// ==========================================================================
// API: DAFTAR SISWA YANG SEDANG MEMINJAM BUKU (AJAX MODAL)
// ==========================================================================
if ($page === 'api_borrowers') {
    auth('admin');
    header('Content-Type: application/json; charset=utf-8');
    $bookId = (int)($_GET['book_id'] ?? 0);

    $bStmt = $pdo->prepare("SELECT id, code, title, quantity, available, source, price FROM books WHERE id = ? LIMIT 1");
    $bStmt->execute([$bookId]);
    $book = $bStmt->fetch();

    if (!$book) {
        echo json_encode(['success' => false, 'message' => 'Buku tidak ditemukan.']);
        exit;
    }

    $borrowedStmt = $pdo->prepare("SELECT l.*, u.name as member_name, u.member_code, u.department, u.phone, u.address 
        FROM loans l 
        JOIN users u ON u.id = l.member_id 
        WHERE l.book_id = ? AND l.status = 'borrowed'
        ORDER BY l.due_date ASC");
    $borrowedStmt->execute([$bookId]);
    $borrowers = $borrowedStmt->fetchAll();

    $data = [];
    $today = date('Y-m-d');
    foreach ($borrowers as $bw) {
        $due = $bw['due_date'];
        $diffDays = (int)round((strtotime($today) - strtotime($due)) / 86400);
        $isOverdue = ($diffDays > 0);
        $data[] = [
            'id' => (int)$bw['id'],
            'member_id' => (int)$bw['member_id'],
            'name' => $bw['member_name'],
            'member_code' => $bw['member_code'] ?: '-',
            'department' => $bw['department'] ?: '-',
            'phone' => $bw['phone'] ?: '',
            'quantity' => (int)$bw['quantity'],
            'copy_serial' => $bw['copy_serial'] ?: '',
            'loan_date' => $bw['loan_date'] ?: $bw['request_date'],
            'due_date' => $due,
            'is_overdue' => $isOverdue,
            'days_diff' => abs($diffDays),
            'status_label' => $isOverdue ? ('Terlambat ' . $diffDays . ' Hari') : ($diffDays === 0 ? 'Jatuh Tempo Hari Ini' : ('Sisa ' . abs($diffDays) . ' Hari'))
        ];
    }

    echo json_encode([
        'success' => true,
        'book' => [
            'id' => (int)$book['id'],
            'code' => $book['code'],
            'title' => $book['title'],
            'source' => $book['source'] ?: 'Dana BOS',
            'price' => !empty($book['price']) ? (int)$book['price'] : null,
            'quantity' => (int)$book['quantity'],
            'available' => (int)$book['available'],
            'borrowed_count' => max(0, (int)$book['quantity'] - (int)$book['available'])
        ],
        'borrowers' => $data
    ]);
    exit;
}

// ==========================================================================
// API: DAFTAR LENGKAP NOMOR SERI EKSEMPLAR BUKU BESERTA STATUS SIRKULASI
// ==========================================================================
if ($page === 'api_book_serials') {
    auth('admin');
    header('Content-Type: application/json; charset=utf-8');

    $bookId = (int)($_GET['book_id'] ?? 0);
    $bStmt = $pdo->prepare("SELECT id, code, title, category, source, price, quantity, available, copy_serials FROM books WHERE id = ?");
    $bStmt->execute([$bookId]);
    $book = $bStmt->fetch();

    if (!$book) {
        echo json_encode(['success' => false, 'message' => 'Data buku tidak ditemukan']);
        exit;
    }

    $serials = !empty($book['copy_serials']) ? json_decode($book['copy_serials'], true) : [];
    if (!is_array($serials)) $serials = [];

    // Cek peminjaman aktif yang mencatat nomor seri untuk buku ini
    $loanStmt = $pdo->prepare("SELECT l.id as loan_id, l.copy_serial, u.name as borrower_name, u.member_code, l.due_date 
                               FROM loans l 
                               JOIN users u ON u.id = l.member_id 
                               WHERE l.book_id = ? AND l.status = 'borrowed' AND l.copy_serial IS NOT NULL");
    $loanStmt->execute([$bookId]);
    $borrowedMap = [];
    foreach ($loanStmt->fetchAll() as $lr) {
        $parts = array_map('trim', explode(',', (string)$lr['copy_serial']));
        foreach ($parts as $p) {
            if ($p !== '') {
                $borrowedMap[$p] = [
                    'loan_id' => (int)$lr['loan_id'],
                    'borrower' => $lr['borrower_name'],
                    'member_code' => $lr['member_code'],
                    'due_date' => $lr['due_date']
                ];
            }
        }
    }

    $items = [];
    $borrowedCount = 0;
    foreach ($serials as $i => $sn) {
        $snClean = trim((string)$sn);
        $isBorrowed = isset($borrowedMap[$snClean]);
        if ($isBorrowed) $borrowedCount++;
        $items[] = [
            'num' => $i + 1,
            'serial' => $snClean,
            'status' => $isBorrowed ? 'borrowed' : 'available',
            'borrower' => $isBorrowed ? $borrowedMap[$snClean]['borrower'] : null,
            'member_code' => $isBorrowed ? $borrowedMap[$snClean]['member_code'] : null,
            'due_date' => $isBorrowed ? $borrowedMap[$snClean]['due_date'] : null,
            'loan_id' => $isBorrowed ? $borrowedMap[$snClean]['loan_id'] : null
        ];
    }

    echo json_encode([
        'success' => true,
        'book' => [
            'id' => (int)$book['id'],
            'code' => $book['code'],
            'title' => $book['title'],
            'category' => $book['category'],
            'quantity' => (int)$book['quantity'],
            'available' => (int)$book['available'],
            'total_serials' => count($serials),
            'borrowed_count' => $borrowedCount,
            'available_count' => max(0, count($serials) - $borrowedCount)
        ],
        'items' => $items
    ]);
    exit;
}

// ==========================================================================
// API: CARI SISWA BERDASARKAN SCAN BARCODE KARTU SISWA (SCANNER GUN)
// ==========================================================================
if ($page === 'api_quick_scan_member') {
    auth('admin');
    header('Content-Type: application/json; charset=utf-8');

    $rawCode = trim($_POST['code'] ?? $_GET['code'] ?? '');
    if ($rawCode === '') {
        echo json_encode(['success' => false, 'message' => 'Kode kartu siswa belum diisi atau tidak terdeteksi.']);
        exit;
    }

    $cleanCode = $rawCode;
    if (preg_match('/id=([0-9]+)/i', $rawCode, $matchId)) {
        $cleanCode = $matchId[1];
    }

    $mStmt = $pdo->prepare("SELECT id, username, name, member_code, department, status, phone FROM users WHERE (username = ? OR member_code = ? OR id = ?) AND role = 'member' LIMIT 1");
    $mStmt->execute([$cleanCode, $cleanCode, (int)$cleanCode]);
    $mem = $mStmt->fetch(PDO::FETCH_ASSOC);

    if (!$mem) {
        $mStmt = $pdo->prepare("SELECT id, username, name, member_code, department, status, phone FROM users WHERE (name LIKE ? OR username LIKE ?) AND role = 'member' LIMIT 1");
        $mStmt->execute(['%' . $cleanCode . '%', '%' . $cleanCode . '%']);
        $mem = $mStmt->fetch(PDO::FETCH_ASSOC);
    }

    if (!$mem) {
        try {
            $memLegacyStmt = $pdo->prepare("SELECT * FROM members WHERE id_anggota = ? OR nama LIKE ? LIMIT 1");
            $memLegacyStmt->execute([$cleanCode, '%' . $cleanCode . '%']);
            $legacy = $memLegacyStmt->fetch(PDO::FETCH_ASSOC);
            if ($legacy) {
                $uStmt = $pdo->prepare("SELECT id, username, name, member_code, department, status, phone FROM users WHERE (username = ? OR member_code = ? OR name = ?) AND role = 'member' LIMIT 1");
                $uStmt->execute([$legacy['id_anggota'], $legacy['id_anggota'], $legacy['nama']]);
                $mem = $uStmt->fetch(PDO::FETCH_ASSOC);
            }
        } catch (Throwable $e) {}
    }

    if (!$mem) {
        echo json_encode(['success' => false, 'message' => 'Siswa/Anggota tidak ditemukan untuk barcode "' . htmlspecialchars($rawCode) . '". Pastikan barcode kartu siswa valid.']);
        exit;
    }

    if ($mem['status'] !== 'active') {
        echo json_encode(['success' => false, 'message' => 'Akun siswa ' . htmlspecialchars($mem['name']) . ' berstatus NON-AKTIF. Peminjaman tidak diizinkan.']);
        exit;
    }

    $activeLoansStmt = $pdo->prepare("SELECT COUNT(*) FROM loans WHERE member_id = ? AND status = 'borrowed'");
    $activeLoansStmt->execute([$mem['id']]);
    $activeLoansCount = (int)$activeLoansStmt->fetchColumn();

    $dept = $mem['department'] ?? '';
    $isGuru = (stripos($dept, 'Guru') !== false || stripos($dept, 'Pendidik') !== false || stripos($dept, 'Tendik') !== false || stripos($dept, 'Pegawai') !== false || stripos($dept, 'Staf') !== false);
    $maxLoans = $isGuru ? 999 : 5;

    echo json_encode([
        'success' => true,
        'member' => [
            'id' => (int)$mem['id'],
            'name' => $mem['name'],
            'username' => $mem['username'],
            'member_code' => $mem['member_code'] ?: $mem['username'],
            'department' => $mem['department'] ?: 'Siswa',
            'active_loans' => $activeLoansCount,
            'active_loans_count' => $activeLoansCount,
            'max_loans' => $maxLoans,
            'is_guru' => $isGuru,
            'is_teacher' => $isGuru
        ]
    ]);
    exit;
}

// ==========================================================================
// API: PROSES PEMINJAMAN KILAT VIA SCANNER GUN
// ==========================================================================
if ($page === 'api_quick_scan_loan') {
    auth('admin');
    header('Content-Type: application/json; charset=utf-8');

    $memberId = (int)($_POST['member_id'] ?? 0);
    $rawBarcode = trim($_POST['book_barcode'] ?? '');

    if ($memberId <= 0) {
        echo json_encode(['success' => false, 'message' => 'Silakan scan kartu siswa terlebih dahulu.']);
        exit;
    }
    if ($rawBarcode === '') {
        echo json_encode(['success' => false, 'message' => 'Kode batang buku belum di-scan.']);
        exit;
    }

    $mStmt = $pdo->prepare("SELECT id, name, department, status FROM users WHERE id = ? AND role = 'member' LIMIT 1");
    $mStmt->execute([$memberId]);
    $mem = $mStmt->fetch(PDO::FETCH_ASSOC);
    if (!$mem || $mem['status'] !== 'active') {
        echo json_encode(['success' => false, 'message' => 'Siswa tidak ditemukan atau status akun tidak aktif.']);
        exit;
    }

    $cStmt = $pdo->prepare("SELECT bc.*, b.id as book_id, b.code as book_code, b.title as book_title, b.available, b.quantity 
        FROM book_copies bc 
        JOIN books b ON b.id = bc.book_id 
        WHERE bc.copy_code = ? LIMIT 1");
    $cStmt->execute([$rawBarcode]);
    $copy = $cStmt->fetch(PDO::FETCH_ASSOC);

    if (!$copy) {
        $bStmt = $pdo->prepare("SELECT id as book_id, code as book_code, title as book_title, available, quantity FROM books WHERE code = ? LIMIT 1");
        $bStmt->execute([$rawBarcode]);
        $bData = $bStmt->fetch(PDO::FETCH_ASSOC);
        if ($bData) {
            $availCopyStmt = $pdo->prepare("SELECT * FROM book_copies WHERE book_id = ? AND status = 'available' ORDER BY id ASC LIMIT 1");
            $availCopyStmt->execute([$bData['book_id']]);
            $copyRow = $availCopyStmt->fetch(PDO::FETCH_ASSOC);
            $copy = array_merge($bData, [
                'id' => $copyRow['id'] ?? 0,
                'copy_code' => $copyRow['copy_code'] ?? ($bData['book_code'] . '-01'),
                'status' => $copyRow['status'] ?? 'available'
            ]);
        }
    }

    if (!$copy) {
        echo json_encode(['success' => false, 'message' => 'Buku dengan kode/nomor seri "' . htmlspecialchars($rawBarcode) . '" tidak ditemukan dalam katalog perpustakaan.']);
        exit;
    }

    if (($copy['status'] ?? '') === 'borrowed') {
        $chkLoan = $pdo->prepare("SELECT l.*, u.name as borrower_name FROM loans l JOIN users u ON u.id = l.member_id WHERE l.book_id = ? AND l.copy_serial = ? AND l.status = 'borrowed' LIMIT 1");
        $chkLoan->execute([$copy['book_id'], $copy['copy_code']]);
        $curLoan = $chkLoan->fetch();
        $borrower = $curLoan['borrower_name'] ?? 'anggota lain';
        echo json_encode(['success' => false, 'message' => 'Nomor seri ' . htmlspecialchars($copy['copy_code']) . ' saat ini SEDANG DIPINJAM oleh ' . htmlspecialchars($borrower) . '. Harap kembalikan terlebih dahulu.']);
        exit;
    }

    if ((int)$copy['available'] <= 0) {
        echo json_encode(['success' => false, 'message' => 'Stok buku "' . htmlspecialchars($copy['book_title']) . '" sedang habis.']);
        exit;
    }

    $pdo->beginTransaction();
    try {
        $dueDate = date('Y-m-d', strtotime('+7 days'));

        $updBook = $pdo->prepare("UPDATE books SET available = available - 1 WHERE id = ? AND available >= 1");
        $updBook->execute([$copy['book_id']]);
        if ($updBook->rowCount() === 0) {
            throw new Exception('Gagal meminjam: stok buku tidak mencukupi.');
        }

        $pdo->prepare("UPDATE book_copies SET status = 'borrowed' WHERE book_id = ? AND copy_code = ?")->execute([$copy['book_id'], $copy['copy_code']]);

        $ins = $pdo->prepare("INSERT INTO loans (member_id, book_id, quantity, copy_serial, request_date, loan_date, due_date, status, notes) VALUES (?, ?, 1, ?, CURDATE(), CURDATE(), ?, 'borrowed', 'Peminjaman Kilat via Scanner Gun')");
        $ins->execute([$memberId, $copy['book_id'], $copy['copy_code'], $dueDate]);
        $loanId = $pdo->lastInsertId();

        $pdo->commit();

        echo json_encode([
            'success' => true,
            'message' => 'Peminjaman berhasil dicatat!',
            'loan' => [
                'id' => (int)$loanId,
                'book_id' => (int)$copy['book_id'],
                'book_title' => $copy['book_title'],
                'book_code' => $copy['book_code'],
                'copy_serial' => $copy['copy_code'],
                'member_name' => $mem['name'],
                'loan_date' => date('d/m/Y'),
                'due_date' => date('d/m/Y', strtotime($dueDate))
            ],
            'book' => [
                'id' => (int)$copy['book_id'],
                'title' => $copy['book_title'],
                'code' => $copy['book_code']
            ],
            'serial_number' => $copy['copy_code'],
            'member' => [
                'id' => (int)$mem['id'],
                'name' => $mem['name'],
                'active_loans' => (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE member_id = " . (int)$memberId . " AND status = 'borrowed'")->fetchColumn(),
                'max_loans' => (stripos($mem['department'] ?? '', 'Guru') !== false ? 999 : 5)
            ]
        ]);
    } catch (Throwable $e) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        echo json_encode(['success' => false, 'message' => $e->getMessage()]);
    }
    exit;
}

// ==========================================================================
// API: PROSES PENGEMBALIAN KILAT VIA SCANNER GUN
// ==========================================================================
if ($page === 'api_quick_scan_return') {
    auth('admin');
    header('Content-Type: application/json; charset=utf-8');

    $rawBarcode = trim($_POST['book_barcode'] ?? '');
    if ($rawBarcode === '') {
        echo json_encode(['success' => false, 'message' => 'Kode batang buku belum di-scan.']);
        exit;
    }

    $lStmt = $pdo->prepare("SELECT l.*, b.id as book_id, b.title as book_title, b.code as book_code, u.name as member_name, u.department, u.username as member_nis 
        FROM loans l
        JOIN books b ON b.id = l.book_id
        JOIN users u ON u.id = l.member_id
        WHERE l.status = 'borrowed' AND l.copy_serial = ?
        ORDER BY l.id DESC LIMIT 1");
    $lStmt->execute([$rawBarcode]);
    $loan = $lStmt->fetch(PDO::FETCH_ASSOC);

    if (!$loan) {
        $lStmt = $pdo->prepare("SELECT l.*, b.id as book_id, b.title as book_title, b.code as book_code, u.name as member_name, u.department, u.username as member_nis 
            FROM loans l
            JOIN books b ON b.id = l.book_id
            JOIN users u ON u.id = l.member_id
            WHERE l.status = 'borrowed' AND (b.code = ? OR l.copy_serial LIKE ?)
            ORDER BY l.due_date ASC LIMIT 1");
        $lStmt->execute([$rawBarcode, '%' . $rawBarcode . '%']);
        $loan = $lStmt->fetch(PDO::FETCH_ASSOC);
    }

    if (!$loan) {
        echo json_encode(['success' => false, 'message' => 'Tidak ada peminjaman aktif untuk kode/nomor seri "' . htmlspecialchars($rawBarcode) . '". Buku ini mungkin sudah dikembalikan atau belum pernah dipinjam.']);
        exit;
    }

    $pdo->beginTransaction();
    try {
        $pdo->prepare("UPDATE loans SET status = 'returned', return_date = CURDATE() WHERE id = ?")->execute([$loan['id']]);

        $pdo->prepare("UPDATE books SET available = LEAST(quantity, available + ?) WHERE id = ?")->execute([$loan['quantity'], $loan['book_id']]);

        if (!empty($loan['copy_serial'])) {
            $pdo->prepare("UPDATE book_copies SET status = 'available' WHERE book_id = ? AND copy_code = ?")->execute([$loan['book_id'], $loan['copy_serial']]);
        }

        $pdo->commit();

        $today = date('Y-m-d');
        $diffDays = (int)round((strtotime($today) - strtotime($loan['due_date'])) / 86400);
        $isOverdue = ($diffDays > 0);

        echo json_encode([
            'success' => true,
            'message' => 'Buku berhasil dikembalikan!',
            'return' => [
                'id' => (int)$loan['id'],
                'book_title' => $loan['book_title'],
                'book_code' => $loan['book_code'],
                'copy_serial' => $loan['copy_serial'] ?: $loan['book_code'],
                'member_name' => $loan['member_name'],
                'department' => $loan['department'] ?: 'Siswa',
                'member_nis' => $loan['member_nis'] ?: '-',
                'loan_date' => date('d/m/Y', strtotime($loan['loan_date'])),
                'due_date' => date('d/m/Y', strtotime($loan['due_date'])),
                'return_date' => date('d/m/Y'),
                'is_overdue' => $isOverdue,
                'overdue_days' => max(0, $diffDays)
            ],
            'book' => [
                'id' => (int)$loan['book_id'],
                'title' => $loan['book_title'],
                'code' => $loan['book_code']
            ],
            'serial_number' => $loan['copy_serial'] ?: $loan['book_code'],
            'member' => [
                'name' => $loan['member_name'],
                'member_code' => $loan['member_nis'] ?: '-'
            ]
        ]);
    } catch (Throwable $e) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        echo json_encode(['success' => false, 'message' => $e->getMessage()]);
    }
    exit;
}

// ==========================================================================
// API: SCAN KARTU ANGGOTA UNTUK PRESENSI KUNJUNGAN (KAMERA / BARCODE)
// ==========================================================================
if ($page === 'api_scan_visit') {
    auth('admin');
    header('Content-Type: application/json; charset=utf-8');

    $rawCode = trim($_POST['code'] ?? $_GET['code'] ?? '');
    $purpose = trim($_POST['purpose'] ?? $_GET['purpose'] ?? 'Membaca Koleksi Buku');
    if ($purpose === '') $purpose = 'Membaca Koleksi Buku';

    if ($rawCode === '') {
        echo json_encode(['success' => false, 'message' => 'Kode kartu tidak terdeteksi. Silakan coba scan ulang.']);
        exit;
    }

    $cleanCode = $rawCode;
    if (preg_match('/id=([0-9]+)/i', $rawCode, $matchId)) {
        $cleanCode = $matchId[1];
    } elseif (preg_match('/([A-Za-z0-9\-_]{3,})/i', $rawCode, $matchCode)) {
        $cleanCode = $matchCode[1];
    }

    $stmt = $pdo->prepare("SELECT id, name, department, member_code, username, status, photo 
        FROM users 
        WHERE (member_code = ? OR username = ? OR id = ? OR member_code = ?) AND role = 'member' 
        LIMIT 1");
    $stmt->execute([$cleanCode, $cleanCode, (int)$cleanCode, $rawCode]);
    $member = $stmt->fetch();

    if (!$member) {
        echo json_encode([
            'success' => false, 
            'code' => $rawCode,
            'message' => 'Kartu tidak terdaftar dalam sistem (Kode: "' . e($rawCode) . '").'
        ]);
        exit;
    }

    if ($member['status'] === 'inactive') {
        echo json_encode([
            'success' => false, 
            'member' => ['name' => $member['name'], 'member_code' => $member['member_code']],
            'message' => 'Akun anggota "' . $member['name'] . '" sedang NONAKTIF. Kunjungan tidak dapat dicatat.'
        ]);
        exit;
    }

    // Periksa apakah anggota sudah check-in hari ini dan belum check-out (time_out masih kosong)
    $chkVisit = $pdo->prepare("SELECT id, time_in, purpose FROM visits 
        WHERE member_id = ? AND visit_date = CURDATE() AND (time_out IS NULL OR time_out = '00:00:00') 
        ORDER BY id DESC LIMIT 1");
    $chkVisit->execute([$member['id']]);
    $actVisit = $chkVisit->fetch();

    $photoUrl = get_member_photo_url($member);
    $nowTime = date('H:i:s');

    if ($actVisit) {
        // SCAN KEDUA: CHECK-OUT / KEPULANGAN / AKHIR KUNJUNGAN
        $visitId = (int)$actVisit['id'];
        $upd = $pdo->prepare("UPDATE visits SET time_out = CURTIME() WHERE id = ?");
        $upd->execute([$visitId]);
        $actionType = 'checkout';
        $message = 'Check-out berhasil! Terima kasih atas kunjungan Anda hari ini.';
        $timeIn = $actVisit['time_in'];
        $timeOut = $nowTime;
        $savedPurpose = $actVisit['purpose'];
    } else {
        // SCAN PERTAMA: CHECK-IN / KEDATANGAN / AWAL KUNJUNGAN
        $ins = $pdo->prepare("INSERT INTO visits (member_id, visitor_name, department, purpose, visit_date, time_in) VALUES (?, ?, ?, ?, CURDATE(), CURTIME())");
        $ins->execute([$member['id'], $member['name'], $member['department'] ?: 'Anggota', $purpose]);
        $visitId = (int)$pdo->lastInsertId();
        $actionType = 'checkin';
        $message = 'Presensi kedatangan berhasil dicatat! Selamat datang di perpustakaan.';
        $timeIn = $nowTime;
        $timeOut = null;
        $savedPurpose = $purpose;
    }

    $todayCount = (int)$pdo->query("SELECT COUNT(*) FROM visits WHERE visit_date = CURDATE()")->fetchColumn();
    $activeNow = (int)$pdo->query("SELECT COUNT(*) FROM visits WHERE visit_date = CURDATE() AND (time_out IS NULL OR time_out = '00:00:00')")->fetchColumn();

    echo json_encode([
        'success' => true,
        'action_type' => $actionType, // 'checkin' (scan pertama) atau 'checkout' (scan kedua)
        'message' => $message,
        'member' => [
            'id' => (int)$member['id'],
            'name' => $member['name'],
            'member_code' => $member['member_code'] ?: $member['username'],
            'department' => $member['department'] ?: 'Anggota',
            'photo' => $photoUrl,
            'time_in' => $timeIn,
            'time_out' => $timeOut,
            'purpose' => $savedPurpose,
            'visit_id' => $visitId
        ],
        'stats' => [
            'total_today' => $todayCount,
            'active_now' => $activeNow,
            'checked_out' => max(0, $todayCount - $activeNow)
        ]
    ]);
    exit;
}

