function render_table_pagination($currentPage, $totalPages, $totalRows, $perPage, $queryParams = []) {
    if ($totalRows <= 0) return;
    
    $from = ($currentPage - 1) * $perPage + 1;
    $to = min($currentPage * $perPage, $totalRows);
    ?>
    <div class="pagination-wrapper no-print" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin-top:16px;padding-top:14px;border-top:1px solid #e2e8f0;">
        <div style="font-size:12.5px;color:#64748b;">
            Menampilkan <b><?=$from?></b> - <b><?=$to?></b> dari <b><?=$totalRows?></b> data (Halaman <b><?=$currentPage?></b> dari <b><?=$totalPages?></b>)
        </div>
        <?php if ($totalPages > 1): ?>
            <div style="display:flex;align-items:center;gap:4px;flex-wrap:wrap;">
                <!-- Tombol Halaman Sebelumnya -->
                <?php if ($currentPage > 1): ?>
                    <?php $prevParams = array_merge($queryParams, ['p' => $currentPage - 1]); ?>
                    <a href="<?=u('index.php?' . http_build_query($prevParams))?>" class="btn btn-sm btn-outline-secondary" style="font-size:12px;padding:5px 10px;font-weight:600;display:inline-flex;align-items:center;gap:4px;border-radius:6px;" title="Halaman Sebelumnya">
                        ← Sebelumnya
                    </a>
                <?php else: ?>
                    <span class="btn btn-sm" style="font-size:12px;padding:5px 10px;color:#94a3b8;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;cursor:not-allowed;pointer-events:none;">
                        ← Sebelumnya
                    </span>
                <?php endif; ?>

                <!-- Nomor Halaman -->
                <?php
                $start = max(1, $currentPage - 2);
                $end = min($totalPages, $currentPage + 2);
                if ($start > 1) {
                    $firstParams = array_merge($queryParams, ['p' => 1]);
                    echo '<a href="' . u('index.php?' . http_build_query($firstParams)) . '" class="btn btn-sm btn-outline-secondary" style="font-size:12px;padding:5px 9px;font-weight:600;min-width:32px;text-align:center;border-radius:6px;">1</a>';
                    if ($start > 2) {
                        echo '<span style="color:#94a3b8;padding:0 2px;">...</span>';
                    }
                }
                for ($i = $start; $i <= $end; $i++):
                    $pageParams = array_merge($queryParams, ['p' => $i]);
                    if ($i === $currentPage):
                        echo '<span class="btn btn-sm btn-primary" style="font-size:12px;padding:5px 9px;font-weight:700;min-width:32px;text-align:center;border-radius:6px;">' . $i . '</span>';
                    else:
                        echo '<a href="' . u('index.php?' . http_build_query($pageParams)) . '" class="btn btn-sm btn-outline-secondary" style="font-size:12px;padding:5px 9px;font-weight:600;min-width:32px;text-align:center;border-radius:6px;">' . $i . '</a>';
                    endif;
                endfor;
                if ($end < $totalPages) {
                    if ($end < $totalPages - 1) {
                        echo '<span style="color:#94a3b8;padding:0 2px;">...</span>';
                    }
                    $lastParams = array_merge($queryParams, ['p' => $totalPages]);
                    echo '<a href="' . u('index.php?' . http_build_query($lastParams)) . '" class="btn btn-sm btn-outline-secondary" style="font-size:12px;padding:5px 9px;font-weight:600;min-width:32px;text-align:center;border-radius:6px;">' . $totalPages . '</a>';
                }
                ?>

                <!-- Tombol Halaman Berikutnya -->
                <?php if ($currentPage < $totalPages): ?>
                    <?php $nextParams = array_merge($queryParams, ['p' => $currentPage + 1]); ?>
                    <a href="<?=u('index.php?' . http_build_query($nextParams))?>" class="btn btn-sm btn-outline-secondary" style="font-size:12px;padding:5px 10px;font-weight:600;display:inline-flex;align-items:center;gap:4px;border-radius:6px;" title="Halaman Selanjutnya">
                        Selanjutnya →
                    </a>
                <?php else: ?>
                    <span class="btn btn-sm" style="font-size:12px;padding:5px 10px;color:#94a3b8;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;cursor:not-allowed;pointer-events:none;">
                        Selanjutnya →
                    </span>
                <?php endif; ?>
            </div>
        <?php endif; ?>
    </div>
    <?php
}

function render_public_footer() {
    $defaultLeft = '© ' . date('Y') . ' <b>' . SCHOOL . '</b> · Perpustakaan Digital Berbasis Intranet Cepat';
    $defaultRight = 'Akses Lokal Host & Wi-Fi Sekolah · Respons Cepat 0ms CDN';

    $footerLeft = get_setting('footer_text_left', $defaultLeft);
    $footerRight = get_setting('footer_text_right', $defaultRight);

    if ($footerLeft === '') $footerLeft = $defaultLeft;
    if ($footerRight === '') $footerRight = $defaultRight;

    $footerLeft = str_replace(['{YEAR}', '{TAHUN}', '{SEKOLAH}', '{SCHOOL}'], [date('Y'), date('Y'), SCHOOL, SCHOOL], $footerLeft);
    $footerRight = str_replace(['{YEAR}', '{TAHUN}', '{SEKOLAH}', '{SCHOOL}'], [date('Y'), date('Y'), SCHOOL, SCHOOL], $footerRight);
    ?>
        </main>
        <footer style="background:var(--navy-dark);color:rgba(255,255,255,0.7);text-align:center;padding:24px 20px;font-size:12.5px;margin-top:40px;border-top:1px solid rgba(255,255,255,0.1);">
            <div style="max-width:1200px;margin:auto;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;">
                <div><?=$footerLeft?></div>
                <div><?=$footerRight?></div>
            </div>
            <?=get_developer_attribution_html('public')?>
        </footer>
        <?php render_developer_guard_script(); ?>
        <script>
            document.querySelectorAll('[data-confirm]').forEach(el => {
                el.onclick = (e) => { if (!confirm(el.dataset.confirm)) e.preventDefault(); };
            });
            // Public Mobile Navigation Toggle
            (function() {
                var toggle = document.getElementById('pubNavToggle');
                var nav = document.getElementById('pubNav');
                var backdrop = document.getElementById('pubNavBackdrop');
                if (toggle && nav) {
                    toggle.addEventListener('click', function() {
                        toggle.classList.toggle('active');
                        nav.classList.toggle('open');
                        if (backdrop) backdrop.classList.toggle('active');
                        document.body.classList.toggle('nav-locked');
                    });
                    if (backdrop) {
                        backdrop.addEventListener('click', function() {
                            toggle.classList.remove('active');
                            nav.classList.remove('open');
                            backdrop.classList.remove('active');
                            document.body.classList.remove('nav-locked');
                        });
                    }
                    nav.querySelectorAll('a').forEach(function(a) {
                        a.addEventListener('click', function() {
                            toggle.classList.remove('active');
                            nav.classList.remove('open');
                            if (backdrop) backdrop.classList.remove('active');
                            document.body.classList.remove('nav-locked');
                        });
                    });
                }
            })();
        </script>
    </body>
    </html>
    <?php
}

