            <?php render_book_serials_modal(); ?>
            <!-- Global HTML5 QR Code & Barcode Scanner Library -->
            <script src="<?=u('assets/js/html5-qrcode.min.js')?>"></script>
        <?php endif; ?>
        <!-- Global Akses LAN & Smartphone Modal Component -->
        <?php render_lan_access_modal(); ?>
        <script>
            document.querySelectorAll('[data-confirm]').forEach(el => {
                el.onclick = (e) => { if (!confirm(el.dataset.confirm)) e.preventDefault(); };
            });
            // App Layout Mobile Drawer Sidebar Toggle
            (function() {
                var toggleBtn = document.getElementById('sidebarToggleBtn');
                var closeBtn = document.getElementById('sidebarCloseBtn');
                var sidebar = document.getElementById('appSidebar');
                var backdrop = document.getElementById('sidebarBackdrop');

                function openSidebar() {
                    if (sidebar) sidebar.classList.add('sidebar-open');
                    if (backdrop) backdrop.classList.add('active');
                    document.body.classList.add('nav-locked');
                }
                function closeSidebar() {
                    if (sidebar) sidebar.classList.remove('sidebar-open');
                    if (backdrop) backdrop.classList.remove('active');
                    document.body.classList.remove('nav-locked');
                }

                if (toggleBtn) toggleBtn.addEventListener('click', openSidebar);
                if (closeBtn) closeBtn.addEventListener('click', closeSidebar);
                if (backdrop) backdrop.addEventListener('click', closeSidebar);

                if (sidebar) {
                    sidebar.querySelectorAll('.sidebar-link').forEach(function(l) {
                        l.addEventListener('click', function() {
                            if (window.innerWidth <= 768) closeSidebar();
                        });
                    });
                }
            })();
        </script>
    </body>
    </html>
    <?php
}

