                        <a href="<?=e($lanUrl)?>" target="_blank" style="background:#f8fafc;color:#0284c7;border:1px solid #cbd5e1;padding:6px 12px;border-radius:6px;font-size:11.5px;font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:3px;">
