    function openLanAccessModal() {
        var m = document.getElementById('lanAccessModal');
        if (m) m.style.display = 'flex';
    }
    function closeLanAccessModal() {
        var m = document.getElementById('lanAccessModal');
        if (m) m.style.display = 'none';
    }
    function copyLanUrl() {
        var inp = document.getElementById('lanUrlInput');
        var btnText = document.getElementById('btnCopyLanText');
        if (inp) {
            inp.select();
            inp.setSelectionRange(0, 99999);
            try {
                navigator.clipboard.writeText(inp.value).then(function() {
                    if (btnText) btnText.textContent = '✓ Tersalin!';
                    setTimeout(function() { if (btnText) btnText.textContent = 'Salin URL'; }, 2000);
                }).catch(function() {
                    document.execCommand('copy');
                    if (btnText) btnText.textContent = '✓ Tersalin!';
                    setTimeout(function() { if (btnText) btnText.textContent = 'Salin URL'; }, 2000);
                });
            } catch(e) {
                document.execCommand('copy');
                if (btnText) btnText.textContent = '✓ Tersalin!';
                setTimeout(function() { if (btnText) btnText.textContent = 'Salin URL'; }, 2000);
            }
        }
    }
    </script>
    <?php
}

