                        <?=icon('clock', '', 14)?> Rincian Siswa Peminjam Aktif
                    </div>
                    <h3 id="modalBookTitle" style="margin:4px 0 0;font-size:17px;font-weight:800;color:var(--navy);">Judul Buku</h3>
                    <div id="modalBookMeta" style="font-size:12px;color:var(--text-muted);margin-top:2px;">Memuat rincian buku...</div>
                </div>
                <button type="button" onclick="closeBorrowersModal()" class="modal-close-btn" aria-label="Tutup">&times;</button>
            </div>
            
            <div id="modalLoading" style="text-align:center;padding:40px;color:var(--text-muted);">
                <div style="display:inline-block;width:32px;height:32px;border:3px solid #e2e8f0;border-top-color:var(--primary);border-radius:50%;animation:spin 0.8s linear infinite;margin-bottom:12px;"></div>
                <div style="font-size:13px;font-weight:600;">Mengambil daftar siswa peminjam...</div>
            </div>

            <div id="modalEmpty" style="display:none;text-align:center;padding:40px;color:#64748b;">
                <div style="font-size:36px;margin-bottom:8px;">📚</div>
                <h4 style="margin:0 0 6px;color:var(--navy);font-size:15px;font-weight:800;">Tidak Ada Siswa yang Sedang Meminjam</h4>
                <p style="margin:0;font-size:12.5px;color:var(--text-muted);">Saat ini semua eksemplar buku ini berada di perpustakaan dan siap dipinjam.</p>
            </div>

            <div id="modalTableContainer" style="display:none;max-height:420px;overflow-y:auto;padding:0;">
                <table class="modern-table" style="margin:0;font-size:12.5px;">
                    <thead>
                        <tr style="background:#f8fafc;position:sticky;top:0;z-index:2;">
                            <th style="width:30px;">No</th>
                            <th>Nama Siswa / Peminjam</th>
                            <th>Jurusan / Kelas</th>
                            <th>Kontak / WhatsApp</th>
                            <th>Tgl Pinjam</th>
                            <th>Jatuh Tempo</th>
                            <th>Status Pengembalian</th>
                            <th style="text-align:center;">Jumlah</th>
                            <th style="text-align:center;">Aksi</th>
                        </tr>
                    </thead>
                    <tbody id="modalBorrowersList">
                    </tbody>
                </table>
            </div>

            <div class="borrowers-modal-footer">
                <span id="modalSummaryText" style="font-size:12px;color:var(--text-muted);font-weight:600;"></span>
                <div style="display:flex;gap:8px;">
                    <a href="<?=u('index.php?page=admin_loans&tab=borrowed')?>" class="btn btn-outline-primary btn-sm" style="font-size:12px;">
                        Buka Manajemen Peminjaman ↗
                    </a>
                    <button type="button" class="btn btn-secondary btn-sm" onclick="closeBorrowersModal()">Tutup</button>
                </div>
            </div>
        </div>
    </div>

    <style>
    @keyframes spin { to { transform: rotate(360deg); } }
    </style>

    <script>
    function openBorrowersModal(bookId, bookTitle) {
        const modal = document.getElementById('borrowersModal');
        if (!modal) return;
        const titleEl = document.getElementById('modalBookTitle');
        const metaEl = document.getElementById('modalBookMeta');
        const loadingEl = document.getElementById('modalLoading');
        const emptyEl = document.getElementById('modalEmpty');
        const tableContEl = document.getElementById('modalTableContainer');
        const listEl = document.getElementById('modalBorrowersList');
        const summaryEl = document.getElementById('modalSummaryText');

        titleEl.textContent = bookTitle || 'Detail Peminjam Buku';
        metaEl.textContent = 'Memuat rincian siswa peminjam...';
        loadingEl.style.display = 'block';
        emptyEl.style.display = 'none';
        tableContEl.style.display = 'none';
        listEl.innerHTML = '';
        summaryEl.textContent = '';
        modal.style.display = 'flex';

        fetch('<?=u("index.php?page=api_borrowers&book_id=")?>' + encodeURIComponent(bookId))
            .then(res => res.json())
            .then(data => {
                loadingEl.style.display = 'none';
                if (!data.success || !data.borrowers || data.borrowers.length === 0) {
                    emptyEl.style.display = 'block';
                    metaEl.textContent = (data.book ? 'Kode: ' + data.book.code : '') + ' · 0 Eksemplar Sedang Dipinjam';
                    return;
                }

                metaEl.textContent = 'Kode: ' + data.book.code + ' · Total ' + data.borrowers.length + ' Transaksi Peminjaman (' + data.book.borrowed_count + ' Eksemplar Sedang Dipinjam)';
                summaryEl.textContent = 'Menampilkan ' + data.borrowers.length + ' siswa peminjam aktif.';
                
                let html = '';
                data.borrowers.forEach((b, idx) => {
                    const statusBadge = b.is_overdue 
                        ? `<span class="badge badge-red" style="font-size:11px;">⚠️ ${b.status_label}</span>`
                        : `<span class="badge badge-green" style="font-size:11px;">✓ ${b.status_label}</span>`;
                    
                    const waClean = (b.phone || '').replace(/[^0-9]/g, '');
                    let waBtn = '';
                    if (waClean) {
                        const waInt = waClean.startsWith('0') ? '62' + waClean.substring(1) : waClean;
                        const schoolWaName = <?=json_encode(get_school_name())?>;
                        const waText = encodeURIComponent(`Halo ${b.name}, pengingat dari Perpustakaan ${schoolWaName} terkait peminjaman buku "${data.book.title}". Batas tanggal kembali: ${b.due_date}. Mohon dikembalikan tepat waktu. Terima kasih.`);
                        waBtn = `<a href="https://wa.me/${waInt}?text=${waText}" target="_blank" class="btn btn-sm btn-outline-success" style="font-size:11px;padding:2px 8px;margin-top:3px;display:inline-flex;align-items:center;gap:4px;border-color:#22c55e;color:#15803d;text-decoration:none;" title="Kirim Pesan WhatsApp">
                            📱 Chat WA
                        </a>`;
                    }

                    html += `<tr>
                        <td>${idx + 1}</td>
                        <td>
                            <div style="font-weight:700;color:var(--navy);font-size:13px;">${escapeHtml(b.name)}</div>
                            <small style="color:var(--text-muted);">NISN / ID: ${escapeHtml(b.member_code)}</small>
                            ${b.copy_serial ? `<div style="margin-top:3px;"><span class="badge" style="background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;font-family:monospace;font-size:11px;padding:1px 6px;">🏷️ No. Seri: ${escapeHtml(b.copy_serial)}</span></div>` : ''}
                        </td>
                        <td><span class="badge" style="background:#f1f5f9;color:#334155;border:1px solid #cbd5e1;">${escapeHtml(b.department)}</span></td>
                        <td>
                            <div>${escapeHtml(b.phone || '-')}</div>
                            ${waBtn}
                        </td>
                        <td>${escapeHtml(b.loan_date)}</td>
                        <td><b style="color:${b.is_overdue?'var(--red)':'var(--navy)'};">${escapeHtml(b.due_date)}</b></td>
                        <td>${statusBadge}</td>
                        <td style="text-align:center;"><b style="color:#c2410c;">${b.quantity}</b> eks</td>
                        <td style="text-align:center;">
                            <a href="<?=u('index.php?page=admin_loans&q=')?>${encodeURIComponent(b.name)}" target="_blank" class="btn btn-sm btn-outline-primary" style="font-size:11px;padding:3px 8px;">
                                Lihat Transaksi ↗
                            </a>
                        </td>
                    </tr>`;
                });

                listEl.innerHTML = html;
                tableContEl.style.display = 'block';
            })
            .catch(err => {
                loadingEl.style.display = 'none';
                emptyEl.style.display = 'block';
                emptyEl.innerHTML = '<div style="color:var(--red);padding:16px;">Gagal memuat data peminjam. Silakan coba kembali.</div>';
            });
    }

    function closeBorrowersModal() {
        const modal = document.getElementById('borrowersModal');
        if (modal) modal.style.display = 'none';
    }

    function escapeHtml(str) {
        if (!str) return '';
        return String(str).replace(/[&<>"']/g, function(m) {
            return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m];
        });
    }

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') closeBorrowersModal();
    });
    </script>
    <?php
}

