    <script>
    let bsmCurrentItems = [];
    let bsmCurrentBook = null;

    function openBookSerialsModal(bookId, bookTitle, bookCode, fallbackSerials) {
        const modal = document.getElementById('bookSerialsModal');
        if (!modal) return;
        const titleEl = document.getElementById('bsmBookTitle');
        const metaEl = document.getElementById('bsmBookMeta');
        const loadingEl = document.getElementById('bsmLoading');
        const emptyEl = document.getElementById('bsmEmpty');
        const gridContEl = document.getElementById('bsmGridContainer');
        const gridEl = document.getElementById('bsmGrid');
        const searchInput = document.getElementById('bsmSearchInput');
        const statFilter = document.getElementById('bsmStatFilter');

        titleEl.textContent = bookTitle || 'Detail Nomor Seri Eksemplar';
        metaEl.textContent = (bookCode ? 'Kode Buku: ' + bookCode : 'Memuat data buku...');
        if (searchInput) searchInput.value = '';
        if (statFilter) statFilter.style.display = 'none';

        bsmCurrentBook = { id: bookId, title: bookTitle, code: bookCode };
        bsmCurrentItems = [];

        // Instant render dari fallback jika ada
        if (Array.isArray(fallbackSerials) && fallbackSerials.length > 0) {
            bsmCurrentItems = fallbackSerials.map((s, idx) => ({
                num: idx + 1,
                serial: String(s).trim(),
                status: 'available',
                borrower: null,
                due_date: null
            }));
            renderBsmGrid(bsmCurrentItems);
            updateBsmStats(bsmCurrentItems.length, bsmCurrentItems.length, 0);
            gridContEl.style.display = 'block';
            emptyEl.style.display = 'none';
        } else {
            gridContEl.style.display = 'none';
            loadingEl.style.display = 'block';
            emptyEl.style.display = 'none';
        }

        modal.style.display = 'flex';

        // Fetch live data dari server untuk status terkini (tersedia / dipinjam)
        fetch('<?=u("index.php?page=api_book_serials&book_id=")?>' + encodeURIComponent(bookId))
            .then(res => res.json())
            .then(data => {
                loadingEl.style.display = 'none';
                if (!data.success || !data.items || data.items.length === 0) {
                    if (bsmCurrentItems.length === 0) {
                        emptyEl.style.display = 'block';
                        gridContEl.style.display = 'none';
                        updateBsmStats(0, 0, 0);
                    }
                    return;
                }

                bsmCurrentBook = data.book;
                bsmCurrentItems = data.items;
                metaEl.textContent = 'Kode Buku: ' + data.book.code + ' · Kategori: ' + (data.book.category || 'Umum') + ' · Total Eksemplar: ' + data.book.quantity + ' buah';
                updateBsmStats(data.book.total_serials, data.book.available_count, data.book.borrowed_count);
                renderBsmGrid(bsmCurrentItems);
                gridContEl.style.display = 'block';
                emptyEl.style.display = 'none';
            })
            .catch(err => {
                loadingEl.style.display = 'none';
                if (bsmCurrentItems.length === 0) {
                    emptyEl.style.display = 'block';
                    emptyEl.innerHTML = '<div style="color:var(--red);padding:16px;">Gagal memuat nomor seri eksemplar.</div>';
                }
            });
    }

    function renderBsmGrid(items) {
        const gridEl = document.getElementById('bsmGrid');
        const footerText = document.getElementById('bsmFooterText');
        if (!gridEl) return;

        if (!items || items.length === 0) {
            gridEl.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:30px;color:#94a3b8;font-weight:600;">Tidak ada nomor seri yang cocok dengan pencarian.</div>';
            if (footerText) footerText.textContent = '0 nomor seri ditampilkan';
            return;
        }

        let html = '';
        items.forEach(it => {
            const isBorrowed = (it.status === 'borrowed');
            const statusBadge = isBorrowed
                ? `<span class="badge" style="background:#fff7ed;color:#c2410c;border:1px solid #fed7aa;font-size:10.5px;padding:1px 6px;">⏳ Dipinjam</span>`
                : `<span class="badge badge-green" style="font-size:10.5px;padding:1px 6px;">✓ Tersedia</span>`;

            const cardBorder = isBorrowed ? 'border:1px solid #fdba74;background:#fffaf5;' : 'border:1px solid #e2e8f0;background:#ffffff;';

            html += `<div class="bsm-card" style="${cardBorder}border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;gap:6px;transition:all 0.15s;box-shadow:0 1px 2px rgba(0,0,0,0.04);">
                <div style="display:flex;align-items:center;justify-content:space-between;">
                    <span class="badge" style="background:#f1f5f9;color:#64748b;font-size:10px;padding:1px 6px;">#${it.num}</span>
                    ${statusBadge}
                </div>
                <div style="display:flex;align-items:center;justify-content:space-between;gap:6px;margin:2px 0;">
                    <span style="font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-weight:700;font-size:13px;color:#0f172a;letter-spacing:0.5px;">${escapeHtml(it.serial)}</span>
                    <button type="button" onclick="copySingleSerial('${escapeHtml(it.serial)}', this)" title="Salin nomor seri ini" style="border:1px solid #cbd5e1;background:#f8fafc;border-radius:4px;cursor:pointer;color:#475569;padding:2px 6px;font-size:11px;display:inline-flex;align-items:center;gap:3px;" onmouseover="this.style.background='#e2e8f0'" onmouseout="this.style.background='#f8fafc'">
                        📋 Salin
                    </button>
                </div>
                ${isBorrowed && it.borrower ? `
                    <div style="font-size:11px;color:#9a3412;background:#ffedd5;padding:4px 8px;border-radius:4px;margin-top:2px;line-height:1.4;">
                        👤 <b>${escapeHtml(it.borrower)}</b><br>
                        <span style="color:#7c2d12;">Tempo: ${escapeHtml(it.due_date || '-')}</span>
                    </div>
                ` : ''}
            </div>`;
        });

        gridEl.innerHTML = html;
        if (footerText) {
            footerText.textContent = 'Menampilkan ' + items.length + ' nomor seri eksemplar fisik.';
        }
    }

    function updateBsmStats(total, avail, borrowed) {
        const tEl = document.getElementById('bsmStatTotal');
        const aEl = document.getElementById('bsmStatAvail');
        const bEl = document.getElementById('bsmStatBorrowed');
        if (tEl) tEl.innerHTML = 'Total: <b>' + total + '</b> Seri';
        if (aEl) aEl.innerHTML = '✓ Tersedia: <b>' + avail + '</b>';
        if (bEl) bEl.innerHTML = '⏳ Dipinjam: <b>' + borrowed + '</b>';
    }

    function filterBookSerials(query) {
        query = (query || '').trim().toLowerCase();
        const statFilter = document.getElementById('bsmStatFilter');
        if (!bsmCurrentItems || bsmCurrentItems.length === 0) return;

        if (query === '') {
            if (statFilter) statFilter.style.display = 'none';
            renderBsmGrid(bsmCurrentItems);
            return;
        }

        const filtered = bsmCurrentItems.filter(it => {
            const matchSerial = (it.serial || '').toLowerCase().includes(query);
            const matchBorrower = (it.borrower || '').toLowerCase().includes(query);
            return matchSerial || matchBorrower;
        });

        if (statFilter) {
            statFilter.style.display = 'inline-block';
            statFilter.textContent = 'Hasil pencarian: ' + filtered.length + ' seri';
        }
        renderBsmGrid(filtered);
    }

    function copyAllBookSerials() {
        if (!bsmCurrentItems || bsmCurrentItems.length === 0) return;
        const text = bsmCurrentItems.map(it => it.serial).join(', ');
        navigator.clipboard.writeText(text).then(() => {
            const btn = document.getElementById('bsmCopyAllBtn');
            if (btn) {
                const orig = btn.innerHTML;
                btn.innerHTML = '✓ Berhasil Disalin!';
                btn.style.borderColor = '#16a34a';
                btn.style.color = '#16a34a';
                setTimeout(() => {
                    btn.innerHTML = orig;
                    btn.style.borderColor = '';
                    btn.style.color = '';
                }, 2000);
            }
        });
    }

    function copySingleSerial(serialText, btnEl) {
        navigator.clipboard.writeText(serialText).then(() => {
            if (btnEl) {
                const orig = btnEl.innerHTML;
                btnEl.innerHTML = '✓ Disalin';
                btnEl.style.color = '#16a34a';
                setTimeout(() => {
                    btnEl.innerHTML = orig;
                    btnEl.style.color = '';
                }, 1500);
            }
        });
    }

    function closeBookSerialsModal() {
        const modal = document.getElementById('bookSerialsModal');
        if (modal) modal.style.display = 'none';
    }

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') closeBookSerialsModal();
    });
    </script>
    <?php
}

