// ==========================================================================
// 2. PAGE: LOGIN (CHOICE ADMIN VS ANGGOTA)
// ==========================================================================
if ($page === 'login') {
    if (!empty($_SESSION['user'])) {
        header('Location: ' . u('index.php?page=' . ($_SESSION['user']['role']==='admin'?'admin':'member')));
        exit;
    }

    $roleChoice = $_GET['role'] ?? null;
    $clientIp = get_client_ip();
    $ipFails = get_login_failed_attempts('', $clientIp);
    $ipLockRemaining = get_login_lockout_remaining('', $clientIp);

    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $uInput = trim($_POST['username'] ?? '');
        $pInput = (string)($_POST['password'] ?? '');

        // 1. Anti-Brute Force Protection Check
        $lockSec = get_login_lockout_remaining($uInput, $clientIp);
        $fails = get_login_failed_attempts($uInput, $clientIp);

        if ($fails >= MAX_LOGIN_ATTEMPTS && $lockSec > 0) {
            $lockMin = ceil($lockSec / 60);
            flash("⚠️ Akses Dibekukan Sementara: Terdeteksi {$fails} kali percobaan login gagal. Demi melindungi akun dari upaya pembobolan (brute-force), akses dibekukan selama {$lockMin} menit. Silakan coba kembali nanti.", 'error');
            header('Location: ' . u('index.php?page=login' . ($roleChoice ? '&role=' . $roleChoice : '')));
            exit;
        }

        $stmt = $pdo->prepare("SELECT * FROM users WHERE (username = ? OR member_code = ?) LIMIT 1");
        $stmt->execute([$uInput, $uInput]);
        $user = $stmt->fetch();

        if ($user && password_verify($pInput, $user['password_hash'])) {
            if ($user['status'] === 'inactive') {
                record_login_attempt($uInput, $clientIp, false);
                flash('Akun Anda saat ini dinonaktifkan oleh Administrator perpustakaan. Silakan hubungi petugas perpustakaan.', 'error');
                header('Location: ' . u('index.php?page=login' . ($roleChoice ? '&role=' . $roleChoice : '')));
                exit;
            }
            if ($user['status'] === 'pending') {
                record_login_attempt($uInput, $clientIp, false);
                flash('Pendaftaran akun Anda masih menunggu verifikasi oleh Administrator perpustakaan.', 'warning');
                header('Location: ' . u('index.php?page=login' . ($roleChoice ? '&role=' . $roleChoice : '')));
                exit;
            }

            // Regenerasi ID Sesi untuk mencegah Session Fixation
            session_regenerate_id(true);

            // Bersihkan jejak percobaan gagal dan catat keberhasilan login
            record_login_attempt($uInput, $clientIp, true);

            // Update riwayat login pada tabel users
            try {
                $pdo->prepare("UPDATE users SET last_login_at = NOW(), last_login_ip = ? WHERE id = ?")->execute([$clientIp, $user['id']]);
            } catch (Throwable $e) {}

            // Set data sesi terlindungi
            $_SESSION['user'] = $user;
            $_SESSION['login_time'] = time();
            $_SESSION['last_activity'] = time();
            $_SESSION['ua_hash'] = md5($_SERVER['HTTP_USER_AGENT'] ?? 'none');
            $_SESSION['login_ip'] = $clientIp;

            flash('Selamat datang kembali, ' . $user['name'] . '! Sesi akun Anda telah aktif dan diamankan.');
            header('Location: ' . u('index.php?page=' . ($user['role'] === 'admin' ? 'admin' : 'member')));
            exit;
        } else {
            record_login_attempt($uInput, $clientIp, false);
            $newFails = $fails + 1;
            $sisa = max(0, MAX_LOGIN_ATTEMPTS - $newFails);

            if ($sisa > 0) {
                flash("Username, NISN, atau password salah. Peringatan Keamanan: Sisa kesempatan {$sisa} kali sebelum akun/IP dibekukan sementara.", 'error');
            } else {
                flash("Terlalu banyak percobaan login gagal! Akses telah dibekukan sementara selama 15 menit demi mencegah upaya pembobolan.", 'error');
            }
            header('Location: ' . u('index.php?page=login' . ($roleChoice ? '&role=' . $roleChoice : '')));
            exit;
        }
    }

    render_public_header('login', 'Login');
