if ($page === 'register') {
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $nisn = trim($_POST['code'] ?? '');
        $name = trim($_POST['name'] ?? '');
        $dept = trim($_POST['department'] ?? '');
        $phone = trim($_POST['phone'] ?? '');
        $pass = (string)($_POST['password'] ?? '');

        if (strlen($pass) < 6) {
            flash('Password minimal harus 6 karakter demi menjaga keamanan akun dari pembobolan.', 'error');
        } elseif (empty($nisn) || empty($name)) {
            flash('NISN / ID Anggota dan Nama Lengkap wajib diisi.', 'error');
        } else {
            $chk = $pdo->prepare("SELECT id FROM users WHERE username = ? OR member_code = ?");
            $chk->execute([$nisn, $nisn]);
            if ($chk->fetch()) {
                flash('NISN / ID Anggota sudah terdaftar.', 'error');
            } else {
                $ins = $pdo->prepare("INSERT INTO users (role, username, password_hash, name, member_code, department, phone, status) VALUES ('member', ?, ?, ?, ?, ?, ?, 'active')");
                $ins->execute([$nisn, password_hash($pass, PASSWORD_DEFAULT), $name, $nisn, $dept, $phone]);
                flash('Pendaftaran berhasil! Akun Anda aktif dan dapat langsung digunakan untuk login.');
                header('Location: ' . u('index.php?page=login&role=member'));
                exit;
            }
        }
    }

    render_public_header('register', 'Pendaftaran Anggota');
    ?>
