                <script>
                function updateIdPlaceholder(val) {
                    const input = document.getElementById('codeInput');
                    const label = document.getElementById('codeLabel');
                    if (!input || !label) return;
                    if (val.indexOf('Guru') !== -1 || val.indexOf('Pendidik') !== -1 || val.indexOf('Dosen') !== -1) {
                        label.textContent = 'NIP / NUPTK / ID Guru';
                        input.placeholder = 'Contoh: NIP. 19780512 200301 1 004';
                    } else if (val.indexOf('Tamu') !== -1 || val.indexOf('Luar') !== -1 || val.indexOf('Umum') !== -1 || val.indexOf('Eksternal') !== -1) {
                        label.textContent = 'Nomor KTP / NIK / ID Tamu';
                        input.placeholder = 'Contoh: 16 Digit NIK KTP / SIM';
                    } else if (val.indexOf('Staf') !== -1 || val.indexOf('Karyawan') !== -1 || val.indexOf('TU') !== -1) {
                        label.textContent = 'NIP / ID Karyawan / Staf';
                        input.placeholder = 'Contoh: NIP / ID Staf Tata Usaha';
                    } else {
                        label.textContent = 'NISN / ID Anggota Siswa';
                        input.placeholder = 'Contoh: 10 Digit NISN (1234567890)';
                    }
                }
                document.addEventListener('DOMContentLoaded', function() {
                    const sel = document.getElementById('regCategorySelect');
                    if (sel && sel.value) updateIdPlaceholder(sel.value);
                });
                </script>
