if ($page === 'books') {
    $q = trim($_GET['q'] ?? '');
    $cat = trim($_GET['category'] ?? '');
    $sort = trim($_GET['sort'] ?? 'newest');

    // Query categories with counts
    $catCountsRaw = $pdo->query("SELECT category, COUNT(*) as cnt FROM books GROUP BY category")->fetchAll();
    $catCounts = [];
    $totalBooks = 0;
    foreach ($catCountsRaw as $r) {
        $cName = $r['category'] ?: 'Lainnya';
        $catCounts[$cName] = (int)$r['cnt'];
        $totalBooks += (int)$r['cnt'];
    }

    // Dynamic categories list from categories table + active book categories
    $dbCats = $pdo->query("SELECT name FROM categories ORDER BY name ASC")->fetchAll(PDO::FETCH_COLUMN);
    $allCats = array_unique(array_merge($dbCats, array_keys($catCounts)));
    $standardCats = array_filter($allCats, function($c) { return trim($c) !== ''; });

    // Build filter query
    $sql = "SELECT * FROM books WHERE 1=1";
    $params = [];

    if ($q !== '') {
        $sql .= " AND (title LIKE ? OR author LIKE ? OR publisher LIKE ? OR code LIKE ?)";
        $like = "%$q%";
        $params[] = $like;
        $params[] = $like;
        $params[] = $like;
        $params[] = $like;
    }

    if ($cat !== '' && $cat !== 'all') {
        $sql .= " AND category = ?";
        $params[] = $cat;
    }

    if ($sort === 'title') {
        $sql .= " ORDER BY title ASC";
    } elseif ($sort === 'stock') {
        $sql .= " ORDER BY available DESC";
    } else {
        $sql .= " ORDER BY id DESC";
    }

    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);
    $booksList = $stmt->fetchAll();

    render_public_header('books', 'Cari Buku');
    ?>
