// ==========================================================================
// 6. PAGE: REQUEST PEMINJAMAN (ACTION)
// ==========================================================================
if ($page === 'request') {
    auth('member');
    $bookId = (int)($_GET['book'] ?? 0);
    $stmt = $pdo->prepare("SELECT * FROM books WHERE id = ? AND available > 0");
    $stmt->execute([$bookId]);
    $b = $stmt->fetch();

    if (!$b) {
        flash('Buku tidak tersedia.', 'error');
        header('Location: ' . u('index.php?page=books'));
        exit;
    }

    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $qty = max(1, (int)($_POST['qty'] ?? 1));
        $notes = trim($_POST['notes'] ?? '');

        if ($qty > $b['available']) {
            flash('Jumlah melebihi stok yang tersedia.', 'error');
            header('Location: ' . u('index.php?page=book_detail&id=' . $bookId));
            exit;
        } else {
            $ins = $pdo->prepare("INSERT INTO loans (member_id, book_id, quantity, request_date, status, notes) VALUES (?, ?, ?, CURDATE(), 'pending', ?)");
            $ins->execute([$_SESSION['user']['id'], $bookId, $qty, $notes]);
            $loanId = (int)$pdo->lastInsertId();
            flash('Peminjaman online berhasil diajukan! Tunjukkan kartu digital berikut kepada admin perpustakaan.');
            header('Location: ' . u('index.php?page=loan_card&id=' . $loanId));
            exit;
        }
    }
}

