if ($page === 'member_request') {
    auth('member');
    $uid = $_SESSION['user']['id'];

    // Handle Form Submission
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $bookId = (int)($_POST['book_id'] ?? 0);
        $userDept = $_SESSION['user']['department'] ?? '';
        $isGuru = (stripos($userDept, 'Guru') !== false || stripos($userDept, 'Pendidik') !== false || stripos($userDept, 'Tendik') !== false || stripos($userDept, 'Pegawai') !== false || stripos($userDept, 'Staf') !== false || stripos($userDept, 'Dosen') !== false);
        $rawQty = max(1, (int)($_POST['qty'] ?? 1));
        $qty = $isGuru ? $rawQty : min(2, $rawQty);
        $notes = trim($_POST['notes'] ?? '');

        $stmt = $pdo->prepare("SELECT * FROM books WHERE id = ?");
        $stmt->execute([$bookId]);
        $b = $stmt->fetch();

        if (!$b) {
            flash('Buku yang dipilih tidak ditemukan.', 'error');
        } elseif ($b['available'] < $qty) {
            flash('Stok buku tidak mencukupi (tersedia: ' . number_format($b['available'], 0, ',', '.') . ').', 'error');
        } else {
            $ins = $pdo->prepare("INSERT INTO loans (member_id, book_id, quantity, request_date, status, notes) VALUES (?, ?, ?, CURDATE(), 'pending', ?)");
            $ins->execute([$uid, $bookId, $qty, $notes]);
            $loanId = (int)$pdo->lastInsertId();
            flash('Pengajuan peminjaman berhasil dikirim! Tunjukkan kartu digital berikut kepada admin perpustakaan.');
            header('Location: ' . u('index.php?page=loan_card&id=' . $loanId));
            exit;
