// ==========================================================================
// 7. PAGE: DASHBOARD ANGGOTA (SISWA)
// ==========================================================================
if ($page === 'member') {
    auth('member');
    $uid = $_SESSION['user']['id'];

    // Handle Member 1-Click Visit Check-In & Check-Out
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        if (isset($_POST['act_checkin'])) {
            $chkToday = $pdo->prepare("SELECT id FROM visits WHERE member_id = ? AND visit_date = CURDATE()");
            $chkToday->execute([$uid]);
            if (!$chkToday->fetch()) {
                $purpose = trim($_POST['purpose'] ?? 'Membaca & Belajar Mandiri');
                $ins = $pdo->prepare("INSERT INTO visits (member_id, visitor_name, department, purpose, visit_date, time_in) VALUES (?, ?, ?, ?, CURDATE(), CURTIME())");
                $ins->execute([$uid, $_SESSION['user']['name'], $_SESSION['user']['department'] ?: 'Anggota', $purpose]);
                flash('Presensi kunjungan hari ini berhasil dicatat! Selamat berkunjung di perpustakaan.');
            } else {
                flash('Anda sudah melakukan presensi masuk hari ini.', 'info');
            }
            header('Location: ' . u('index.php?page=member'));
            exit;
        } elseif (isset($_POST['act_checkout'])) {
            $upd = $pdo->prepare("UPDATE visits SET time_out = CURTIME() WHERE member_id = ? AND visit_date = CURDATE() AND time_out IS NULL");
            $upd->execute([$uid]);
            flash('Presensi check-out (jam keluar) berhasil dicatat. Terima kasih atas kunjungannya!');
            header('Location: ' . u('index.php?page=member'));
            exit;
        }
    }

    // Check today's visit for current member
    $todayVisitStmt = $pdo->prepare("SELECT * FROM visits WHERE member_id = ? AND visit_date = CURDATE() ORDER BY id DESC LIMIT 1");
    $todayVisitStmt->execute([$uid]);
    $myVisitToday = $todayVisitStmt->fetch();

    // Stats
    $cBorrowed = (int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM loans WHERE member_id = $uid AND status = 'borrowed'")->fetchColumn();
    $cPending = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE member_id = $uid AND status = 'pending'")->fetchColumn();
    $cOverdue = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE member_id = $uid AND status = 'borrowed' AND due_date < CURDATE()")->fetchColumn();

    // Books for quick grid
    $recentBooks = $pdo->query("SELECT * FROM books ORDER BY id DESC LIMIT 4")->fetchAll();

    // Member's loans that are due soon (next 2 days)
    $dueSoon = $pdo->query("SELECT l.*, b.title FROM loans l JOIN books b ON b.id = l.book_id WHERE l.member_id = $uid AND l.status = 'borrowed' AND l.due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 2 DAY)")->fetchAll();

    // Latest active or pending loan for quick digital card access
    $latestLoan = $pdo->query("SELECT l.*, b.title, b.author, b.category FROM loans l JOIN books b ON b.id = l.book_id WHERE l.member_id = $uid AND l.status IN ('pending', 'borrowed') ORDER BY l.id DESC LIMIT 1")->fetch();

    render_app_layout('member', 'dashboard', 'Dashboard Anggota', function() use ($cBorrowed, $cPending, $cOverdue, $recentBooks, $dueSoon, $latestLoan, $myVisitToday) {
