if ($page === 'member_loans' || $page === 'member_history') {
    auth('member');
    $uid = $_SESSION['user']['id'];
    $isHistory = ($page === 'member_history');

    $sql = "SELECT l.*, b.title, b.author, b.category FROM loans l JOIN books b ON b.id = l.book_id WHERE l.member_id = ?";
    if (!$isHistory) {
        $sql .= " AND l.status IN ('borrowed', 'pending')";
    }
    $sql .= " ORDER BY l.id DESC";

    $stmt = $pdo->prepare($sql);
    $stmt->execute([$uid]);
    $loans = $stmt->fetchAll();

    $title = $isHistory ? 'Riwayat Peminjaman' : 'Buku Saya (Aktif)';
    render_app_layout('member', $isHistory ? 'history' : 'loans', $title, function() use ($loans, $isHistory) {
        ?>
        <div class="card-box">
            <div class="table-responsive">
                <table class="modern-table">
                    <thead>
                        <tr>
                            <th>No</th>
                            <th>Judul Buku</th>
                            <th>Kategori</th>
                            <th>Jumlah</th>
                            <th>Tgl Pengajuan</th>
                            <th>Jatuh Tempo</th>
                            <th>Status</th>
                            <th>Aksi</th>
                        </tr>
                    </thead>
                    <tbody>
                        <?php if (empty($loans)): ?>
                            <tr><td colspan="8" style="text-align:center;padding:24px;color:var(--text-muted);">Belum ada data peminjaman.</td></tr>
                        <?php else: ?>
                            <?php $no = 1; foreach ($loans as $l): ?>
                                <tr>
                                    <td><?=$no++?></td>
                                    <td>
                                        <b><?=e($l['title'])?></b><br><small style="color:var(--text-muted);"><?=e($l['author'])?></small>
                                        <?php if (!empty($l['copy_serial'])): ?>
                                            <div style="margin-top:2px;">
                                                <span class="badge" style="background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;font-family:monospace;font-size:10.5px;padding:1px 6px;">
