                                    </td>
                                    <td><?=e($l['category']?:'-')?></td>
                                    <td><?=$l['quantity']?></td>
                                    <td><?=e($l['request_date'])?></td>
                                    <td><?=e($l['due_date'] ?? '-')?></td>
                                    <td>
                                        <?php if ($l['status'] === 'borrowed'): ?>
                                            <span class="badge badge-green">Sedang Dipinjam</span>
                                        <?php elseif ($l['status'] === 'pending'): ?>
