                                            <span class="badge badge-red"><?=e($l['status'])?></span>
                                        <?php endif; ?>
                                    </td>
                                    <td>
                                        <a href="<?=u('index.php?page=loan_card&id='.$l['id'])?>" class="btn btn-outline-primary btn-sm" style="display:inline-flex;align-items:center;gap:5px;padding:5px 10px;font-size:12px;font-weight:700;">
                                            <?=icon('card', '', 14)?> Kartu Digital
                                        </a>
                                    </td>
                                </tr>
                            <?php endforeach; ?>
                        <?php endif; ?>
