if ($page === 'member_visit') {
    auth('member');
    $uid = $_SESSION['user']['id'];

    // Handle Member 1-Click Visit Check-In & Check-Out
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        if (isset($_POST['act_checkin'])) {
            $chkToday = $pdo->prepare("SELECT id FROM visits WHERE member_id = ? AND visit_date = CURDATE()");
            $chkToday->execute([$uid]);
            if (!$chkToday->fetch()) {
                $purpose = trim($_POST['purpose'] ?? 'Membaca & Belajar Mandiri');
                $ins = $pdo->prepare("INSERT INTO visits (member_id, visitor_name, department, purpose, visit_date, time_in) VALUES (?, ?, ?, ?, CURDATE(), CURTIME())");
                $ins->execute([$uid, $_SESSION['user']['name'], $_SESSION['user']['department'] ?: 'Anggota', $purpose]);
                flash('Presensi kunjungan hari ini berhasil dicatat! Selamat berkunjung di perpustakaan.');
            } else {
                flash('Anda sudah melakukan presensi masuk hari ini.', 'info');
            }
            header('Location: ' . u('index.php?page=member_visit'));
            exit;
        } elseif (isset($_POST['act_checkout'])) {
            $upd = $pdo->prepare("UPDATE visits SET time_out = CURTIME() WHERE member_id = ? AND visit_date = CURDATE() AND time_out IS NULL");
            $upd->execute([$uid]);
            flash('Presensi check-out (jam keluar) berhasil dicatat. Terima kasih atas kunjungannya!');
            header('Location: ' . u('index.php?page=member_visit'));
            exit;
        }
    }

    // Check today's visit for current member
    $todayVisitStmt = $pdo->prepare("SELECT * FROM visits WHERE member_id = ? AND visit_date = CURDATE() ORDER BY id DESC LIMIT 1");
