if ($page === 'card') {
    auth();
    $currentUser = $_SESSION['user'];
    $isAdmin = ($currentUser['role'] === 'admin');

    // Handle POST Actions on Card Page (Upload / Change Member Photo)
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $action = $_POST['action'] ?? '';
        if ($action === 'update_card_photo') {
            $targetUserId = $isAdmin ? (int)($_POST['member_id'] ?? 0) : (int)$currentUser['id'];
            if ($targetUserId <= 0) $targetUserId = (int)$currentUser['id'];

            $chkStmt = $pdo->prepare("SELECT id, name, photo FROM users WHERE id = ? LIMIT 1");
            $chkStmt->execute([$targetUserId]);
            $targetUser = $chkStmt->fetch();

            if ($targetUser) {
                $newPhoto = null;
                // Preset Avatar selected
                if (!empty($_POST['preset_avatar'])) {
                    $preset = trim($_POST['preset_avatar']);
                    $validPresets = [
                        'assets/img/avatar_student_default.svg',
                        'assets/img/avatar_student_male.svg',
                        'assets/img/avatar_student_female.svg'
                    ];
                    if (in_array($preset, $validPresets, true)) {
                        $newPhoto = $preset;
                    }
                }

                // File Uploaded
                if (!empty($_FILES['member_photo']['name']) && $_FILES['member_photo']['error'] === UPLOAD_ERR_OK) {
                    $uploaded = handle_member_photo_upload('member_photo', $targetUser['photo']);
                    if ($uploaded) {
                        $newPhoto = $uploaded;
                    }
                }

                // Remove photo
                if (!empty($_POST['remove_photo'])) {
                    if (!empty($targetUser['photo']) && strpos($targetUser['photo'], 'member_') === 0 && file_exists(__DIR__ . '/uploads/' . $targetUser['photo'])) {
                        @unlink(__DIR__ . '/uploads/' . $targetUser['photo']);
                    }
                    $newPhoto = '';
                }

                if ($newPhoto !== null) {
                    $pdo->prepare("UPDATE users SET photo = ? WHERE id = ?")->execute([$newPhoto ?: null, $targetUserId]);
                    if ($currentUser['id'] == $targetUserId) {
                        $_SESSION['user']['photo'] = $newPhoto ?: null;
                    }
                    flash('Foto profil anggota "' . $targetUser['name'] . '" berhasil disimpan.');
                }
            }
            header('Location: ' . u('index.php?page=card' . ($isAdmin ? '&id=' . $targetUserId : '')));
            exit;
        }
    }

    $targetMembers = [];
    $selectedDept = trim($_GET['dept'] ?? $_GET['class'] ?? '');
    $rawIds = $_POST['selected_member_ids'] ?? $_REQUEST['ids'] ?? '';
    $idArray = [];
    if (is_array($rawIds)) {
        $idArray = array_filter(array_map('intval', $rawIds));
    } elseif (is_string($rawIds) && trim($rawIds) !== '') {
        $idArray = array_filter(array_map('intval', explode(',', $rawIds)));
    }

    if ($isAdmin) {
        $memberId = (int)($_GET['id'] ?? 0);
        if (!empty($idArray)) {
            $placeholders = implode(',', array_fill(0, count($idArray), '?'));
            $stmt = $pdo->prepare("SELECT * FROM users WHERE role = 'member' AND id IN ($placeholders) ORDER BY department ASC, name ASC");
            $stmt->execute($idArray);
            $targetMembers = $stmt->fetchAll();
        } elseif ($selectedDept !== '' && $selectedDept !== 'all') {
            $stmt = $pdo->prepare("SELECT * FROM users WHERE role = 'member' AND department = ? ORDER BY name ASC");
            $stmt->execute([$selectedDept]);
            $targetMembers = $stmt->fetchAll();
        } elseif (isset($_GET['all']) && $_GET['all'] === '1') {
            $targetMembers = $pdo->query("SELECT * FROM users WHERE role = 'member' AND status = 'active' ORDER BY department ASC, name ASC")->fetchAll();
        } elseif ($memberId > 0) {
            $stmt = $pdo->prepare("SELECT * FROM users WHERE id = ? AND role = 'member' LIMIT 1");
            $stmt->execute([$memberId]);
            $singleUser = $stmt->fetch();
            if ($singleUser) {
                $targetMembers = [$singleUser];
            }
        } else {
            // Default to latest member if none specified
            $stmt = $pdo->query("SELECT * FROM users WHERE role = 'member' ORDER BY id DESC LIMIT 1");
            $singleUser = $stmt->fetch();
            if ($singleUser) {
                $targetMembers = [$singleUser];
            }
        }

        if (empty($targetMembers)) {
            flash('Tidak ada data anggota yang ditemukan untuk dicetak kartunya.', 'error');
            header('Location: ' . u('index.php?page=admin_members'));
            exit;
        }

        $allMembersList = $pdo->query("SELECT id, name, member_code, department FROM users WHERE role = 'member' ORDER BY name ASC")->fetchAll();
        $departmentsList = $pdo->query("SELECT department, COUNT(*) as cnt FROM users WHERE role = 'member' GROUP BY department ORDER BY cnt DESC")->fetchAll();
        $user = $targetMembers[0];
    } else {
        $user = $currentUser;
        $targetMembers = [$currentUser];
        $allMembersList = [];
        $departmentsList = [];
    }

    $isBulk = count($targetMembers) > 1;
    $layoutRole = $isAdmin ? 'admin' : 'member';
    $layoutActive = $isAdmin ? 'members' : 'card';
    $pageTitle = $isBulk 
        ? ('Cetak Kartu Massal (' . count($targetMembers) . ' Siswa): ' . ($selectedDept ?: 'Daftar Terpilih'))
        : ('Cetak Kartu Anggota: ' . ($user['name'] ?? 'Anggota'));

