        <!-- JavaScript: Real ISO QR Code Generator Script & Print Controls -->
        <script src="<?=u('assets/js/qrcode.min.js')?>"></script>
        <script src="<?=u('assets/js/html2canvas.min.js')?>"></script>
        <script src="<?=u('assets/js/jszip.min.js')?>"></script>
        <script>
        if (typeof html2canvas === 'undefined') {
            document.write('<script src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js"><\/script>');
        }
        if (typeof JSZip === 'undefined') {
            document.write('<script src="https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"><\/script>');
        }
        </script>
        <script>
        (function() {
            // Render all QR Codes with high precision QRCode.js
            function renderAllCardQrs() {
                if (typeof QRCode === 'undefined') return;
                var qrBoxes = document.querySelectorAll('.card-qr-box[data-code]');
                qrBoxes.forEach(function(box) {
                    if (!box.getAttribute('data-qr-rendered')) {
                        box.setAttribute('data-qr-rendered', '1');
                        var code = box.getAttribute('data-code');
                        box.innerHTML = '';
                        new QRCode(box, {
                            text: code,
                            width: 66,
                            height: 66,
                            colorDark: '#0b254e',
                            colorLight: '#ffffff',
                            correctLevel: QRCode.CorrectLevel.M
                        });
                    }
                });
            }

            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', renderAllCardQrs);
            } else {
                renderAllCardQrs();
            }

            window.renderAllCardQrs = renderAllCardQrs;
        })();

        // Control: Card Side Mode (Both / Front Only / Back Only)
        function setCardSideMode(mode) {
            document.body.classList.remove('print-mode-front-only', 'print-mode-back-only');
            var btnBoth = document.getElementById('btnSideBoth');
            var btnFront = document.getElementById('btnSideFront');
            var btnBack = document.getElementById('btnSideBack');

            if (btnBoth) btnBoth.className = 'btn btn-sm btn-outline-secondary';
            if (btnFront) btnFront.className = 'btn btn-sm btn-outline-secondary';
            if (btnBack) btnBack.className = 'btn btn-sm btn-outline-secondary';

            if (mode === 'front') {
                document.body.classList.add('print-mode-front-only');
                if (btnFront) btnFront.className = 'btn btn-sm btn-primary';
                document.querySelectorAll('.member-id-card-back').forEach(function(el){ el.style.display = 'none'; });
                document.querySelectorAll('.member-id-card').forEach(function(el){ el.style.display = 'flex'; });
            } else if (mode === 'back') {
                document.body.classList.add('print-mode-back-only');
                if (btnBack) btnBack.className = 'btn btn-sm btn-primary';
                document.querySelectorAll('.member-id-card').forEach(function(el){ el.style.display = 'none'; });
                document.querySelectorAll('.member-id-card-back').forEach(function(el){ el.style.display = 'flex'; });
            } else {
                if (btnBoth) btnBoth.className = 'btn btn-sm btn-primary';
                document.querySelectorAll('.member-id-card').forEach(function(el){ el.style.display = 'flex'; });
                document.querySelectorAll('.member-id-card-back').forEach(function(el){ el.style.display = 'flex'; });
            }
        }

        // Control: Print Layout Mode (A4 Grid vs PVC 1-per-page)
        function setLayoutMode(mode) {
            var btnA4 = document.getElementById('btnLayoutA4');
            var btnPvc = document.getElementById('btnLayoutPvc');
            if (mode === 'pvc') {
                document.body.classList.add('print-layout-pvc');
                if (btnPvc) btnPvc.className = 'btn btn-sm btn-primary';
                if (btnA4) btnA4.className = 'btn btn-sm btn-outline-secondary';
            } else {
                document.body.classList.remove('print-layout-pvc');
                if (btnA4) btnA4.className = 'btn btn-sm btn-primary';
                if (btnPvc) btnPvc.className = 'btn btn-sm btn-outline-secondary';
            }
        }

        // Control: Preview Scale Zoom
        function setCardScale(scale) {
            document.documentElement.style.setProperty('--card-scale', scale);
            var b100 = document.getElementById('btnScale100');
            var b115 = document.getElementById('btnScale115');
            var b130 = document.getElementById('btnScale130');
            if (b100) b100.className = 'btn btn-sm btn-outline-secondary';
            if (b115) b115.className = 'btn btn-sm btn-outline-secondary';
            if (b130) b130.className = 'btn btn-sm btn-outline-secondary';

            if (scale === 1.0 && b100) b100.className = 'btn btn-sm btn-primary';
            else if (scale === 1.15 && b115) b115.className = 'btn btn-sm btn-primary';
            else if (scale === 1.30 && b130) b130.className = 'btn btn-sm btn-primary';
        }

        // Control: Toggle Single Card Inclusion
        function toggleCardInclusion(cb, pairId) {
            var wrap = document.getElementById(pairId);
            if (!wrap) return;
            if (cb.checked) {
                wrap.classList.remove('is-excluded');
            } else {
                wrap.classList.add('is-excluded');
            }
            updateActiveCardCount();
        }

        function selectAllCardPairs(check) {
            var cbs = document.querySelectorAll('.card-pair-checkbox');
            cbs.forEach(function(cb) {
                cb.checked = check;
                var wrap = cb.closest('.card-pair-wrapper');
                if (wrap) {
                    if (check) wrap.classList.remove('is-excluded');
                    else wrap.classList.add('is-excluded');
                }
            });
            updateActiveCardCount();
        }

        function updateActiveCardCount() {
            var active = document.querySelectorAll('.card-pair-wrapper:not(.is-excluded)').length;
            var badge = document.getElementById('activePrintCardCount');
            if (badge) badge.textContent = active;
        }

        // ==========================================================================
        // FITUR UNDUH GAMBAR JPG & CETAK GAMBAR UKURAN KARTU ATM
        // ==========================================================================
        function toggleDropdownJpgMenu() {
            var m = document.getElementById('dropdownJpgMenu');
            if (m) m.style.display = (m.style.display === 'none' ? 'block' : 'none');
        }

        document.addEventListener('click', function(e) {
            var btn = document.getElementById('btnDownloadJpgMain');
            var m = document.getElementById('dropdownJpgMenu');
            if (m && btn && !btn.contains(e.target) && !m.contains(e.target)) {
                m.style.display = 'none';
            }
        });

        function getCleanFileName(name, code, side) {
            var safeName = (name || 'Siswa').replace(/[^a-zA-Z0-9_-]/g, '_').substring(0, 30);
            var safeCode = (code || '').replace(/[^a-zA-Z0-9_-]/g, '_');
            return 'Kartu_Siswa_' + safeName + (safeCode ? '_' + safeCode : '') + '_' + side + '.jpg';
        }

        function showCardToast(msg, isSuccess) {
            if (isSuccess === undefined) isSuccess = true;
            var toast = document.getElementById('cardJpgToast');
            if (!toast) {
                toast = document.createElement('div');
                toast.id = 'cardJpgToast';
                toast.style.cssText = 'position:fixed;bottom:24px;right:24px;z-index:999999;padding:12px 18px;border-radius:8px;font-size:13px;font-weight:700;box-shadow:0 8px 24px rgba(0,0,0,0.25);transition:all 0.3s;display:flex;align-items:center;gap:8px;';
                document.body.appendChild(toast);
            }
            toast.style.background = isSuccess ? '#059669' : '#dc2626';
            toast.style.color = '#ffffff';
            toast.innerHTML = (isSuccess ? '✓ ' : '✕ ') + msg;
            toast.style.display = 'flex';
            toast.style.opacity = '1';
            setTimeout(function() {
                toast.style.opacity = '0';
                setTimeout(function() { toast.style.display = 'none'; }, 300);
            }, 3500);
        }

        function downloadCardJpg(pairId, side, studentName, studentCode) {
            if (typeof html2canvas === 'undefined') {
                alert('Pustaka html2canvas belum dimuat. Mohon muat ulang halaman.');
                return;
            }

            var pairElem = document.getElementById(pairId);
            if (!pairElem) return;

            var targetElem;
            if (side === 'depan') {
                targetElem = pairElem.querySelector('.member-id-card');
            } else if (side === 'belakang') {
                targetElem = pairElem.querySelector('.member-id-card-back');
            } else {
                targetElem = pairElem.querySelector('.card-pair-sides');
            }

            if (!targetElem) {
                showCardToast('Elemen kartu tidak ditemukan', false);
                return;
            }

            showCardToast('Sedang membuat gambar JPG resolusi tinggi (Ukuran ATM)...');

            var frontCard = pairElem.querySelector('.member-id-card');
            var backCard = pairElem.querySelector('.member-id-card-back');
            var prevFrontDisplay = frontCard ? frontCard.style.display : '';
            var prevBackDisplay = backCard ? backCard.style.display : '';

            if (side === 'depan' && frontCard) frontCard.style.display = 'flex';
            if (side === 'belakang' && backCard) backCard.style.display = 'flex';
            if (side === 'semua') {
                if (frontCard) frontCard.style.display = 'flex';
                if (backCard) backCard.style.display = 'flex';
            }

            html2canvas(targetElem, {
                scale: 3,
                useCORS: true,
                allowTaint: true,
                backgroundColor: '#ffffff',
                logging: false
            }).then(function(canvas) {
                if (frontCard) frontCard.style.display = prevFrontDisplay;
                if (backCard) backCard.style.display = prevBackDisplay;

                var dataUrl = canvas.toDataURL('image/jpeg', 0.95);
                var link = document.createElement('a');
                link.download = getCleanFileName(studentName, studentCode, side);
                link.href = dataUrl;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                showCardToast('Kartu siswa (' + side.toUpperCase() + ') berhasil diunduh sebagai file JPG!');
            }).catch(function(err) {
                if (frontCard) frontCard.style.display = prevFrontDisplay;
                if (backCard) backCard.style.display = prevBackDisplay;
                console.error(err);
                showCardToast('Gagal memproses gambar kartu: ' + err.message, false);
            });
        }

        function printCardAsAtmImage(pairId, studentName) {
            if (typeof html2canvas === 'undefined') {
                alert('Pustaka html2canvas belum dimuat. Mohon muat ulang halaman.');
                return;
            }

            var pairElem = document.getElementById(pairId);
            if (!pairElem) return;

            var frontElem = pairElem.querySelector('.member-id-card');
            var backElem = pairElem.querySelector('.member-id-card-back');

            if (!frontElem && !backElem) {
                showCardToast('Elemen kartu tidak ditemukan', false);
                return;
            }

            showCardToast('Menyiapkan gambar kartu presisi ukuran ATM (85.6 × 54 mm)...');

            var prevFrontDisplay = frontElem ? frontElem.style.display : '';
            var prevBackDisplay = backElem ? backElem.style.display : '';
            if (frontElem) frontElem.style.display = 'flex';
            if (backElem) backElem.style.display = 'flex';

            var renderFront = frontElem ? html2canvas(frontElem, { scale: 3, useCORS: true, backgroundColor: '#ffffff', logging: false }) : Promise.resolve(null);
            var renderBack = backElem ? html2canvas(backElem, { scale: 3, useCORS: true, backgroundColor: '#ffffff', logging: false }) : Promise.resolve(null);

            Promise.all([renderFront, renderBack]).then(function(results) {
                if (frontElem) frontElem.style.display = prevFrontDisplay;
                if (backElem) backElem.style.display = prevBackDisplay;

                var frontCanvas = results[0];
                var backCanvas = results[1];

                var frontJpg = frontCanvas ? frontCanvas.toDataURL('image/jpeg', 0.95) : '';
                var backJpg = backCanvas ? backCanvas.toDataURL('image/jpeg', 0.95) : '';

                var printWin = window.open('', '_blank', 'width=850,height=750');
                if (!printWin) {
                    alert('Popup terblokir oleh browser. Izinkan pop-up untuk mencetak gambar kartu.');
                    return;
                }

                var safeStudent = studentName || 'Siswa';
                var html = '<!DOCTYPE html><html><head><meta charset="utf-8">';
                html += '<title>Cetak Gambar Kartu ATM - ' + safeStudent + '</title>';
                html += '<style>';
                html += '@page { size: auto; margin: 10mm; }';
                html += '* { box-sizing: border-box; }';
                html += 'body { margin: 0; padding: 20px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: #fff; text-align: center; }';
                html += '.print-atm-container { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8mm; margin: 0 auto; }';
                html += '.card-atm-item { display: inline-flex; flex-direction: column; align-items: center; page-break-inside: avoid; break-inside: avoid; }';
                html += '.card-atm-img { width: 85.6mm !important; height: 54.0mm !important; display: block; object-fit: contain; border-radius: 3.18mm; border: 0.5px dashed #94a3b8; }';
                html += '.card-atm-label { font-size: 10px; color: #64748b; font-weight: bold; margin-bottom: 2mm; text-transform: uppercase; }';
                html += '.no-print { margin-bottom: 20px; padding: 14px; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; }';
                html += '.btn-print { background: #059669; color: #fff; border: none; padding: 8px 20px; border-radius: 6px; font-weight: 700; cursor: pointer; font-size: 13px; }';
                html += '@media print { .no-print { display: none !important; } body { padding: 0; } }';
                html += '</style></head><body>';
                html += '<div class="no-print">';
                html += '<div style="font-weight:800;font-size:15px;color:#0f172a;margin-bottom:6px;">Pratinjau Gambar Kartu Siswa (Ukuran Fisik Kartu ATM: 85.6 × 54.0 mm)</div>';
                html += '<div style="font-size:12px;color:#64748b;margin-bottom:12px;">Siswa: <b>' + safeStudent + '</b> • Gambar dicetak persis standar kartu ATM / CR80</div>';
                html += '<button type="button" class="btn-print" onclick="window.print()">🖨️ Cetak Gambar Sekarang (Ctrl+P)</button>';
                html += '</div>';
                html += '<div class="print-atm-container">';
                if (frontJpg) {
                    html += '<div class="card-atm-item">';
                    html += '<div class="card-atm-label">Sisi Depan (85.6 mm × 54.0 mm)</div>';
                    html += '<img class="card-atm-img" src="' + frontJpg + '" alt="Depan">';
                    html += '</div>';
                }
                if (backJpg) {
                    html += '<div class="card-atm-item">';
                    html += '<div class="card-atm-label">Sisi Belakang (85.6 mm × 54.0 mm)</div>';
                    html += '<img class="card-atm-img" src="' + backJpg + '" alt="Belakang">';
                    html += '</div>';
                }
                html += '</div>';
                html += '<script>window.onload = function() { setTimeout(function(){ window.print(); }, 400); };<\/script>';
                html += '</body></html>';

                printWin.document.open();
                printWin.document.write(html);
                printWin.document.close();
                showCardToast('Jendela cetak gambar ukuran ATM berhasil dibuka!');
            }).catch(function(err) {
                if (frontElem) frontElem.style.display = prevFrontDisplay;
                if (backElem) backElem.style.display = prevBackDisplay;
                console.error(err);
                showCardToast('Gagal memproses gambar cetak: ' + err.message, false);
            });
        }

        function getFirstActivePair() {
            var activePairs = document.querySelectorAll('.card-pair-wrapper:not(.is-excluded)');
            if (activePairs.length > 0) return activePairs[0];
            return document.querySelector('.card-pair-wrapper');
        }

        function downloadActiveCardJpg(side) {
            var p = getFirstActivePair();
            if (!p) {
                showCardToast('Tidak ada kartu siswa yang dipilih', false);
                return;
            }
            var id = p.id;
            var nameElem = p.querySelector('.card-pair-header-bar b');
            var name = nameElem ? nameElem.textContent.trim() : 'Siswa';
            var codeElem = p.querySelector('.card-pair-header-bar span b');
            var code = codeElem ? codeElem.textContent.trim() : '';
            downloadCardJpg(id, side, name, code);
        }

        function printActiveCardAsAtmImage() {
            var p = getFirstActivePair();
            if (!p) {
                showCardToast('Tidak ada kartu siswa yang dipilih', false);
                return;
            }
            var id = p.id;
            var nameElem = p.querySelector('.card-pair-header-bar b');
            var name = nameElem ? nameElem.textContent.trim() : 'Siswa';
            printCardAsAtmImage(id, name);
        }

        // ==========================================================================
        // DOWNLOAD SEKALIGUS SEMUA KARTU SISWA DALAM FILE .ZIP
        // ==========================================================================
        function downloadAllCardsZip(side) {
            if (typeof html2canvas === 'undefined' || typeof JSZip === 'undefined') {
                alert('Pustaka pemroses gambar/zip sedang dimuat. Mohon tunggu beberapa detik atau muat ulang halaman.');
                return;
            }

            var activePairs = Array.from(document.querySelectorAll('.card-pair-wrapper:not(.is-excluded)'));
            if (activePairs.length === 0) {
                showCardToast('Tidak ada kartu siswa yang dipilih', false);
                return;
            }

            var progressModal = document.getElementById('bulkCardProgressModal');
            if (!progressModal) {
                progressModal = document.createElement('div');
                progressModal.id = 'bulkCardProgressModal';
                progressModal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(15,23,42,0.72);backdrop-filter:blur(4px);z-index:999999;display:flex;align-items:center;justify-content:center;padding:16px;';
                progressModal.innerHTML = '<div style="background:#fff;border-radius:14px;padding:26px;max-width:440px;width:100%;text-align:center;box-shadow:0 25px 50px rgba(0,0,0,0.3);">' +
                    '<div style="font-size:36px;margin-bottom:8px;">📦</div>' +
                    '<h3 style="margin:0 0 8px 0;font-size:16px;color:#0f172a;font-weight:800;">Download Sekaligus Semua Kartu JPG</h3>' +
                    '<p id="bulkCardProgressText" style="margin:0 0 16px 0;font-size:13px;color:#64748b;">Menyiapkan kartu siswa...</p>' +
                    '<div style="background:#e2e8f0;border-radius:8px;height:12px;overflow:hidden;margin-bottom:12px;">' +
                        '<div id="bulkCardProgressBar" style="background:#0284c7;width:0%;height:100%;transition:width 0.2s;"></div>' +
                    '</div>' +
                    '<div id="bulkCardProgressCount" style="font-size:12px;font-weight:700;color:#0284c7;">0 / ' + activePairs.length + ' Selesai</div>' +
                '</div>';
                document.body.appendChild(progressModal);
            }
            progressModal.style.display = 'flex';
            var pText = document.getElementById('bulkCardProgressText');
            var pBar = document.getElementById('bulkCardProgressBar');
            var pCount = document.getElementById('bulkCardProgressCount');

            var zip = new JSZip();
            var total = activePairs.length;
            var currentIdx = 0;

            function processNext() {
                if (currentIdx >= total) {
                    pText.textContent = 'Mengompres seluruh kartu ke file ZIP...';
                    pBar.style.width = '100%';
                    zip.generateAsync({ type: 'blob' }).then(function(content) {
                        var a = document.createElement('a');
                        var deptName = '<?=e(addslashes($selectedDept ?: "Semua_Siswa"))?>';
                        a.download = 'Kartu_Siswa_' + deptName.replace(/[^a-zA-Z0-9_-]/g, '_') + '_' + total + '_Siswa_' + side + '.zip';
                        a.href = URL.createObjectURL(content);
                        document.body.appendChild(a);
                        a.click();
                        document.body.removeChild(a);
                        setTimeout(function() {
                            progressModal.style.display = 'none';
                            showCardToast('Berhasil mendownload ' + total + ' kartu siswa sekaligus (.ZIP)!');
                        }, 800);
                    }).catch(function(err) {
                        progressModal.style.display = 'none';
                        alert('Gagal mengompres file: ' + err.message);
                    });
                    return;
                }

                var pair = activePairs[currentIdx];
                var nameElem = pair.querySelector('.card-pair-header-bar b');
                var studentName = nameElem ? nameElem.textContent.trim() : ('Siswa_' + (currentIdx + 1));
                var codeElem = pair.querySelector('.card-pair-header-bar span b');
                var studentCode = codeElem ? codeElem.textContent.trim() : '';

                var percent = Math.round(((currentIdx + 1) / total) * 100);
                pText.textContent = 'Mengonversi kartu ' + (currentIdx + 1) + ' dari ' + total + ': ' + studentName;
                pBar.style.width = percent + '%';
                pCount.textContent = (currentIdx + 1) + ' / ' + total + ' (' + percent + '%)';

                var frontElem = pair.querySelector('.member-id-card');
                var backElem = pair.querySelector('.member-id-card-back');

                var prevF = frontElem ? frontElem.style.display : '';
                var prevB = backElem ? backElem.style.display : '';
                if (frontElem) frontElem.style.display = 'flex';
                if (backElem) backElem.style.display = 'flex';

                var cleanName = (studentName).replace(/[^a-zA-Z0-9_-]/g, '_').substring(0, 30);
                var cleanCode = (studentCode).replace(/[^a-zA-Z0-9_-]/g, '_');
                var prefix = (currentIdx + 1) + '_' + cleanName + (cleanCode ? '_' + cleanCode : '');

                var promises = [];
                if ((side === 'depan' || side === 'semua') && frontElem) {
                    promises.push(html2canvas(frontElem, { scale: 3, useCORS: true, backgroundColor: '#ffffff', logging: false }).then(function(canvas) {
                        var data = canvas.toDataURL('image/jpeg', 0.95).split(',')[1];
                        zip.file(prefix + '_Depan.jpg', data, { base64: true });
                    }));
                }
                if ((side === 'belakang' || side === 'semua') && backElem) {
                    promises.push(html2canvas(backElem, { scale: 3, useCORS: true, backgroundColor: '#ffffff', logging: false }).then(function(canvas) {
                        var data = canvas.toDataURL('image/jpeg', 0.95).split(',')[1];
                        zip.file(prefix + '_Belakang.jpg', data, { base64: true });
                    }));
                }

                Promise.all(promises).then(function() {
                    if (frontElem) frontElem.style.display = prevF;
                    if (backElem) backElem.style.display = prevB;
                    currentIdx++;
                    setTimeout(processNext, 40);
                }).catch(function(err) {
                    if (frontElem) frontElem.style.display = prevF;
                    if (backElem) backElem.style.display = prevB;
                    currentIdx++;
                    setTimeout(processNext, 40);
                });
            }

            processNext();
        }
        </script>
        <?php
    });
    exit;
}

// ==========================================================================
// 9B. PAGE: KARTU DIGITAL PEMINJAMAN ONLINE (DIGITAL LOAN PASS)
// ==========================================================================
if ($page === 'loan_card') {
    $loanId = (int)($_GET['id'] ?? 0);
    $stmt = $pdo->prepare("SELECT l.*, 
        u.name AS member_name, u.member_code, u.department, u.phone, u.photo, u.role AS member_role,
        b.title AS book_title, b.code AS book_code, b.author AS book_author, b.publisher AS book_publisher, 
        b.category AS book_category, b.available AS book_available, b.quantity AS book_total_qty,
        b.cover_image AS book_cover_image
        FROM loans l
        JOIN users u ON u.id = l.member_id
        JOIN books b ON b.id = l.book_id
        WHERE l.id = ?");
    $stmt->execute([$loanId]);
    $loan = $stmt->fetch();

    if (!$loan) {
        flash('Data kartu peminjaman tidak ditemukan.', 'error');
        $fallback = !empty($_SESSION['user']) ? ($_SESSION['user']['role'] === 'admin' ? 'index.php?page=admin_loans' : 'index.php?page=member') : '';
        header('Location: ' . u($fallback));
        exit;
    }

    $isLoggedIn = !empty($_SESSION['user']);
    $userRole = $_SESSION['user']['role'] ?? '';
    $userId = $_SESSION['user']['id'] ?? 0;
    $isAdmin = ($userRole === 'admin');
    $isOwner = ($userId == $loan['member_id']);

    $verifyToken = md5($loan['id'] . '_' . $loan['created_at'] . '_smkn5telkom');
    $tokenProvided = $_GET['token'] ?? '';
    $isTokenValid = ($tokenProvided && hash_equals($verifyToken, $tokenProvided));

    if (!$isAdmin && !$isOwner && !$isTokenValid) {
        if (!$isLoggedIn) {
            header('Location: ' . u('index.php?page=login'));
            exit;
        } else {
            flash('Anda tidak memiliki izin untuk melihat kartu peminjaman ini.', 'error');
            header('Location: ' . u('index.php?page=member'));
            exit;
        }
    }

    // Handle Admin Action (Approve / Return directly from the ticket)
    if ($_SERVER['REQUEST_METHOD'] === 'POST' && $isAdmin) {
        checkcsrf();
        $act = $_POST['act'] ?? '';
        $pdo->beginTransaction();
        try {
            $lStmt = $pdo->prepare("SELECT * FROM loans WHERE id = ? FOR UPDATE");
            $lStmt->execute([$loanId]);
            $currLoan = $lStmt->fetch();

            if (!$currLoan) throw new Exception('Peminjaman tidak ditemukan.');

            if ($act === 'approve' && $currLoan['status'] === 'pending') {
                $bStmt = $pdo->prepare("SELECT available, copy_serials FROM books WHERE id = ? FOR UPDATE");
                $bStmt->execute([$currLoan['book_id']]);
                $b = $bStmt->fetch();

                if ($b['available'] < $currLoan['quantity']) {
                    throw new Exception('Stok buku tidak mencukupi untuk diserahkan.');
                }

                $assignedSerial = trim($_POST['copy_serial'] ?? ($currLoan['copy_serial'] ?? ''));
                $dueDate = date('Y-m-d', strtotime('+7 days'));
                $pdo->prepare("UPDATE loans SET status='borrowed', copy_serial=?, loan_date=CURDATE(), due_date=? WHERE id=?")->execute([$assignedSerial ?: null, $dueDate, $loanId]);
                $pdo->prepare("UPDATE books SET available = available - ? WHERE id=?")->execute([$currLoan['quantity'], $currLoan['book_id']]);
                if ($assignedSerial !== '') {
                    foreach (explode(',', $assignedSerial) as $sCode) {
                        $sCode = trim($sCode);
                        if ($sCode !== '') {
                            $pdo->prepare("UPDATE book_copies SET status = 'borrowed' WHERE book_id = ? AND copy_code = ?")->execute([$currLoan['book_id'], $sCode]);
                        }
                    }
                }
                flash('Peminjaman berhasil disetujui! Buku fisik' . ($assignedSerial ? ' (No. Seri: ' . e($assignedSerial) . ')' : '') . ' telah diserahkan.');
            } elseif ($act === 'return' && $currLoan['status'] === 'borrowed') {
                $pdo->prepare("UPDATE loans SET status='returned', return_date=CURDATE() WHERE id=?")->execute([$loanId]);
                $pdo->prepare("UPDATE books SET available = available + ? WHERE id=?")->execute([$currLoan['quantity'], $currLoan['book_id']]);
                if (!empty($currLoan['copy_serial'])) {
                    foreach (explode(',', (string)$currLoan['copy_serial']) as $sCode) {
                        $sCode = trim($sCode);
                        if ($sCode !== '') {
                            $pdo->prepare("UPDATE book_copies SET status = 'available' WHERE book_id = ? AND copy_code = ?")->execute([$currLoan['book_id'], $sCode]);
                        }
                    }
                }
                flash('Buku' . (!empty($currLoan['copy_serial']) ? ' (No. Seri: ' . e($currLoan['copy_serial']) . ')' : '') . ' berhasil dikonfirmasi telah dikembalikan.');
            }
            $pdo->commit();
        } catch (Throwable $e) {
            $pdo->rollBack();
            flash($e->getMessage(), 'error');
        }
        $redirUrl = 'index.php?page=loan_card&id=' . $loanId . ($tokenProvided ? '&token=' . urlencode($tokenProvided) : '');
        header('Location: ' . u($redirUrl));
        exit;
    }

    $ticketCode = 'PINJAM-' . date('Ym', strtotime($loan['created_at'])) . '-' . str_pad($loan['id'], 4, '0', STR_PAD_LEFT);
    $memberCode = $loan['member_code'] ?: ('2025' . str_pad($loan['member_id'], 3, '0', STR_PAD_LEFT));

    $statusClass = 'status-pill-pending';
    $statusText = 'Menunggu Persetujuan Admin';
    if ($loan['status'] === 'borrowed') {
        $statusClass = 'status-pill-borrowed';
        $statusText = 'Sedang Dipinjam (Aktif)';
    } elseif ($loan['status'] === 'returned') {
        $statusClass = 'status-pill-returned';
        $statusText = 'Sudah Dikembalikan';
    } elseif ($loan['status'] === 'rejected') {
        $statusClass = 'status-pill-rejected';
        $statusText = 'Ditolak';
    }

    $requestDateFmt = indonesian_date($loan['request_date']);
    $loanDateFmt = $loan['loan_date'] ? indonesian_date($loan['loan_date']) : 'Menunggu Serah Terima Admin';
    $dueDateFmt = $loan['due_date'] 
        ? indonesian_date($loan['due_date']) 
        : indonesian_date(date('Y-m-d', strtotime($loan['request_date'] . ' + 7 days'))) . ' (Estimasi 7 Hari)';

    $barcodeSvg = generate_barcode_svg($ticketCode, 230, 36);
    $qrSvg1 = generate_qr_svg($ticketCode, 78);
    $qrSvg2 = generate_qr_svg('SMKN5:NISN=' . $memberCode . '&BK=' . $loan['book_code'] . '&LOAN=' . $loan['id'], 78);

    $renderCard = function() use ($loan, $ticketCode, $memberCode, $statusClass, $statusText, $requestDateFmt, $loanDateFmt, $dueDateFmt, $barcodeSvg, $qrSvg1, $qrSvg2, $isAdmin, $isOwner) {
