                <div style="display:flex;gap:8px;align-items:center;">
                    <?php if ($isAdmin): ?>
                        <a href="<?=u('index.php?page=admin_loans')?>" class="btn btn-secondary btn-sm" style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;font-size:12px;">
                            <?=icon('arrow-left', '', 14)?> Kembali ke Data Peminjaman
                        </a>
                    <?php else: ?>
                        <a href="<?=u('index.php?page=member_loans')?>" class="btn btn-secondary btn-sm" style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;font-size:12px;">
                            <?=icon('arrow-left', '', 14)?> Buku Saya
                        </a>
                        <a href="<?=u('index.php?page=member')?>" class="btn btn-outline-primary btn-sm" style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;font-size:12px;">
