if ($page === 'profile') {
    auth();
    $sessionUser = $_SESSION['user'];
    $uid = (int)$sessionUser['id'];

    // Fetch fresh user data
    $uStmt = $pdo->prepare("SELECT * FROM users WHERE id = ? LIMIT 1");
    $uStmt->execute([$uid]);
    $uData = $uStmt->fetch();

    if (!$uData) {
        header('Location: ' . u('index.php?page=login'));
        exit;
    }

    $role = $uData['role'] ?? 'member';

    // Handle Profile Update
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $name = trim($_POST['name'] ?? '');
        $phone = trim($_POST['phone'] ?? '');
        $address = trim($_POST['address'] ?? '');
        $currentPass = (string)($_POST['current_password'] ?? '');
        $newPass = trim($_POST['password'] ?? '');
        $confirmPass = trim($_POST['confirm_password'] ?? '');

        if ($name === '') {
            flash('Nama lengkap tidak boleh kosong.', 'error');
        } elseif ($newPass !== '') {
            if ($currentPass === '') {
                flash('Untuk mengubah password akun, Anda wajib memasukkan password saat ini.', 'error');
            } elseif (!password_verify($currentPass, $uData['password_hash'])) {
                flash('Password saat ini salah. Penggantian password dibatalkan demi keamanan akun.', 'error');
            } elseif (strlen($newPass) < 6) {
                flash('Password baru minimal harus 6 karakter untuk mencegah upaya pembobolan.', 'error');
            } elseif ($newPass !== $confirmPass) {
                flash('Konfirmasi password baru tidak cocok. Silakan ulangi pengetikan password baru.', 'error');
            } else {
                // Handle Photo Upload
                $newPhotoName = null;
                if (!empty($_FILES['photo']['name']) && $_FILES['photo']['error'] === UPLOAD_ERR_OK) {
                    $uploaded = handle_member_photo_upload('photo', $sessionUser['photo'] ?? null);
                    if ($uploaded) {
                        $newPhotoName = $uploaded;
                    }
                }

                $hash = password_hash($newPass, PASSWORD_DEFAULT);
                if ($newPhotoName) {
                    $pdo->prepare("UPDATE users SET name = ?, phone = ?, address = ?, password_hash = ?, photo = ? WHERE id = ?")->execute([$name, $phone, $address, $hash, $newPhotoName, $uid]);
                } else {
                    $pdo->prepare("UPDATE users SET name = ?, phone = ?, address = ?, password_hash = ? WHERE id = ?")->execute([$name, $phone, $address, $hash, $uid]);
                }

                $_SESSION['user']['name'] = $name;
                $_SESSION['user']['phone'] = $phone;
                $_SESSION['user']['address'] = $address;
                $_SESSION['user']['password_hash'] = $hash;
                if ($newPhotoName) {
                    $_SESSION['user']['photo'] = $newPhotoName;
                }

                flash('Profil dan password baru Anda berhasil disimpan dengan aman.');
                header('Location: ' . u('index.php?page=profile'));
                exit;
            }
        } else {
            // Update profile info without changing password
            $newPhotoName = null;
            if (!empty($_FILES['photo']['name']) && $_FILES['photo']['error'] === UPLOAD_ERR_OK) {
                $uploaded = handle_member_photo_upload('photo', $sessionUser['photo'] ?? null);
                if ($uploaded) {
                    $newPhotoName = $uploaded;
                }
            }

            if ($newPhotoName) {
                $pdo->prepare("UPDATE users SET name = ?, phone = ?, address = ?, photo = ? WHERE id = ?")->execute([$name, $phone, $address, $newPhotoName, $uid]);
            } else {
                $pdo->prepare("UPDATE users SET name = ?, phone = ?, address = ? WHERE id = ?")->execute([$name, $phone, $address, $uid]);
            }

            // Refresh session data
            $_SESSION['user']['name'] = $name;
            $_SESSION['user']['phone'] = $phone;
            $_SESSION['user']['address'] = $address;
            if ($newPhotoName) {
                $_SESSION['user']['photo'] = $newPhotoName;
            }

            flash('Profil Anda berhasil diperbarui.');
            header('Location: ' . u('index.php?page=profile'));
            exit;
        }
        header('Location: ' . u('index.php?page=profile'));
        exit;
    }

