// ==========================================================================
// 10. PAGE: DASHBOARD ADMIN
// ==========================================================================
if ($page === 'admin') {
    auth('admin');

    // Handle POST Actions (Register Member by Admin)
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $action = $_POST['action'] ?? '';

        if ($action === 'admin_register_member') {
            $name = trim($_POST['name'] ?? '');
            $code = trim($_POST['member_code'] ?? '');
            $dept = trim($_POST['department'] ?? 'Siswa');
            $username = trim($_POST['username'] ?? '');
            $pass = trim($_POST['password'] ?? '123456');
            $phone = trim($_POST['phone'] ?? '');
            $address = trim($_POST['address'] ?? '');
            $status = trim($_POST['status'] ?? 'active');

            if ($pass === '') {
                $pass = '123456';
            }

            if ($name === '') {
                flash('Nama lengkap anggota wajib diisi.', 'error');
            } else {
                // Auto generate member code if empty
                if ($code === '') {
                    $pfx = 'AGT';
                    if (stripos($dept, 'Guru') !== false || stripos($dept, 'Pendidik') !== false) {
                        $pfx = 'GUR';
                    } elseif (stripos($dept, 'Tamu') !== false || stripos($dept, 'Luar') !== false) {
                        $pfx = 'TMU';
                    } elseif (stripos($dept, 'Staf') !== false || stripos($dept, 'TU') !== false) {
                        $pfx = 'STF';
                    }
                    $code = $pfx . date('y') . str_pad((string)mt_rand(100, 9999), 4, '0', STR_PAD_LEFT);
                }

                if ($username === '') {
                    $username = $code;
                }

                // Check duplicate
                $dupStmt = $pdo->prepare("SELECT id FROM users WHERE username = ? OR member_code = ? LIMIT 1");
                $dupStmt->execute([$username, $code]);
                if ($dupStmt->fetch()) {
                    flash('Username atau NISN / ID Anggota "' . e($code) . '" sudah digunakan oleh anggota lain.', 'error');
                } else {
                    $photoName = null;
                    if (!empty($_FILES['photo']['name']) && $_FILES['photo']['error'] === UPLOAD_ERR_OK) {
                        $photoName = handle_member_photo_upload('photo');
                    } elseif (!empty($_POST['preset_avatar'])) {
                        $preset = trim($_POST['preset_avatar']);
                        if (in_array($preset, ['assets/img/avatar_student_default.svg', 'assets/img/avatar_student_male.svg', 'assets/img/avatar_student_female.svg'], true)) {
                            $photoName = $preset;
                        }
                    }

                    $ins = $pdo->prepare("INSERT INTO users (role, username, password_hash, name, member_code, department, phone, address, status, photo) VALUES ('member', ?, ?, ?, ?, ?, ?, ?, ?, ?)");
                    $ins->execute([$username, password_hash($pass, PASSWORD_DEFAULT), $name, $code, $dept, $phone, $address, $status, $photoName]);
                    $newMemberId = (int)$pdo->lastInsertId();

                    flash('Anggota baru "' . $name . '" (ID: ' . $code . ') berhasil didaftarkan.');
                }
            }
            header('Location: ' . u('index.php?page=admin'));
            exit;
        }

        if ($action === 'set_member_status') {
            $mid = (int)($_POST['member_id'] ?? 0);
            $newStatus = trim($_POST['status'] ?? 'active');

            if ($mid > 0 && in_array($newStatus, ['active', 'inactive', 'pending'], true)) {
                $mStmt = $pdo->prepare("SELECT name FROM users WHERE id = ? AND role = 'member' LIMIT 1");
                $mStmt->execute([$mid]);
                $mem = $mStmt->fetch();

                if ($mem) {
                    $pdo->prepare("UPDATE users SET status = ? WHERE id = ? AND role = 'member'")->execute([$newStatus, $mid]);
                    $label = $newStatus === 'active' ? 'Aktif' : ($newStatus === 'inactive' ? 'Nonaktif' : 'Menunggu Verifikasi');
                    flash('Status akun anggota "' . $mem['name'] . '" berhasil diubah menjadi ' . $label . '.');
                }
            }

            $redirectUrl = !empty($_POST['redirect_to']) ? $_POST['redirect_to'] : u('index.php?page=admin_members');
            header('Location: ' . $redirectUrl);
            exit;
        }
    }

    // Counts
    $cBooks = (int)$pdo->query("SELECT COUNT(*) FROM books")->fetchColumn();
    $cMembers = (int)$pdo->query("SELECT COUNT(*) FROM users WHERE role = 'member' AND status = 'active'")->fetchColumn();
    $cBorrowed = (int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM loans WHERE status = 'borrowed'")->fetchColumn();
    $cOverdue = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE status = 'borrowed' AND due_date < CURDATE()")->fetchColumn();
    $cVisitsToday = (int)$pdo->query("SELECT COUNT(*) FROM visits WHERE visit_date = CURDATE()")->fetchColumn();

    // Recent Registered Members for Quick Card Printing
    $recentMembers = $pdo->query("SELECT id, name, member_code, department, phone, status, created_at FROM users WHERE role = 'member' ORDER BY id DESC LIMIT 5")->fetchAll();
    $allMembersForCard = $pdo->query("SELECT id, name, member_code, department FROM users WHERE role = 'member' ORDER BY name ASC")->fetchAll();

    // Recent Notifications (overdue, new registrations, loans, visits)
    $notifications = [
        ['Terlambat', 'Buku "Pemrograman Web" belum dikembalikan', '23-09-2025 08:30'],
        ['Pendaftaran', 'Anggota baru menunggu verifikasi', '23-09-2025 07:45'],
        ['Peminjaman', 'Peminjaman baru oleh Siti Rahma', '23-09-2025 07:20'],
        ['Kunjungan', 'Kunjungan perpustakaan hari ini', '23-09-2025 07:10'],
    ];

    // Data Grafik Kunjungan (Harian, Bulanan, Tahunan)
    $dailyRaw = $pdo->query("SELECT visit_date, COUNT(*) as cnt FROM visits WHERE visit_date >= DATE_SUB(CURDATE(), INTERVAL 6 DAY) GROUP BY visit_date")->fetchAll(PDO::FETCH_KEY_PAIR);
    $chartDaily = [];
    for ($i = 6; $i >= 0; $i--) {
        $dStr = date('Y-m-d', strtotime("-$i days"));
        $dDay = date('j', strtotime("-$i days"));
        $cnt = (int)($dailyRaw[$dStr] ?? 0);
        $chartDaily[] = ['label' => $dDay, 'full' => date('d M Y', strtotime($dStr)), 'count' => $cnt];
    }

    $monthlyRaw = $pdo->query("SELECT MONTH(visit_date) as m, COUNT(*) as cnt FROM visits WHERE YEAR(visit_date) = YEAR(CURDATE()) GROUP BY MONTH(visit_date)")->fetchAll(PDO::FETCH_KEY_PAIR);
    $monthLabels = [1=>'Jan',2=>'Feb',3=>'Mar',4=>'Apr',5=>'Mei',6=>'Jun',7=>'Jul',8=>'Agu',9=>'Sep',10=>'Okt',11=>'Nov',12=>'Des'];
    $chartMonthly = [];
    for ($m = 1; $m <= 12; $m++) {
        $cnt = (int)($monthlyRaw[$m] ?? 0);
        $chartMonthly[] = ['label' => $monthLabels[$m], 'full' => $monthLabels[$m] . ' ' . date('Y'), 'count' => $cnt];
    }

    $curYear = (int)date('Y');
    $yearlyRaw = $pdo->query("SELECT YEAR(visit_date) as y, COUNT(*) as cnt FROM visits WHERE YEAR(visit_date) >= " . ($curYear - 4) . " GROUP BY YEAR(visit_date)")->fetchAll(PDO::FETCH_KEY_PAIR);
    $chartYearly = [];
    for ($y = $curYear - 4; $y <= $curYear; $y++) {
        $cnt = (int)($yearlyRaw[$y] ?? 0);
        $chartYearly[] = ['label' => (string)$y, 'full' => 'Tahun ' . $y, 'count' => $cnt];
    }

    render_app_layout('admin', 'dashboard', 'Dashboard Admin', function() use ($cBooks, $cMembers, $cBorrowed, $cOverdue, $cVisitsToday, $notifications, $recentMembers, $allMembersForCard, $chartDaily, $chartMonthly, $chartYearly) {
