                    const lbl = document.getElementById('admin_reg_code_label');
                    if (!inp || !lbl) return;
                    if (val.indexOf('Guru') !== -1 || val.indexOf('Pendidik') !== -1) {
                        lbl.textContent = 'NIP / NUPTK Guru';
                        inp.placeholder = 'Contoh: 19780512 200301 1 004';
                    } else if (val.indexOf('Tamu') !== -1 || val.indexOf('Luar') !== -1) {
                        lbl.textContent = 'Nomor KTP / NIK Tamu';
                        inp.placeholder = 'Contoh: 16 Digit NIK KTP';
                    } else {
                        lbl.textContent = 'NISN / ID Siswa';
                        inp.placeholder = 'Contoh: 10 Digit NISN';
                    }
                }
                function generateRandomMemberCode() {
                    const deptElem = document.getElementById('admin_reg_dept');
                    const dept = deptElem ? deptElem.value : '';
                    let pfx = 'AGT';
                    if (dept.indexOf('Guru') !== -1) pfx = 'GUR';
                    else if (dept.indexOf('Tamu') !== -1) pfx = 'TMU';
                    else if (dept.indexOf('Staf') !== -1) pfx = 'STF';
                    const rand = Math.floor(1000 + Math.random() * 9000);
                    const now = new Date();
                    const yr = String(now.getFullYear()).substring(2);
                    const code = pfx + yr + rand;
                    const cInp = document.getElementById('admin_reg_code');
                    if (cInp) cInp.value = code;
                    const uInp = document.getElementById('admin_reg_username');
                    if (uInp && !uInp.value) uInp.value = code;
                }
