            <script>
            function switchVisitChart(type) {
                const dailyView = document.getElementById('chart_view_daily');
                const monthlyView = document.getElementById('chart_view_monthly');
                const yearlyView = document.getElementById('chart_view_yearly');

                const btnDaily = document.getElementById('tab_btn_daily');
                const btnMonthly = document.getElementById('tab_btn_monthly');
                const btnYearly = document.getElementById('tab_btn_yearly');

                const badge = document.getElementById('chart_period_badge');
                const stat = document.getElementById('chart_stat_info');

                btnDaily.classList.remove('active');
                btnMonthly.classList.remove('active');
                btnYearly.classList.remove('active');

                if (type === 'monthly') {
                    btnMonthly.classList.add('active');
                    dailyView.style.display = 'none';
                    monthlyView.style.display = 'block';
                    yearlyView.style.display = 'none';
