                    if (stat) stat.innerHTML = 'Total tahun <?=date("Y")?>: <b><?=array_sum(array_column($chartMonthly, "count"))?> kunjungan</b>';
                } else if (type === 'yearly') {
                    btnYearly.classList.add('active');
                    dailyView.style.display = 'none';
                    monthlyView.style.display = 'none';
                    yearlyView.style.display = 'block';
                    if (badge) badge.innerText = 'Tahunan (5 Tahun)';
                    if (stat) stat.innerHTML = 'Total 5 tahun terakhir: <b><?=array_sum(array_column($chartYearly, "count"))?> kunjungan</b>';
                } else {
                    btnDaily.classList.add('active');
                    dailyView.style.display = 'block';
                    monthlyView.style.display = 'none';
                    yearlyView.style.display = 'none';
                    if (badge) badge.innerText = 'Harian (7 Hari Terakhir)';
                    if (stat) stat.innerHTML = 'Total 7 hari terakhir: <b><?=array_sum(array_column($chartDaily, "count"))?> kunjungan</b>';
