// ==========================================================================
// 11. PAGE: MANAJEMEN PEMINJAMAN (ADMIN)
// ==========================================================================
if ($page === 'admin_loans' || $page === 'admin_returns') {
    auth('admin');

    // Handle Actions (Approve / Return / Reject / Create Loan by Admin)
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $act = $_POST['act'] ?? '';

        if ($act === 'create_loan') {
            $mid = (int)($_POST['member_id'] ?? 0);
            $bid = (int)($_POST['book_id'] ?? 0);
            $qty = max(1, (int)($_POST['quantity'] ?? 1));
            $days = max(1, (int)($_POST['days'] ?? 7));
            $lStatus = ($_POST['loan_status'] ?? 'borrowed') === 'pending' ? 'pending' : 'borrowed';
            $notes = trim($_POST['notes'] ?? '');

            if ($mid <= 0 || $bid <= 0) {
                flash('Pilih siswa/anggota dan buku terlebih dahulu.', 'error');
            } else {
                if (!$pdo->inTransaction()) {
                    $pdo->beginTransaction();
                }
                try {
                    // Kunci baris buku secara atomik untuk mencegah race condition / konkurensi stok
                    $bStmt = $pdo->prepare("SELECT id, title, available, quantity FROM books WHERE id = ? FOR UPDATE");
                    $bStmt->execute([$bid]);
                    $b = $bStmt->fetch();

                    // Kunci dan verifikasi keaktifan anggota
                    $mStmt = $pdo->prepare("SELECT id, name, department, status FROM users WHERE id = ? FOR UPDATE");
                    $mStmt->execute([$mid]);
                    $mem = $mStmt->fetch();

                    if (!$b) {
                        throw new Exception('Buku tidak ditemukan dalam database.');
                    }
                    if (!$mem || ($mem['status'] ?? '') !== 'active') {
                        throw new Exception('Anggota tidak ditemukan atau akun sedang tidak aktif.');
                    }

                    $dept = $mem['department'] ?? '';
                    $isGuru = (stripos($dept, 'Guru') !== false || stripos($dept, 'Pendidik') !== false || stripos($dept, 'Tendik') !== false || stripos($dept, 'Pegawai') !== false || stripos($dept, 'Staf') !== false || stripos($dept, 'Dosen') !== false);

                    if ($qty > (int)$b['available']) {
                        throw new Exception('Stok buku "' . $b['title'] . '" tidak mencukupi (tersedia: ' . number_format((int)$b['available'], 0, ',', '.') . ' eksemplar).');
                    }
                    if (!$isGuru && $qty > 5) {
                        throw new Exception('Untuk siswa/anggota umum, batas maksimal peminjaman adalah 5 eksemplar. Khusus guru/tendik diperbolehkan meminjam tanpa batas sesuai stok buku.');
                    }

                    $dueDate = date('Y-m-d', strtotime("+$days days"));
                    $copySerial = trim($_POST['copy_serial'] ?? '');

                    if ($lStatus === 'borrowed') {
                        // Pembaruan stok bersyarat untuk menjamin stok tidak pernah tembus di bawah 0
                        $updBook = $pdo->prepare("UPDATE books SET available = available - ? WHERE id = ? AND available >= ?");
                        $updBook->execute([$qty, $bid, $qty]);
                        if ($updBook->rowCount() === 0) {
                            throw new Exception('Stok buku tidak mencukupi atau telah dipinjam oleh transaksi bersamaan.');
                        }

                        $ins = $pdo->prepare("INSERT INTO loans (member_id, book_id, quantity, copy_serial, request_date, loan_date, due_date, status, notes) VALUES (?, ?, ?, ?, CURDATE(), CURDATE(), ?, 'borrowed', ?)");
                        $ins->execute([$mid, $bid, $qty, $copySerial ?: null, $dueDate, $notes]);

                        if ($copySerial !== '') {
                            foreach (explode(',', $copySerial) as $sCode) {
                                $sCode = trim($sCode);
                                if ($sCode !== '') {
                                    $pdo->prepare("UPDATE book_copies SET status = 'borrowed' WHERE book_id = ? AND copy_code = ?")->execute([$bid, $sCode]);
                                }
                            }
                        }
                        $pdo->commit();
                        flash('Peminjaman ' . number_format($qty, 0, ',', '.') . ' eksemplar buku' . ($copySerial ? ' (No. Seri: ' . e($copySerial) . ')' : '') . ' untuk ' . e($mem['name']) . ($isGuru ? ' (Guru/Tendik)' : '') . ' berhasil dicatat.');
                    } else {
                        $ins = $pdo->prepare("INSERT INTO loans (member_id, book_id, quantity, copy_serial, request_date, status, notes) VALUES (?, ?, ?, ?, CURDATE(), 'pending', ?)");
                        $ins->execute([$mid, $bid, $qty, $copySerial ?: null, $notes]);
                        $pdo->commit();
                        flash('Pengajuan peminjaman ' . number_format($qty, 0, ',', '.') . ' eksemplar buku berhasil disimpan dan menunggu persetujuan.');
                    }
                } catch (Throwable $e) {
                    if ($pdo->inTransaction()) {
                        $pdo->rollBack();
                    }
                    flash($e->getMessage(), 'error');
                }
            }
            header('Location: ' . u('index.php?page=admin_loans&tab=' . ($lStatus === 'pending' ? 'pending' : 'borrowed')));
            exit;
        }

        $id = (int)($_POST['id'] ?? 0);
        if (!$pdo->inTransaction()) {
            $pdo->beginTransaction();
        }
        try {
            $stmt = $pdo->prepare("SELECT * FROM loans WHERE id = ? FOR UPDATE");
            $stmt->execute([$id]);
            $loan = $stmt->fetch();

            if (!$loan) throw new Exception('Peminjaman tidak ditemukan.');

            if ($act === 'approve' && $loan['status'] === 'pending') {
                $bStmt = $pdo->prepare("SELECT available, quantity, copy_serials FROM books WHERE id = ? FOR UPDATE");
                $bStmt->execute([$loan['book_id']]);
                $b = $bStmt->fetch();

                if (!$b || (int)$b['available'] < (int)$loan['quantity']) {
                    throw new Exception('Stok buku tidak mencukupi untuk menyetujui peminjaman ini.');
                }

                $assignedSerial = trim($_POST['copy_serial'] ?? ($loan['copy_serial'] ?? ''));
                $dueDate = date('Y-m-d', strtotime('+7 days'));

                // Pembaruan stok bersyarat untuk mencegah over-borrowing pada konkurensi
                $updBook = $pdo->prepare("UPDATE books SET available = available - ? WHERE id = ? AND available >= ?");
                $updBook->execute([$loan['quantity'], $loan['book_id'], $loan['quantity']]);
                if ($updBook->rowCount() === 0) {
                    throw new Exception('Stok buku tidak mencukupi atau telah dipinjam oleh transaksi bersamaan.');
                }

                $pdo->prepare("UPDATE loans SET status='borrowed', copy_serial=?, loan_date=CURDATE(), due_date=? WHERE id=?")->execute([$assignedSerial ?: null, $dueDate, $id]);
                if ($assignedSerial !== '') {
                    foreach (explode(',', $assignedSerial) as $sCode) {
                        $sCode = trim($sCode);
                        if ($sCode !== '') {
                            $pdo->prepare("UPDATE book_copies SET status = 'borrowed' WHERE book_id = ? AND copy_code = ?")->execute([$loan['book_id'], $sCode]);
                        }
                    }
                }
                flash('Peminjaman telah disetujui dan buku fisik' . ($assignedSerial ? ' (No. Seri: ' . e($assignedSerial) . ')' : '') . ' siap diserahkan.');
            } elseif ($act === 'reject' && $loan['status'] === 'pending') {
                $pdo->prepare("UPDATE loans SET status='rejected' WHERE id=?")->execute([$id]);
                flash('Pengajuan peminjaman telah ditolak.');
            } elseif ($act === 'return' && $loan['status'] === 'borrowed') {
                $pdo->prepare("UPDATE loans SET status='returned', return_date=CURDATE() WHERE id=?")->execute([$id]);
                $pdo->prepare("UPDATE books SET available = LEAST(quantity, available + ?) WHERE id=?")->execute([$loan['quantity'], $loan['book_id']]);
                if (!empty($loan['copy_serial'])) {
                    foreach (explode(',', (string)$loan['copy_serial']) as $sCode) {
                        $sCode = trim($sCode);
                        if ($sCode !== '') {
                            $pdo->prepare("UPDATE book_copies SET status = 'available' WHERE book_id = ? AND copy_code = ?")->execute([$loan['book_id'], $sCode]);
                        }
                    }
                }
                flash('Buku' . (!empty($loan['copy_serial']) ? ' (No. Seri: ' . e($loan['copy_serial']) . ')' : '') . ' berhasil dikembalikan dan stok diperbarui.');
            }
            $pdo->commit();
        } catch (Throwable $e) {
            if ($pdo->inTransaction()) {
                $pdo->rollBack();
            }
            flash($e->getMessage(), 'error');
        }
        $redirTab = !empty($_GET['tab']) ? ('&tab=' . urlencode($_GET['tab'])) : '';
        header('Location: ' . u('index.php?page=admin_loans' . $redirTab));
        exit;
    }

    $tab = $_GET['tab'] ?? ($page === 'admin_returns' ? 'returned' : 'all');
    $q = trim($_GET['q'] ?? '');
    $statusFilter = $_GET['status'] ?? '';

    // Tab counts
    $cAll = (int)$pdo->query("SELECT COUNT(*) FROM loans")->fetchColumn();
    $cPending = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE status = 'pending'")->fetchColumn();
    $cBorrowed = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE status = 'borrowed'")->fetchColumn();
    $cReturned = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE status = 'returned'")->fetchColumn();
    $cOverdue = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE status = 'borrowed' AND due_date < CURDATE()")->fetchColumn();

    // Books and members for Quick Add Modal
    $allActiveMembers = $pdo->query("SELECT id, name, member_code, department FROM users WHERE role = 'member' AND status = 'active' ORDER BY name ASC")->fetchAll();
    $allAvailBooks = $pdo->query("SELECT id, code, title, available, copy_serials FROM books WHERE available > 0 ORDER BY title ASC")->fetchAll();

    $sql = "SELECT l.*, 
                   COALESCE(u.name, '(Anggota Diarsipkan)') as member_name, 
                   COALESCE(u.member_code, '-') as member_code, 
                   COALESCE(u.department, '-') as department, 
                   u.phone as member_phone, 
                   COALESCE(b.title, '(Buku Diarsipkan)') as book_title, 
                   COALESCE(b.code, '-') as book_code, 
                   b.copy_serials as book_copy_serials 
            FROM loans l 
            LEFT JOIN users u ON u.id = l.member_id 
            LEFT JOIN books b ON b.id = l.book_id WHERE 1=1";
    $params = [];

    if ($tab === 'pending') {
        $sql .= " AND l.status = 'pending'";
    } elseif ($tab === 'borrowed') {
        $sql .= " AND l.status = 'borrowed'";
    } elseif ($tab === 'returned') {
        $sql .= " AND l.status = 'returned'";
    } elseif ($tab === 'overdue') {
        $sql .= " AND l.status = 'borrowed' AND l.due_date < CURDATE()";
    }

    if ($statusFilter) {
        $sql .= " AND l.status = ?";
        $params[] = $statusFilter;
    }

    if ($q) {
        $sql .= " AND (u.name LIKE ? OR u.member_code LIKE ? OR b.title LIKE ? OR b.code LIKE ? OR l.copy_serial LIKE ?)";
        $like = "%$q%";
        $params[] = $like;
        $params[] = $like;
        $params[] = $like;
        $params[] = $like;
        $params[] = $like;
    }

    $sql .= " ORDER BY l.id DESC LIMIT 150";
    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);
    $rows = $stmt->fetchAll();

    render_app_layout('admin', 'loans', 'Manajemen Peminjaman', function() use ($rows, $tab, $q, $statusFilter, $cAll, $cPending, $cBorrowed, $cReturned, $cOverdue, $allActiveMembers, $allAvailBooks) {
        ?>
        <!-- Tab Bar with Count Badges & Quick Loan Button -->
        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:18px;">
            <div class="nav-tabs-pill" style="margin:0;">
                <a href="<?=u('index.php?page=admin_loans')?>" class="<?=$tab==='all'?'active':''?>">
                    Semua <span class="badge badge-gray" style="font-size:11px;margin-left:4px;"><?=$cAll?></span>
                </a>
                <a href="<?=u('index.php?page=admin_loans&tab=pending')?>" class="<?=$tab==='pending'?'active':''?>">
                    Pengajuan <span class="badge <?=$cPending>0?'badge-yellow':'badge-gray'?>" style="font-size:11px;margin-left:4px;"><?=$cPending?></span>
                </a>
                <a href="<?=u('index.php?page=admin_loans&tab=borrowed')?>" class="<?=$tab==='borrowed'?'active':''?>">
                    Peminjaman <span class="badge <?=$cBorrowed>0?'badge-blue':'badge-gray'?>" style="font-size:11px;margin-left:4px;"><?=$cBorrowed?></span>
                </a>
                <a href="<?=u('index.php?page=admin_loans&tab=returned')?>" class="<?=$tab==='returned'?'active':''?>">
                    Pengembalian <span class="badge badge-gray" style="font-size:11px;margin-left:4px;"><?=$cReturned?></span>
                </a>
                <a href="<?=u('index.php?page=admin_loans&tab=overdue')?>" class="<?=$tab==='overdue'?'active':''?>">
                    Buku Terlambat <span class="badge <?=$cOverdue>0?'badge-red':'badge-gray'?>" style="font-size:11px;margin-left:4px;"><?=$cOverdue?></span>
                </a>
