            <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
                <!-- Tombol 1: Pinjam Kilat / Scanner Gun -->
                <button type="button" class="btn" onclick="openQuickLoanModal()" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;padding:8px 14px;background:#059669;color:#ffffff;border:none;border-radius:6px;box-shadow:0 3px 10px rgba(5,150,105,0.25);cursor:pointer;transition:all 0.15s;" onmouseover="this.style.background='#047857'" onmouseout="this.style.background='#059669'" title="Pinjam Kilat menggunakan Scanner Gun Barcode / QR">
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"></path></svg>
