        <div class="card-box">
            <!-- Filter Bar -->
            <form method="get" style="display:flex;gap:12px;margin-bottom:20px;flex-wrap:wrap;">
                <input type="hidden" name="page" value="admin_loans">
                <?php if ($tab): ?><input type="hidden" name="tab" value="<?=e($tab)?>"><?php endif; ?>
                <input type="text" name="q" value="<?=e($q)?>" placeholder="Cari Siswa / ID / Judul / Kode Buku..." class="form-control" style="flex:1;min-width:200px;">
                <select name="status" class="form-control" style="width:160px;">
                    <option value="">Semua Status</option>
                    <option value="pending" <?=$statusFilter==='pending'?'selected':''?>>Menunggu (Pengajuan)</option>
                    <option value="borrowed" <?=$statusFilter==='borrowed'?'selected':''?>>Dipinjam (Aktif)</option>
                    <option value="returned" <?=$statusFilter==='returned'?'selected':''?>>Dikembalikan</option>
                </select>
