                <div style="padding:20px;display:flex;flex-direction:column;gap:16px;">
                    <!-- Input Scan Barcode Pengembalian -->
                    <div style="background:#fffbeb;border:1.5px solid #fcd34d;border-radius:12px;padding:16px;">
                        <label style="font-weight:800;font-size:13.5px;color:#92400e;display:flex;align-items:center;gap:6px;margin-bottom:8px;">
                            <span>📦 Scan Barcode / Nomor Seri Buku yang Dikembalikan: <span style="color:var(--red);">*</span></span>
                        </label>
                        <input type="text" id="qrBookInput" oninput="handleQrInputAuto(this.value)" onkeydown="if(event.key==='Enter'||event.key==='Tab'){event.preventDefault();submitQuickScanReturn(this.value);}" onpaste="setTimeout(()=>{submitQuickScanReturn(this.value);},40);" onchange="submitQuickScanReturn(this.value);" placeholder="Arahkan scanner ke Barcode Buku (contoh: BK-005-01) [Otomatis Kembali Tanpa Enter]..." class="form-control" style="font-size:14px;font-weight:600;padding:10px 12px;border:1.5px solid #d97706;border-radius:8px;background:#ffffff;" autocomplete="off">
                        <div id="qrFeedback" style="margin-top:8px;font-size:12.5px;display:none;"></div>
                    </div>

                    <!-- Riwayat Pengembalian Sesi Ini -->
                    <div>
                        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">
                            <span style="font-size:12px;font-weight:700;color:var(--navy);">Riwayat Pengembalian Sesi Ini:</span>
                            <span id="qrSessionCount" style="font-size:11px;color:var(--text-muted);">0 buku dikembalikan</span>
                        </div>
                        <div id="qrSessionList" style="max-height:180px;overflow-y:auto;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:8px;display:flex;flex-direction:column;gap:6px;font-size:12px;">
                            <div style="color:var(--text-muted);text-align:center;padding:12px 0;">Belum ada buku yang dikembalikan dalam sesi ini.</div>
                        </div>
                    </div>

                    <div style="display:flex;justify-content:flex-end;gap:10px;padding-top:10px;border-top:1px solid #f1f5f9;">
                        <button type="button" class="btn btn-primary" onclick="closeQuickReturnModal()" style="font-weight:700;padding:8px 20px;">
                            Selesai &amp; Tutup
                        </button>
                    </div>
                </div>
            </div>
        </div>

        <!-- Load HTML5 QR Code & Barcode Scanner Library -->
        <script src="<?=u('assets/js/html5-qrcode.min.js')?>"></script>
        <script>
        let masValidSerials = [];
        let masHtml5Scanner = null;
        let masAvailableCameras = [];
        let masSelectedCameraId = null;

        function playScanChime() {
            try {
                const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
                const osc = audioCtx.createOscillator();
                const gain = audioCtx.createGain();
                osc.connect(gain);
                gain.connect(audioCtx.destination);
                osc.type = 'sine';
                osc.frequency.setValueAtTime(880, audioCtx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(1320, audioCtx.currentTime + 0.12);
                gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
                gain.gain.linearRampToValueAtTime(0.01, audioCtx.currentTime + 0.12);
                osc.start(audioCtx.currentTime);
                osc.stop(audioCtx.currentTime + 0.12);
            } catch(e) {}
        }

        function openApproveScanModal(loanId, memberName, memberCode, bookTitle, bookCode, bookId, rawSerials) {
            const modal = document.getElementById('modalApproveScan');
            if (!modal) return;

            document.getElementById('masLoanId').value = loanId;
            document.getElementById('masMemberName').textContent = memberName || '-';
            document.getElementById('masMemberCode').textContent = memberCode ? ('NISN: ' + memberCode) : '';
            document.getElementById('masBookTitle').textContent = bookTitle || '-';
            document.getElementById('masBookCode').textContent = bookCode ? ('Kode: ' + bookCode) : '';

            const input = document.getElementById('masSerialInput');
            const feedback = document.getElementById('masFeedback');
            const dropdown = document.getElementById('masSerialDropdown');
            const countBadge = document.getElementById('masAvailableCount');

            input.value = '';
            feedback.style.display = 'none';
            dropdown.innerHTML = '<option value="">-- Pilih dari Eksemplar Tersedia --</option>';

            try {
                masValidSerials = typeof rawSerials === 'string' ? JSON.parse(rawSerials || '[]') : (rawSerials || []);
            } catch(e) { masValidSerials = []; }

            // Fetch live status for this book's available serials
            fetch('<?=u("index.php?page=api_book_serials&book_id=")?>' + encodeURIComponent(bookId))
                .then(res => res.json())
                .then(data => {
                    if (data.success && Array.isArray(data.items)) {
                        const availItems = data.items.filter(it => it.status === 'available');
                        dropdown.innerHTML = '<option value="">-- Pilih dari Eksemplar Tersedia (' + availItems.length + ' buku di rak) --</option>';
                        availItems.forEach(it => {
                            const opt = document.createElement('option');
                            opt.value = it.serial;
                            opt.textContent = '#' + it.num + ': ' + it.serial + ' (Tersedia)';
                            dropdown.appendChild(opt);
                        });
                        countBadge.textContent = availItems.length + ' eksemplar di rak';
                    }
                })
                .catch(e => {});

            modal.style.display = 'flex';
            setTimeout(() => { if (input) input.focus(); }, 150);
        }

        function closeApproveScanModal() {
            const modal = document.getElementById('modalApproveScan');
            if (modal) modal.style.display = 'none';
            stopMasCamera();
        }

        function handleMasSerialInput(val) {
            val = (val || '').trim();
            const feedback = document.getElementById('masFeedback');
            const dropdown = document.getElementById('masSerialDropdown');
            if (!val) {
                feedback.style.display = 'none';
                return;
            }

            if (dropdown) dropdown.value = val;

            const isMatched = masValidSerials.some(s => s.toLowerCase() === val.toLowerCase());
            feedback.style.display = 'block';
            if (isMatched) {
                feedback.style.color = '#15803d';
                feedback.innerHTML = '✓ Eksemplar valid &amp; sesuai dengan buku ini!';
            } else {
                feedback.style.color = '#b45309';
                feedback.innerHTML = 'ℹ️ Nomor seri terdeteksi (pastikan buku fisik sesuai).';
            }
        }

        function handleMasScanKey(e) {
            if (e.key === 'Enter') {
                e.preventDefault();
                const input = document.getElementById('masSerialInput');
                if (input && input.value.trim() !== '') {
                    playScanChime();
                    handleMasSerialInput(input.value);
                    setTimeout(() => {
                        document.getElementById('masApproveForm').submit();
                    }, 250);
                }
            }
        }

        function onMasDropdownSelect(val) {
            const input = document.getElementById('masSerialInput');
            if (input && val) {
                input.value = val;
                handleMasSerialInput(val);
                playScanChime();
            }
        }

        function submitMasWithoutSerial() {
            if (confirm('Setujui peminjaman ini tanpa mencatat nomor seri eksemplar?')) {
                document.getElementById('masSerialInput').value = '';
                document.getElementById('masApproveForm').submit();
            }
        }

        function toggleMasCamera() {
            const container = document.getElementById('masCameraContainer');
            if (!container) return;
            if (container.style.display === 'block') {
                stopMasCamera();
            } else {
                startMasCamera();
            }
        }

        async function startMasCamera() {
            const container = document.getElementById('masCameraContainer');
            const statusBox = document.getElementById('masCameraStatus');
            const camSelect = document.getElementById('masCamSelect');
            const btn = document.getElementById('masCamBtn');
            if (!container) return;

            container.style.display = 'block';
            if (statusBox) {
                statusBox.style.display = 'block';
                statusBox.innerHTML = '<span style="color:#38bdf8;">⏳ Mengakses kamera... Pastikan browser memberi izin kamera.</span>';
            }
            if (btn) {
                btn.innerHTML = '⏹ Stop Kamera';
                btn.className = 'btn btn-outline-danger';
            }

            if (typeof Html5Qrcode === 'undefined') {
                if (statusBox) {
                    statusBox.innerHTML = '<div style="color:#ef4444;background:#fff;padding:8px;border-radius:4px;">Modul scanner kamera tidak termuat. Silakan muat ulang halaman atau gunakan scanner gun USB.</div>';
                }
                return;
            }

            try {
                // Enumerate cameras if not yet enumerated
                if (masAvailableCameras.length === 0) {
                    try {
                        const devices = await Html5Qrcode.getCameras();
                        if (devices && devices.length > 0) {
                            masAvailableCameras = devices;
                            if (camSelect) {
                                camSelect.innerHTML = '';
                                devices.forEach((cam, idx) => {
                                    const opt = document.createElement('option');
                                    opt.value = cam.id;
                                    opt.text = cam.label || ('Kamera ' + (idx + 1));
                                    camSelect.appendChild(opt);
                                });
                                camSelect.style.display = (devices.length > 1) ? 'inline-block' : 'none';
                            }
                            const rear = devices.find(d => /back|rear|belakang|environment/i.test(d.label));
                            masSelectedCameraId = rear ? rear.id : devices[0].id;
                            if (camSelect) camSelect.value = masSelectedCameraId;
                        }
                    } catch(enumErr) {
                        console.warn('Enum cameras notice:', enumErr);
                    }
                }

                if (!masHtml5Scanner) {
                    masHtml5Scanner = new Html5Qrcode("masCameraLiveView");
                }

                let cameraConfig = masSelectedCameraId 
                    ? { deviceId: { exact: masSelectedCameraId } }
                    : { facingMode: "environment" };

                const scanConfig = {
                    fps: 15,
                    qrbox: function(w, h) {
                        return { width: Math.min(w - 20, 280), height: Math.min(h - 20, 160) };
                    },
                    aspectRatio: 1.333333,
                    experimentalFeatures: {
                        useBarCodeDetectorIfSupported: true
                    }
                };

                const onScanSuccess = (decodedText) => {
                    const cleanText = (decodedText || '').trim();
                    if (!cleanText) return;

                    const input = document.getElementById('masSerialInput');
                    if (input) {
                        input.value = cleanText;
                        handleMasSerialInput(cleanText);
                    }
                    playScanChime();
                    stopMasCamera();
                    setTimeout(() => {
                        const form = document.getElementById('masApproveForm');
                        if (form) form.submit();
                    }, 350);
                };

                try {
                    await masHtml5Scanner.start(cameraConfig, scanConfig, onScanSuccess, () => {});
                    if (statusBox) statusBox.style.display = 'none';
                } catch(startErr) {
                    console.warn('First camera attempt failed, retrying with default:', startErr);
                    await masHtml5Scanner.start({ facingMode: "user" }, scanConfig, onScanSuccess, () => {});
                    if (statusBox) statusBox.style.display = 'none';
                }
            } catch(err) {
                console.error('Camera error:', err);
                if (statusBox) {
                    statusBox.style.display = 'block';
                    statusBox.innerHTML = '<div style="color:#ef4444;background:#fff;padding:10px;border-radius:6px;font-size:12px;text-align:left;">' +
                        '<b>⚠️ Tidak dapat menyalakan kamera:</b> ' + (err.message || err) + '<br>' +
                        '<small style="color:#64748b;display:block;margin-top:4px;">Tips: Pastikan browser memiliki izin kamera dan tidak sedang digunakan aplikasi lain, atau langsung scan menggunakan barcode gun USB.</small>' +
                        '</div>';
                }
            }
        }

        async function onMasCameraChange(camId) {
            masSelectedCameraId = camId;
            if (masHtml5Scanner) {
                try {
                    if (masHtml5Scanner.isScanning) {
                        await masHtml5Scanner.stop();
                    }
                    masHtml5Scanner.clear();
                } catch(e) {}
                masHtml5Scanner = null;
                startMasCamera();
            }
        }

        function stopMasCamera() {
            const container = document.getElementById('masCameraContainer');
            const statusBox = document.getElementById('masCameraStatus');
            const btn = document.getElementById('masCamBtn');
            if (masHtml5Scanner) {
                const scanner = masHtml5Scanner;
                masHtml5Scanner = null;
                try {
                    if (scanner.isScanning) {
                        scanner.stop().then(() => {
                            try { scanner.clear(); } catch(e) {}
                        }).catch(() => {
                            try { scanner.clear(); } catch(e) {}
                        });
                    } else {
                        try { scanner.clear(); } catch(e) {}
                    }
                } catch(e) {
                    try { scanner.clear(); } catch(err) {}
                }
            }
            if (container) container.style.display = 'none';
            if (statusBox) statusBox.style.display = 'none';
            if (btn) {
                btn.innerHTML = '📷 Kamera';
                btn.className = 'btn btn-outline-success';
            }
        }

        function updateLoanLimits() {
            const memSel = document.getElementById('loan_member_select');
            const bookSel = document.getElementById('loan_book_select');
            const qtyInput = document.getElementById('loan_quantity_input');
            const badge = document.getElementById('loan_qty_badge');
            const hint = document.getElementById('loan_qty_hint');
            const serialGroup = document.getElementById('loan_serial_group');
            const serialSelect = document.getElementById('loan_serial_dropdown');
            const serialInput = document.getElementById('loan_serial_text');
            const serialBadge = document.getElementById('loan_serial_badge');
            if (!memSel || !bookSel || !qtyInput) return;

            const optMem = memSel.options[memSel.selectedIndex];
            const optBook = bookSel.options[bookSel.selectedIndex];

            const isGuru = optMem && optMem.getAttribute('data-is-guru') === '1';
            const hasBook = optBook && optBook.value !== '';
            const avail = hasBook ? parseInt(optBook.getAttribute('data-available') || '0', 10) : 0;

            // Sync serial numbers dropdown
            if (serialSelect && optBook) {
                const rawSerials = optBook.getAttribute('data-serials');
                let serialList = [];
                try {
                    serialList = JSON.parse(rawSerials || '[]');
                } catch(e) { serialList = []; }

                serialSelect.innerHTML = '<option value="">-- Pilih No. Seri --</option>';
                if (serialList && serialList.length > 0) {
                    serialList.forEach(s => {
                        const opt = document.createElement('option');
                        opt.value = s;
                        opt.textContent = s;
                        serialSelect.appendChild(opt);
                    });
                    if (serialBadge) {
                        serialBadge.textContent = '🏷️ ' + serialList.length + ' nomor seri terdata';
                        serialBadge.style.color = '#0284c7';
                    }
                    if (serialSelect) serialSelect.style.display = 'block';
                } else {
                    if (serialBadge) {
                        serialBadge.textContent = 'Buku tanpa nomor seri';
                        serialBadge.style.color = '#94a3b8';
                    }
                    if (serialSelect) serialSelect.style.display = 'none';
                    if (serialInput) serialInput.value = '';
                }
            }

            if (isGuru) {
                if (hasBook && avail > 0) {
                    qtyInput.max = avail;
                    if (badge) { badge.textContent = 'Khusus Guru: Bebas s.d ' + avail.toLocaleString() + ' buku'; badge.style.color = '#15803d'; }
                    if (hint) { hint.textContent = '✓ Guru/Tendik boleh meminjam berapapun hingga batas stok tersedia (' + avail.toLocaleString() + ' eksemplar).'; hint.style.color = '#15803d'; }
                } else {
                    qtyInput.removeAttribute('max');
                    if (badge) { badge.textContent = 'Khusus Guru: Bebas sesuai stok'; badge.style.color = '#15803d'; }
                    if (hint) { hint.textContent = '✓ Guru/Tendik boleh meminjam berapapun tanpa batas (sesuai stok buku).'; hint.style.color = '#15803d'; }
                }
            } else {
                const maxSiswa = (hasBook && avail > 0) ? Math.min(5, avail) : 5;
                qtyInput.max = maxSiswa;
                if (badge) { badge.textContent = 'Maks. ' + maxSiswa + ' buku (Siswa)'; badge.style.color = '#64748b'; }
                if (hint) { hint.textContent = 'Standar siswa/anggota umum: maksimal ' + maxSiswa + ' eksemplar.'; hint.style.color = '#64748b'; }
            }
        }

        function onLoanSerialDropdownChange() {
            const sel = document.getElementById('loan_serial_dropdown');
            const txt = document.getElementById('loan_serial_text');
            if (sel && txt && sel.value) {
                txt.value = sel.value;
                playScanChime();
            }
        }

