        }

        // =====================================================================
        // AUTOCOMPLETE SEARCH SISWA/ANGGOTA (MODAL CATAT PEMINJAMAN)
        // =====================================================================
        (function() {
            function initMemberSearchAutocomplete() {
                const searchInput = document.getElementById('loan_member_search');
                const dropdownList = document.getElementById('loan_member_dropdown_list');
                const memberSelect = document.getElementById('loan_member_select');
                const clearBtn = document.getElementById('loan_member_clear_btn');
                const selectedBadge = document.getElementById('loan_member_selected_badge');

                if (!searchInput || !dropdownList || !memberSelect) return;

                // Ekstrak data semua anggota
                const memberData = [];
                for (let i = 0; i < memberSelect.options.length; i++) {
                    const opt = memberSelect.options[i];
                    if (!opt.value) continue;
                    memberData.push({
                        id: opt.value,
                        name: opt.getAttribute('data-name') || opt.text,
                        code: opt.getAttribute('data-code') || '',
                        dept: opt.getAttribute('data-dept') || '',
                        isGuru: opt.getAttribute('data-is-guru') === '1',
                        rawText: (opt.text || '').toLowerCase()
                    });
                }

                let activeIndex = -1;

                function escapeHtml(str) {
                    return (str || '').replace(/[&<>"']/g, function(m) {
                        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m];
                    });
                }

                function escapeRegex(str) {
                    return (str || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                }

                function renderDropdown(items, query) {
                    dropdownList.innerHTML = '';
                    activeIndex = -1;

                    if (items.length === 0) {
                        dropdownList.innerHTML = '<div style="padding:12px;font-size:12px;color:#64748b;text-align:center;">Tidak ada anggota yang cocok dengan "<b>' + escapeHtml(query) + '</b>"</div>';
                        dropdownList.style.display = 'block';
                        return;
                    }

                    // Tampilkan maksimal 35 hasil agar performa tetap instan
                    const limited = items.slice(0, 35);
                    limited.forEach((item, idx) => {
                        const row = document.createElement('div');
                        row.className = 'loan-mem-item';
                        row.dataset.index = idx;
                        row.style.cssText = 'padding:9px 12px;cursor:pointer;border-bottom:1px solid #f1f5f9;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12.5px;transition:background 0.1s;';

                        let displayName = escapeHtml(item.name);
                        let displayCode = escapeHtml(item.code);
                        if (query) {
                            const reg = new RegExp('(' + escapeRegex(query) + ')', 'gi');
                            displayName = displayName.replace(reg, '<mark style="background:#fef08a;padding:0 2px;border-radius:2px;color:#000;">$1</mark>');
                            displayCode = displayCode.replace(reg, '<mark style="background:#fef08a;padding:0 2px;border-radius:2px;color:#000;">$1</mark>');
                        }

                        const badge = item.isGuru 
                            ? '<span style="font-size:10px;padding:2px 7px;border-radius:10px;background:#fef3c7;color:#b45309;font-weight:700;">Guru</span>'
                            : '<span style="font-size:10px;padding:2px 7px;border-radius:10px;background:#e0f2fe;color:#0284c7;font-weight:700;">' + escapeHtml(item.dept || 'Siswa') + '</span>';

                        row.innerHTML = '<div><b style="color:var(--navy);">' + displayName + '</b> <span style="color:#64748b;font-size:11.5px;">[' + displayCode + ']</span></div><div>' + badge + '</div>';

                        row.addEventListener('mouseenter', () => setActiveItem(idx));
                        row.addEventListener('click', () => selectMember(item));

                        dropdownList.appendChild(row);
                    });

                    dropdownList.style.display = 'block';
                }

                function setActiveItem(idx) {
                    const rows = dropdownList.querySelectorAll('.loan-mem-item');
                    rows.forEach((r, i) => {
                        if (i === idx) {
                            r.style.background = '#f0fdf4';
                            r.scrollIntoView({ block: 'nearest' });
                        } else {
                            r.style.background = '#ffffff';
                        }
                    });
                    activeIndex = idx;
                }

                function selectMember(item) {
                    searchInput.value = item.name + ' [' + item.code + '] - ' + (item.dept || 'Umum');
                    searchInput.style.borderColor = '#16a34a';
                    memberSelect.value = item.id;
                    if (clearBtn) clearBtn.style.display = 'block';
                    if (selectedBadge) selectedBadge.style.display = 'inline-block';
                    dropdownList.style.display = 'none';
                    updateLoanLimits();
                }

                window.clearLoanMemberSearch = function() {
                    searchInput.value = '';
                    searchInput.style.borderColor = '#cbd5e1';
                    memberSelect.value = '';
                    if (clearBtn) clearBtn.style.display = 'none';
                    if (selectedBadge) selectedBadge.style.display = 'none';
                    dropdownList.style.display = 'none';
                    updateLoanLimits();
                    searchInput.focus();
                };

                searchInput.addEventListener('input', function() {
                    const q = this.value.trim().toLowerCase();
                    if (clearBtn) clearBtn.style.display = q ? 'block' : 'none';
                    if (!q) {
                        memberSelect.value = '';
                        if (selectedBadge) selectedBadge.style.display = 'none';
                        updateLoanLimits();
                        renderDropdown(memberData, '');
                        return;
                    }
                    const filtered = memberData.filter(m => {
                        return m.name.toLowerCase().includes(q) || m.code.toLowerCase().includes(q) || m.dept.toLowerCase().includes(q) || m.rawText.includes(q);
                    });
                    renderDropdown(filtered, q);
                });

                searchInput.addEventListener('focus', function() {
                    const q = this.value.trim().toLowerCase();
                    const filtered = q ? memberData.filter(m => m.name.toLowerCase().includes(q) || m.code.toLowerCase().includes(q) || m.rawText.includes(q)) : memberData;
                    renderDropdown(filtered, q);
                });

                searchInput.addEventListener('keydown', function(e) {
                    const rows = dropdownList.querySelectorAll('.loan-mem-item');
                    if (dropdownList.style.display === 'none' || rows.length === 0) return;

                    if (e.key === 'ArrowDown') {
                        e.preventDefault();
                        let next = activeIndex + 1;
                        if (next >= rows.length) next = 0;
                        setActiveItem(next);
                    } else if (e.key === 'ArrowUp') {
                        e.preventDefault();
                        let prev = activeIndex - 1;
                        if (prev < 0) prev = rows.length - 1;
                        setActiveItem(prev);
                    } else if (e.key === 'Enter') {
                        e.preventDefault();
                        if (activeIndex >= 0 && activeIndex < rows.length) {
                            rows[activeIndex].click();
                        } else if (rows.length > 0) {
                            // Otomatis pilih hasil pertama saat Enter ditekan
                            rows[0].click();
                        }
                    } else if (e.key === 'Escape') {
                        dropdownList.style.display = 'none';
                    }
                });

                // Tutup dropdown saat klik di luar area
                document.addEventListener('click', function(e) {
                    if (!searchInput.contains(e.target) && !dropdownList.contains(e.target)) {
                        dropdownList.style.display = 'none';
                    }
                });

                // Validasi saat form di-submit
                const parentForm = memberSelect.closest('form');
                if (parentForm) {
                    parentForm.addEventListener('submit', function(e) {
                        if (!memberSelect.value) {
                            e.preventDefault();
                            alert('Silakan pilih salah satu siswa/anggota perpustakaan dari daftar pencarian.');
                            searchInput.focus();
                            searchInput.style.borderColor = 'var(--red)';
                        }
                    });
                }
            }

            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', initMemberSearchAutocomplete);
            } else {
                initMemberSearchAutocomplete();
            }
        })();

        // =====================================================================
        // LOGIKA PINJAM KILAT & PENGEMBALIAN KILAT (SCANNER GUN HID BARCODE/QR)
        // AUTO-SUBMIT OTOMATIS TANPA HARUS TEKAN ENTER
        // =====================================================================
        let qlCurrentMember = null;
        let qlChanged = false;
        let qrChanged = false;
        let qlSessionCount = 0;
        let qrSessionCount = 0;

        let qlMemberTimer = null;
        let qlMemberBusy = false;
        let qlBookTimer = null;
        let qlBookBusy = false;
        let qrBookTimer = null;
        let qrBookBusy = false;

        function playQuickTone(type) {
            try {
                const ctx = new (window.AudioContext || window.webkitAudioContext)();
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                if (type === 'success') {
                    osc.type = 'triangle';
                    osc.frequency.setValueAtTime(587.33, ctx.currentTime);
                    osc.frequency.setValueAtTime(880, ctx.currentTime + 0.08);
                    gain.gain.setValueAtTime(0.25, ctx.currentTime);
                    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.28);
                    osc.start(ctx.currentTime);
                    osc.stop(ctx.currentTime + 0.28);
                } else {
                    osc.type = 'sawtooth';
                    osc.frequency.setValueAtTime(240, ctx.currentTime);
                    osc.frequency.setValueAtTime(160, ctx.currentTime + 0.12);
                    gain.gain.setValueAtTime(0.3, ctx.currentTime);
                    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.35);
                    osc.start(ctx.currentTime);
                    osc.stop(ctx.currentTime + 0.35);
                }
            } catch (e) {}
        }

        function openQuickLoanModal() {
            const m = document.getElementById('modalQuickLoan');
            if (m) {
                m.style.display = 'flex';
                resetQuickLoanMember();
                setTimeout(() => {
                    const inp = document.getElementById('qlMemberInput');
                    if (inp) inp.focus();
                }, 150);
            }
        }

        function closeQuickLoanModal() {
            const m = document.getElementById('modalQuickLoan');
            if (m) m.style.display = 'none';
            if (qlChanged) {
                location.reload();
            }
        }

        function resetQuickLoanMember(keepSuccessMsg = false) {
            clearTimeout(qlMemberTimer);
            clearTimeout(qlBookTimer);
            qlMemberBusy = false;
            qlBookBusy = false;
            qlCurrentMember = null;

            const mInp = document.getElementById('qlMemberInput');
            const mFb = document.getElementById('qlMemberFeedback');
            const mDet = document.getElementById('qlMemberDetail');
            const mBtn = document.getElementById('qlBtnResetMember');
            const mBdg = document.getElementById('qlMemberBadge');
            const bStep = document.getElementById('qlStepBook');
            const bInp = document.getElementById('qlBookInput');
            const bBdg = document.getElementById('qlBookBadge');
            const bFb = document.getElementById('qlBookFeedback');

            if (mInp) {
                mInp.value = '';
                mInp.disabled = false;
                setTimeout(() => mInp.focus(), 60);
            }
            if (!keepSuccessMsg && mFb) mFb.style.display = 'none';
            if (mDet) mDet.style.display = 'none';
            if (mBtn) mBtn.style.display = 'none';
            if (mBdg) {
                mBdg.textContent = keepSuccessMsg ? 'Siap Scan Siswa Baru' : 'Menunggu Scan';
                mBdg.style.background = keepSuccessMsg ? '#dcfce7' : '#e2e8f0';
                mBdg.style.color = keepSuccessMsg ? '#15803d' : '#64748b';
            }
            if (bStep) {
                bStep.style.opacity = '0.5';
                bStep.style.pointerEvents = 'none';
            }
            if (bInp) {
                bInp.value = '';
                bInp.disabled = true;
            }
            if (bBdg) {
                bBdg.textContent = 'Terkunci';
                bBdg.style.background = '#e2e8f0';
                bBdg.style.color = '#64748b';
            }
            if (bFb) bFb.style.display = 'none';
        }

        function submitQuickScanMember(val) {
            clearTimeout(qlMemberTimer);
            val = (val || '').trim();
            if (!val || qlMemberBusy) return;
            qlMemberBusy = true;

            const mFb = document.getElementById('qlMemberFeedback');
            const mInp = document.getElementById('qlMemberInput');
            if (mFb) {
                mFb.style.display = 'block';
                mFb.innerHTML = '<span style="color:#0284c7;">🔍 Membaca barcode &amp; mencari data anggota...</span>';
            }

            const fd = new FormData();
            fd.append('code', val);

            fetch('index.php?page=api_quick_scan_member', {
                method: 'POST',
                body: fd
            })
            .then(r => r.json())
            .then(res => {
                if (res.success && res.member) {
                    playQuickTone('success');
                    qlCurrentMember = res.member;
                    if (mInp) mInp.disabled = true;
                    if (mFb) mFb.style.display = 'none';

                    const mBtn = document.getElementById('qlBtnResetMember');
                    const mBdg = document.getElementById('qlMemberBadge');
                    const mDet = document.getElementById('qlMemberDetail');
                    const mName = document.getElementById('qlMemberName');
                    const mMeta = document.getElementById('qlMemberMeta');
                    const mType = document.getElementById('qlMemberType');
                    const mStats = document.getElementById('qlMemberBorrowStats');
                    const mAv = document.getElementById('qlMemberAvatar');

                    if (mBtn) mBtn.style.display = 'inline-block';
                    if (mBdg) {
                        mBdg.textContent = '✓ Siswa Terpilih';
                        mBdg.style.background = '#dcfce7';
                        mBdg.style.color = '#15803d';
                    }
                    if (mName) mName.textContent = res.member.name;
                    if (mMeta) mMeta.textContent = 'NIS/Kode: ' + res.member.member_code + (res.member.department ? ' • ' + res.member.department : '');
                    if (mType) {
                        mType.textContent = res.member.is_teacher ? 'Guru / Pegawai' : 'Siswa';
                        mType.className = 'badge ' + (res.member.is_teacher ? 'badge-amber' : 'badge-blue');
                    }
                    if (mStats) mStats.textContent = 'Pinjam Aktif: ' + res.member.active_loans + ' / ' + res.member.max_loans;
                    if (mAv) {
                        mAv.textContent = (res.member.name || 'A').substring(0, 2).toUpperCase();
                    }
                    if (mDet) mDet.style.display = 'block';

                    // Aktifkan Step 2: Scan Seri Buku
                    const bStep = document.getElementById('qlStepBook');
                    const bInp = document.getElementById('qlBookInput');
                    const bBdg = document.getElementById('qlBookBadge');
                    if (bStep) {
                        bStep.style.opacity = '1';
                        bStep.style.pointerEvents = 'auto';
                    }
                    if (bInp) {
                        bInp.disabled = false;
                        bInp.value = '';
                        setTimeout(() => bInp.focus(), 60);
                    }
                    if (bBdg) {
                        bBdg.textContent = 'Siap Scan Buku';
                        bBdg.style.background = '#dbeafe';
                        bBdg.style.color = '#1d4ed8';
                    }
                } else {
                    playQuickTone('error');
                    if (mFb) {
                        mFb.style.display = 'block';
                        mFb.innerHTML = '<span style="color:var(--red);font-weight:700;">❌ ' + (res.message || 'Anggota tidak ditemukan') + '</span>';
                    }
                    if (mInp) {
                        mInp.select();
                    }
                }
            })
            .catch(err => {
                playQuickTone('error');
                if (mFb) {
                    mFb.style.display = 'block';
                    mFb.innerHTML = '<span style="color:var(--red);font-weight:700;">❌ Terjadi kesalahan jaringan. Coba lagi.</span>';
                }
            })
            .finally(() => {
                setTimeout(() => { qlMemberBusy = false; }, 80);
            });
        }

        function submitQuickScanLoan(val) {
            clearTimeout(qlBookTimer);
            val = (val || '').trim();
            if (!val || qlBookBusy) return;
            if (!qlCurrentMember) {
                alert('Pilih siswa terlebih dahulu!');
                resetQuickLoanMember();
                return;
            }
            qlBookBusy = true;

            const bFb = document.getElementById('qlBookFeedback');
            const bInp = document.getElementById('qlBookInput');
            if (bFb) {
                bFb.style.display = 'block';
                bFb.innerHTML = '<span style="color:#059669;">⏳ Membaca barcode &amp; memproses peminjaman buku...</span>';
            }

            const fd = new FormData();
            fd.append('csrf', '<?=csrf()?>');
            fd.append('member_id', qlCurrentMember.id);
            fd.append('book_barcode', val);

            fetch('index.php?page=api_quick_scan_loan', {
                method: 'POST',
                body: fd
            })
            .then(r => r.json())
            .then(res => {
                if (res.success) {
                    playQuickTone('success');
                    qlChanged = true;
                    qlSessionCount++;

                    // Simpan data peminjam & buku untuk riwayat dan feedback
                    const memberName = (qlCurrentMember ? qlCurrentMember.name : '');
                    const memberNis = (qlCurrentMember ? (qlCurrentMember.member_code || qlCurrentMember.username) : '');
                    const bookTitle = (res.book && res.book.title) || (res.loan && res.loan.book_title) || '';
                    const serialNum = res.serial_number || (res.loan && res.loan.copy_serial) || '';
                    const dueDate = (res.loan && res.loan.due_date) || '-';

                    // Tambahkan ke riwayat sesi peminjaman
                    const list = document.getElementById('qlSessionList');
                    const cnt = document.getElementById('qlSessionCount');
                    if (cnt) cnt.textContent = qlSessionCount + ' buku dipinjam';
                    if (list) {
                        if (qlSessionCount === 1) list.innerHTML = '';
                        const now = new Date().toLocaleTimeString('id-ID', {hour:'2-digit', minute:'2-digit', second:'2-digit'});
                        const row = document.createElement('div');
                        row.style.cssText = 'background:#ffffff;border:1px solid #bbf7d0;border-left:4px solid #16a34a;border-radius:6px;padding:8px 10px;display:flex;align-items:center;justify-content:space-between;gap:8px;';
                        row.innerHTML = '<div><b style="color:var(--navy);">' + bookTitle + '</b> <span style="color:#059669;font-weight:700;font-size:11px;">[' + (serialNum || '-') + ']</span><div style="font-size:11px;color:var(--text-muted);">' + memberName + ' (' + memberNis + ') • Jatuh Tempo: ' + dueDate + '</div></div><span style="font-size:10.5px;color:#64748b;font-weight:700;">' + now + '</span>';
                        list.prepend(row);
                    }

                    // Tampilkan notifikasi berhasil di Step 1
                    const mFb = document.getElementById('qlMemberFeedback');
                    if (mFb) {
                        mFb.style.display = 'block';
                        mFb.innerHTML = '<span style="color:#16a34a;font-weight:700;">✅ BERHASIL PINJAM: ' + bookTitle + ' (' + (serialNum || '-') + ') untuk ' + memberName + '. Silakan scan kartu siswa berikutnya...</span>';
                    }

                    // Langsung kosongkan/reset nama siswa agar kursor auto-fokus kembali ke scan NISN siswa berikutnya!
                    resetQuickLoanMember(true);
                } else {
                    playQuickTone('error');
                    if (bFb) {
                        bFb.style.display = 'block';
                        bFb.innerHTML = '<span style="color:var(--red);font-weight:700;">❌ ' + (res.message || 'Gagal meminjam buku') + '</span>';
                    }
                    if (bInp) {
                        bInp.select();
                    }
                }
            })
            .catch(err => {
                playQuickTone('error');
                if (bFb) {
                    bFb.style.display = 'block';
                    bFb.innerHTML = '<span style="color:var(--red);font-weight:700;">❌ Terjadi kesalahan server. Coba lagi.</span>';
                }
            })
            .finally(() => {
                setTimeout(() => { qlBookBusy = false; }, 80);
            });
        }

        // =====================================================================
        // PENGEMBALIAN KILAT (SCANNER GUN)
        // =====================================================================
        function openQuickReturnModal() {
