        function closeQuickReturnModal() {
            const m = document.getElementById('modalQuickReturn');
            if (m) m.style.display = 'none';
            if (qrChanged) {
                location.reload();
            }
        }

        function submitQuickScanReturn(val) {
            clearTimeout(qrBookTimer);
            val = (val || '').trim();
            if (!val || qrBookBusy) return;
            qrBookBusy = true;

            const fb = document.getElementById('qrFeedback');
            const inp = document.getElementById('qrBookInput');
            if (fb) {
                fb.style.display = 'block';
                fb.innerHTML = '<span style="color:#d97706;">⏳ Membaca barcode &amp; memproses pengembalian buku...</span>';
            }

            const fd = new FormData();
            fd.append('csrf', '<?=csrf()?>');
            fd.append('book_barcode', val);

            fetch('index.php?page=api_quick_scan_return', {
                method: 'POST',
                body: fd
            })
            .then(r => r.json())
            .then(res => {
                if (res.success) {
                    playQuickTone('success');
                    qrChanged = true;
                    qrSessionCount++;

                    let fineText = '';
                    if (res.return && res.return.is_overdue) {
                        fineText = ' <span style="color:var(--red);font-weight:700;">(Terlambat ' + res.return.overdue_days + ' hari)</span>';
                    } else {
                        fineText = ' <span style="color:#16a34a;font-weight:700;">(Tepat Waktu)</span>';
                    }

                    const retTitle = (res.book && res.book.title) || (res.return && res.return.book_title) || '';
                    const retSerial = res.serial_number || (res.return && res.return.copy_serial) || '';
                    const retMember = (res.member && res.member.name) || (res.return && res.return.member_name) || '';
                    const retNis = (res.member && res.member.member_code) || (res.return && res.return.member_nis) || '';

                    if (fb) {
                        fb.style.display = 'block';
                        fb.innerHTML = '<span style="color:#16a34a;font-weight:700;">✅ BERHASIL DIKEMBALIKAN: ' + retTitle + ' (' + retSerial + ')' + fineText + '</span>';
                    }

                    // Tambahkan ke riwayat sesi pengembalian
                    const list = document.getElementById('qrSessionList');
                    const cnt = document.getElementById('qrSessionCount');
                    if (cnt) cnt.textContent = qrSessionCount + ' buku dikembalikan';
                    if (list) {
                        if (qrSessionCount === 1) list.innerHTML = '';
                        const now = new Date().toLocaleTimeString('id-ID', {hour:'2-digit', minute:'2-digit', second:'2-digit'});
                        const row = document.createElement('div');
                        row.style.cssText = 'background:#ffffff;border:1px solid #fde68a;border-left:4px solid #d97706;border-radius:6px;padding:8px 10px;display:flex;align-items:center;justify-content:space-between;gap:8px;';
                        row.innerHTML = '<div><b style="color:var(--navy);">' + retTitle + '</b> <span style="color:#d97706;font-weight:700;font-size:11px;">[' + (retSerial || '-') + ']</span><div style="font-size:11px;color:var(--text-muted);">' + retMember + ' (' + retNis + ')' + fineText + '</div></div><span style="font-size:10.5px;color:#64748b;font-weight:700;">' + now + '</span>';
                        list.prepend(row);
                    }

                    // Reset input buku & fokus kembali untuk pengembalian buku berikutnya!
                    if (inp) {
                        inp.value = '';
                        setTimeout(() => inp.focus(), 60);
                    }
                } else {
                    playQuickTone('error');
                    if (fb) {
                        fb.style.display = 'block';
                        fb.innerHTML = '<span style="color:var(--red);font-weight:700;">❌ ' + (res.message || 'Gagal memproses pengembalian') + '</span>';
                    }
                    if (inp) {
                        inp.value = '';
                        setTimeout(() => inp.focus(), 60);
                    }
                }
            })
            .catch(err => {
                playQuickTone('error');
                if (fb) {
                    fb.style.display = 'block';
                    fb.innerHTML = '<span style="color:var(--red);font-weight:700;">❌ Terjadi kesalahan server. Coba lagi.</span>';
                }
                if (inp) {
                    inp.value = '';
                    setTimeout(() => inp.focus(), 60);
                }
            })
            .finally(() => {
                setTimeout(() => { qrBookBusy = false; }, 80);
            });
        }

        // =====================================================================
        // FUNGSI AUTO SCAN REAL-TIME (TANPA HARUS TEKAN ENTER)
        // =====================================================================
        window.handleQlMemberInputAuto = function(val) {
            clearTimeout(qlMemberTimer);
            val = (val || '').trim();
            if (!val) return;
            qlMemberTimer = setTimeout(function() {
                submitQuickScanMember(val);
            }, 85);
        };

        window.handleQlBookInputAuto = function(val) {
            clearTimeout(qlBookTimer);
            val = (val || '').trim();
            if (!val) return;
            qlBookTimer = setTimeout(function() {
                submitQuickScanLoan(val);
            }, 85);
        };

        window.handleQrInputAuto = function(val) {
            clearTimeout(qrBookTimer);
            val = (val || '').trim();
            if (!val) return;
            qrBookTimer = setTimeout(function() {
                submitQuickScanReturn(val);
            }, 85);
        };

        // Event listener cadangan saat ready
        function bindAllQuickScannerEvents() {
            const qlMemberInput = document.getElementById('qlMemberInput');
            if (qlMemberInput && !qlMemberInput._boundAuto) {
                qlMemberInput._boundAuto = true;
                qlMemberInput.addEventListener('input', function() { handleQlMemberInputAuto(this.value); });
                qlMemberInput.addEventListener('change', function() { submitQuickScanMember(this.value); });
            }

            const qlBookInput = document.getElementById('qlBookInput');
            if (qlBookInput && !qlBookInput._boundAuto) {
                qlBookInput._boundAuto = true;
                qlBookInput.addEventListener('input', function() { handleQlBookInputAuto(this.value); });
                qlBookInput.addEventListener('change', function() { submitQuickScanLoan(this.value); });
            }

            const qrBookInput = document.getElementById('qrBookInput');
            if (qrBookInput && !qrBookInput._boundAuto) {
                qrBookInput._boundAuto = true;
                qrBookInput.addEventListener('input', function() { handleQrInputAuto(this.value); });
                qrBookInput.addEventListener('change', function() { submitQuickScanReturn(this.value); });
            }
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', bindAllQuickScannerEvents);
        } else {
            bindAllQuickScannerEvents();
        }

        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') {
                closeNewLoanModal();
                closeApproveScanModal();
                closeQuickLoanModal();
                closeQuickReturnModal();
            }
        });
        </script>
        <?php
    });
    exit;
}

