    $isValidCalendarDate = function($dateStr) {
        if (!is_string($dateStr) || !preg_match('/^(\d{4})-(\d{2})-(\d{2})$/', $dateStr, $m)) {
            return false;
        }
        return checkdate((int)$m[2], (int)$m[3], (int)$m[1]);
    };

