        const currentReportTab = '<?=e($tab)?>';
        let activeCols = [];

        function renderActiveColumns(cols, activePresetName) {
            const config = reportTabConfigs[currentReportTab];
            if (!config) return;
            activeCols = cols;

            // Sembunyikan atau tampilkan kolom
            config.all.forEach(colKey => {
                const isVisible = cols.includes(colKey);
                const cells = document.querySelectorAll(`[data-col="${colKey}"]`);
                cells.forEach(el => {
                    if (isVisible) {
                        el.classList.remove('col-hidden');
                    } else {
                        el.classList.add('col-hidden');
                    }
                });
            });

            // Pada tab books, sesuaikan colspan baris total
            if (currentReportTab === 'books') {
                const labelCell = document.getElementById('book_tfoot_label');
                if (labelCell) {
                    const preCols = ['no', 'tanggal_penerimaan', 'kode', 'nomor_seri', 'judul', 'kategori', 'sumber', 'harga', 'penulis_penerbit'];
                    const visiblePreCount = preCols.filter(c => cols.includes(c)).length;
                    labelCell.colSpan = Math.max(1, visiblePreCount);
                }
            }
            if (currentReportTab === 'buku_digital') {
                const labelCell = document.getElementById('buku_digital_tfoot_label');
                if (labelCell) {
                    const preCols = ['no', 'judul', 'penulis', 'penerbit', 'kategori', 'file_type'];
                    const visiblePreCount = preCols.filter(c => cols.includes(c)).length;
                    labelCell.colSpan = Math.max(1, visiblePreCount);
                }
            }
            if (currentReportTab === 'karya') {
                const labelCell = document.getElementById('karya_tfoot_label');
                if (labelCell) {
                    const preCols = ['no', 'judul', 'pembuat_tipe', 'nama_pembuat', 'kelas_jurusan', 'tahun', 'kategori', 'media_type'];
                    const visiblePreCount = preCols.filter(c => cols.includes(c)).length;
                    labelCell.colSpan = Math.max(1, visiblePreCount);
                }
            }

            // Update badge jumlah kolom
            const badge = document.getElementById('activeColsCountBadge');
            if (badge) {
                badge.innerText = `${cols.length}/${config.all.length}`;
                if (cols.length < config.all.length) {
                    badge.className = 'badge badge-green';
                } else {
                    badge.className = 'badge badge-blue';
                }
            }

            // Update label banner
            const modeLabel = document.getElementById('reportPrintModeLabel');
            if (modeLabel) {
                if (cols.length === config.all.length) {
                    modeLabel.innerText = `Lengkap (${cols.length} Kolom)`;
                } else if (cols.length <= 6) {
                    modeLabel.innerText = `Hemat Kertas (${cols.length} Kolom) - Pas di A4 Tegak`;
                } else {
                    modeLabel.innerText = `Kustom (${cols.length} dari ${config.all.length} Kolom)`;
                }
            }

            // Update preset chips highlight
            document.querySelectorAll('.btn-preset-chip').forEach(btn => btn.classList.remove('active'));
            if (activePresetName) {
                const chip = document.getElementById(`chip_${activePresetName}`);
                if (chip) chip.classList.add('active');
            }

            // Update link Export Excel dengan parameter kolom
            const btnExcel = document.getElementById('btnExportExcel');
            if (btnExcel) {
                let baseHref = btnExcel.getAttribute('href');
                baseHref = baseHref.replace(/&cols=[^&]*/, '');
                if (cols.length < config.all.length) {
                    baseHref += '&cols=' + cols.join(',');
                }
                btnExcel.setAttribute('href', baseHref);
            }
        }

        function setPrintOrientation(orient) {
            let styleEl = document.getElementById('print-orientation-style');
            if (!styleEl) {
                styleEl = document.createElement('style');
                styleEl.id = 'print-orientation-style';
                document.head.appendChild(styleEl);
            }
            const orientLabel = document.getElementById('reportOrientLabel');
            if (orient === 'landscape') {
                styleEl.innerHTML = '@media print { @page { size: A4 landscape !important; margin: 8mm 10mm; } }';
                if (orientLabel) orientLabel.innerText = 'A4 Landscape (Melebar)';
            } else {
                styleEl.innerHTML = '@media print { @page { size: A4 portrait !important; margin: 8mm 10mm; } }';
                if (orientLabel) orientLabel.innerText = 'A4 Portrait (Tegak - Hemat Kertas)';
            }
            localStorage.setItem('report_orient_' + currentReportTab, orient);
        }

        function applyPreset(presetName) {
            const config = reportTabConfigs[currentReportTab];
            if (!config || !config.presets[presetName]) return;
            const chosen = config.presets[presetName];

            // Otomatis atur orientasi: jika <= 7 kolom gunakan portrait (hemat kertas), jika lebih banyak gunakan landscape
            if (presetName === 'compact') {
                setPrintOrientation('portrait');
            } else if (presetName === 'all' && config.all.length > 8) {
                setPrintOrientation('landscape');
            }

            renderActiveColumns(chosen, presetName);
            localStorage.setItem('report_cols_' + currentReportTab, JSON.stringify(chosen));
            localStorage.setItem('report_preset_' + currentReportTab, presetName);
        }

        function triggerReportPrint() {
            window.print();
        }

        // MODAL LOGIC
        function openReportColModal() {
            const config = reportTabConfigs[currentReportTab];
            if (!config) return;

            if (!activeCols || activeCols.length === 0) {
                const raw = localStorage.getItem('report_cols_' + currentReportTab);
                if (raw) {
                    try { activeCols = JSON.parse(raw); } catch(e) {}
                }
                if (!activeCols || activeCols.length === 0) {
                    activeCols = [...config.all];
                }
            }

            const grid = document.getElementById('modalColGrid');
            grid.innerHTML = '';

            config.all.forEach(key => {
                const item = config.labels[key] || { name: key, desc: '' };
                const isChecked = activeCols.includes(key);
                const isNo = key === 'no';

                const card = document.createElement('label');
                card.className = 'col-card-item' + (isChecked ? ' selected' : '');
                card.innerHTML = `
                    <input type="checkbox" name="report_col_chk" value="${key}" ${isChecked ? 'checked' : ''} ${isNo ? 'disabled' : ''} onchange="onColCheckboxChange(this)">
                    <div class="col-card-info">
                        <span class="col-card-title">${item.name}</span>
                        <span class="col-card-desc">${item.desc}</span>
                    </div>
                `;
                grid.appendChild(card);
            });

            // Set orientasi di modal radio
            const currentOrient = localStorage.getItem('report_orient_' + currentReportTab) || 'portrait';
            const rad = document.querySelector(`input[name="modal_orient"][value="${currentOrient}"]`);
            if (rad) rad.checked = true;

            document.getElementById('reportColModalBackdrop').classList.add('active');
        }

        function closeReportColModal() {
            document.getElementById('reportColModalBackdrop').classList.remove('active');
        }

        function onColCheckboxChange(chk) {
            const card = chk.closest('.col-card-item');
            if (card) {
                if (chk.checked) card.classList.add('selected');
                else card.classList.remove('selected');
            }
        }

        function modalCheckAll(val) {
            document.querySelectorAll('#modalColGrid input[type="checkbox"]').forEach(chk => {
                if (chk.value === 'no') return; // selalu aktif
                chk.checked = val;
                onColCheckboxChange(chk);
            });
        }

        function modalSetPreset(presetName) {
            const config = reportTabConfigs[currentReportTab];
            if (!config || !config.presets[presetName]) return;
            const targetCols = config.presets[presetName];

            document.querySelectorAll('#modalColGrid input[type="checkbox"]').forEach(chk => {
                chk.checked = targetCols.includes(chk.value);
                onColCheckboxChange(chk);
            });

            if (presetName === 'compact') {
                modalChangeOrient('portrait');
                const rad = document.querySelector('input[name="modal_orient"][value="portrait"]');
                if (rad) rad.checked = true;
            } else if (presetName === 'all' && config.all.length > 8) {
                modalChangeOrient('landscape');
                const rad = document.querySelector('input[name="modal_orient"][value="landscape"]');
                if (rad) rad.checked = true;
            }
        }

        function modalChangeOrient(orient) {
            setPrintOrientation(orient);
        }

        function modalToggleMetrics(show) {
            if (show) {
                document.body.classList.remove('print-hide-metrics');
            } else {
                document.body.classList.add('print-hide-metrics');
            }
            localStorage.setItem('report_opt_metrics', show ? '1' : '0');
        }

        function modalToggleSignature(show) {
            if (show) {
                document.body.classList.remove('print-hide-signature');
            } else {
                document.body.classList.add('print-hide-signature');
            }
            localStorage.setItem('report_opt_signature', show ? '1' : '0');
        }

        function modalToggleCompactFont(compact) {
            const tbl = document.getElementById('reportTableMain');
            if (tbl) {
                if (compact) tbl.classList.add('print-compact');
                else tbl.classList.remove('print-compact');
            }
            localStorage.setItem('report_opt_compact_font', compact ? '1' : '0');
        }

        function saveAndApplyModalCols() {
            const config = reportTabConfigs[currentReportTab];
            if (!config) return;

            const selected = ['no'];
            document.querySelectorAll('#modalColGrid input[type="checkbox"]:checked').forEach(chk => {
                if (!selected.includes(chk.value)) selected.push(chk.value);
            });

            // Identifikasi apakah cocok dengan preset tertentu
            let matchedPreset = null;
            for (const [pName, pCols] of Object.entries(config.presets)) {
                if (pCols.length === selected.length && pCols.every(c => selected.includes(c))) {
                    matchedPreset = pName;
                    break;
                }
            }

            renderActiveColumns(selected, matchedPreset);
            localStorage.setItem('report_cols_' + currentReportTab, JSON.stringify(selected));
            if (matchedPreset) {
                localStorage.setItem('report_preset_' + currentReportTab, matchedPreset);
            } else {
                localStorage.removeItem('report_preset_' + currentReportTab);
            }

            closeReportColModal();
        }

        function modalResetDefault() {
            modalSetPreset('all');
            modalChangeOrient(reportTabConfigs[currentReportTab].all.length > 8 ? 'landscape' : 'portrait');
            document.getElementById('modal_opt_metrics').checked = true;
            modalToggleMetrics(true);
            document.getElementById('modal_opt_signature').checked = true;
            modalToggleSignature(true);
            document.getElementById('modal_opt_compact_font').checked = false;
            modalToggleCompactFont(false);
        }

        // LOAD PREFERENCES ON START
        document.addEventListener('DOMContentLoaded', function() {
            const config = reportTabConfigs[currentReportTab];
            if (!config) return;

            // Load saved orientation
            const savedOrient = localStorage.getItem('report_orient_' + currentReportTab) || (config.all.length > 8 ? 'landscape' : 'portrait');
            setPrintOrientation(savedOrient);

            // Load options
            const optMetrics = localStorage.getItem('report_opt_metrics');
            if (optMetrics === '0') {
                document.body.classList.add('print-hide-metrics');
                const chk = document.getElementById('modal_opt_metrics');
                if (chk) chk.checked = false;
            }
            const optSig = localStorage.getItem('report_opt_signature');
            if (optSig === '0') {
                document.body.classList.add('print-hide-signature');
                const chk = document.getElementById('modal_opt_signature');
                if (chk) chk.checked = false;
            }
            const optFont = localStorage.getItem('report_opt_compact_font');
            if (optFont === '1') {
                const tbl = document.getElementById('reportTableMain');
                if (tbl) tbl.classList.add('print-compact');
                const chk = document.getElementById('modal_opt_compact_font');
                if (chk) chk.checked = true;
            }

            // Load saved columns
            const raw = localStorage.getItem('report_cols_' + currentReportTab);
            const savedPreset = localStorage.getItem('report_preset_' + currentReportTab);

            if (raw) {
                try {
                    const parsed = JSON.parse(raw);
                    if (Array.isArray(parsed) && parsed.length > 0) {
                        const valid = parsed.filter(c => config.all.includes(c));
                        if (valid.length > 0) {
                            renderActiveColumns(valid, savedPreset);
                            return;
                        }
                    }
                } catch(e) {}
            }

            // Default
            renderActiveColumns(config.all, 'all');
        });
        </script>
        <?php
    });
    exit;
}

