// 12B. PAGE: ADMIN LAYANAN BEBAS PUSTAKA (LIBRARY CLEARANCE)
// ==========================================================================
if ($page === 'admin_clearance') {
    auth('admin');

    // Handle POST Actions (Issue or Revoke Clearance)
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $action = $_POST['action'] ?? '';

        if ($action === 'issue_clearance') {
            $memberId = (int)($_POST['member_id'] ?? 0);
            $purpose = trim($_POST['purpose'] ?? 'Pengambilan Ijazah / Kelulusan');
            if ($purpose === '') $purpose = 'Pengambilan Ijazah / Kelulusan';
            $notes = trim($_POST['notes'] ?? '');

            // Verify member
            $mStmt = $pdo->prepare("SELECT * FROM users WHERE id = ? AND role = 'member' LIMIT 1");
            $mStmt->execute([$memberId]);
            $mem = $mStmt->fetch();

            if (!$mem) {
                flash('Anggota tidak ditemukan.', 'error');
                header('Location: ' . u('index.php?page=admin_clearance'));
                exit;
            }

            // Check active borrowed books and pending loans
            $chkActive = $pdo->prepare("SELECT COUNT(*) FROM loans WHERE member_id = ? AND status = 'borrowed'");
            $chkActive->execute([$memberId]);
            $activeCount = (int)$chkActive->fetchColumn();

            $chkPending = $pdo->prepare("SELECT COUNT(*) FROM loans WHERE member_id = ? AND status = 'pending'");
            $chkPending->execute([$memberId]);
            $pendingCount = (int)$chkPending->fetchColumn();

            if ($activeCount > 0 || $pendingCount > 0) {
                flash('Anggota "' . e($mem['name']) . '" belum dapat diterbitkan Bebas Pustaka karena masih memiliki ' . ($activeCount + $pendingCount) . ' peminjaman/pengajuan buku yang aktif.', 'error');
                header('Location: ' . u('index.php?page=admin_clearance&q=' . urlencode($mem['name'])));
                exit;
            }

            // Generate unique official certificate number
            $nextId = ((int)$pdo->query("SELECT MAX(id) FROM clearances")->fetchColumn()) + 1;
            $certNo = generate_clearance_number($nextId);

            $insStmt = $pdo->prepare("INSERT INTO clearances (certificate_no, member_id, issued_by, purpose, notes) VALUES (?, ?, ?, ?, ?)");
            $insStmt->execute([$certNo, $memberId, (int)($currentUser['id'] ?? 0), $purpose, $notes]);

            flash('Surat Bebas Pustaka resmi No. ' . $certNo . ' untuk ' . e($mem['name']) . ' berhasil diterbitkan!');
            header('Location: ' . u('index.php?page=print_clearance&id=' . $memberId));
            exit;
        }

        if ($action === 'quick_clear_and_issue' || $action === 'return_all_and_issue') {
            $memberId = (int)($_POST['member_id'] ?? 0);
            $purpose = trim($_POST['purpose'] ?? 'Pengambilan Ijazah / Kelulusan');
            if ($purpose === '') $purpose = 'Pengambilan Ijazah / Kelulusan';
            $targetFormat = trim($_POST['format'] ?? 'cert');

            $mStmt = $pdo->prepare("SELECT * FROM users WHERE id = ? AND role = 'member' LIMIT 1");
            $mStmt->execute([$memberId]);
            $mem = $mStmt->fetch();

            if (!$mem) {
                flash('Anggota tidak ditemukan.', 'error');
                header('Location: ' . u('index.php?page=admin_clearance'));
                exit;
            }

            try {
                if (!$pdo->inTransaction()) {
                    $pdo->beginTransaction();
                }

                // 1. Kunci baris anggota terlebih dahulu
                $mLock = $pdo->prepare("SELECT id, name FROM users WHERE id = ? AND role = 'member' FOR UPDATE");
                $mLock->execute([$memberId]);

                // 2. Kunci dan ambil seluruh pinjaman yang masih aktif (borrowed) atau pending
                $activeLoans = $pdo->prepare("SELECT id, book_id, quantity, status, copy_serial FROM loans WHERE member_id = ? AND status IN ('borrowed', 'pending') FOR UPDATE");
                $activeLoans->execute([$memberId]);
                $loansToClear = $activeLoans->fetchAll();

                $returnedBooksCount = 0;
                $updLoanBorrowed = $pdo->prepare("UPDATE loans SET status = 'returned', return_date = CURDATE(), notes = CONCAT(COALESCE(notes, ''), ' [Pelunasan Bebas Pustaka]') WHERE id = ? AND status = 'borrowed'");
                $updLoanPending = $pdo->prepare("UPDATE loans SET status = 'rejected', notes = CONCAT(COALESCE(notes, ''), ' [Dibatalkan Bebas Pustaka]') WHERE id = ? AND status = 'pending'");
                $updBookStmt = $pdo->prepare("UPDATE books SET available = LEAST(quantity, available + ?) WHERE id = ?");
                $updCopyStmt = $pdo->prepare("UPDATE book_copies SET status = 'available' WHERE book_id = ? AND copy_code = ?");

                foreach ($loansToClear as $ln) {
                    $lId = (int)$ln['id'];
                    $bId = (int)$ln['book_id'];
                    $qty = max(1, (int)$ln['quantity']);
                    $curStat = $ln['status'];

                    if ($curStat === 'borrowed') {
                        // Kunci baris buku untuk mencegah race condition pada update stok
                        $bLock = $pdo->prepare("SELECT id, available, quantity FROM books WHERE id = ? FOR UPDATE");
                        $bLock->execute([$bId]);

                        // Update status peminjaman dengan syarat status masih 'borrowed' (mencegah pemulihan stok ganda)
                        $updLoanBorrowed->execute([$lId]);
                        if ($updLoanBorrowed->rowCount() > 0) {
                            $updBookStmt->execute([$qty, $bId]);
                            $returnedBooksCount += $qty;

                            // Pulihkan juga status book_copies jika tercatat no seri
                            if (!empty($ln['copy_serial'])) {
                                foreach (explode(',', (string)$ln['copy_serial']) as $sCode) {
                                    $sCode = trim($sCode);
                                    if ($sCode !== '') {
                                        $updCopyStmt->execute([$bId, $sCode]);
                                    }
                                }
                            }
                        }
                    } elseif ($curStat === 'pending') {
                        // Status pending BELUM pernah memotong stok, sehingga TIDAK BOLEH memulihkan stok
                        $updLoanPending->execute([$lId]);
                    }
                }

                // 3. Pastikan dokumen sertifikat bebas pustaka resmi diterbitkan
                $chkCert = $pdo->prepare("SELECT id, certificate_no FROM clearances WHERE member_id = ? ORDER BY id DESC LIMIT 1 FOR UPDATE");
                $chkCert->execute([$memberId]);
                $existingCert = $chkCert->fetch();

                if ($existingCert) {
                    $certNo = $existingCert['certificate_no'];
                    flash("Seluruh pinjaman (" . $returnedBooksCount . " buku fisik) untuk " . e($mem['name']) . " telah dilunaskan. Dokumen Bebas Pustaka siap dicetak!");
                } else {
                    $nextId = ((int)$pdo->query("SELECT MAX(id) FROM clearances FOR UPDATE")->fetchColumn()) + 1;
                    $certNo = generate_clearance_number($nextId);

                    $insStmt = $pdo->prepare("INSERT INTO clearances (certificate_no, member_id, issued_by, purpose, notes) VALUES (?, ?, ?, ?, ?)");
                    $insStmt->execute([$certNo, $memberId, (int)($currentUser['id'] ?? 0), $purpose, 'Terbit via Pelunasan Bebas Pustaka']);

                    flash("Seluruh buku tanggungan berhasil dikembalikan dan Surat & Kartu Bebas Pustaka No. " . $certNo . " berhasil diterbitkan!");
                }

                $pdo->commit();
            } catch (Throwable $e) {
                if ($pdo->inTransaction()) {
                    $pdo->rollBack();
                }
                flash('Gagal memproses bebas pustaka: ' . $e->getMessage(), 'error');
                header('Location: ' . u('index.php?page=admin_clearance'));
                exit;
            }

            header('Location: ' . u('index.php?page=print_clearance&id=' . $memberId . '&format=' . $targetFormat));
            exit;
        }

        if ($action === 'delete_clearance') {
            $clearanceId = (int)($_POST['clearance_id'] ?? 0);
            $del = $pdo->prepare("DELETE FROM clearances WHERE id = ?");
            $del->execute([$clearanceId]);
            flash('Histori surat keterangan bebas pustaka telah dihapus.');
            header('Location: ' . u('index.php?page=admin_clearance'));
            exit;
        }
    }

    // KPI Summary
    $cTotalMembers = (int)$pdo->query("SELECT COUNT(*) FROM users WHERE role = 'member'")->fetchColumn();
    $cMembersWithLoans = (int)$pdo->query("SELECT COUNT(DISTINCT member_id) FROM loans WHERE status = 'borrowed'")->fetchColumn();
    $cMembersOverdue = (int)$pdo->query("SELECT COUNT(DISTINCT member_id) FROM loans WHERE status = 'borrowed' AND due_date < CURDATE()")->fetchColumn();
    $cMembersCleared = max(0, $cTotalMembers - $cMembersWithLoans);
    $cCertificates = (int)$pdo->query("SELECT COUNT(*) FROM clearances")->fetchColumn();

    // Filters & Search
    $q = trim($_GET['q'] ?? '');
    $statusFilter = trim($_GET['status'] ?? 'all');
    $deptFilter = trim($_GET['department'] ?? 'all');

    $where = ["u.role = 'member'"];
    $params = [];

    if ($q !== '') {
        $where[] = "(u.name LIKE ? OR u.member_code LIKE ? OR u.username LIKE ? OR u.phone LIKE ? OR u.department LIKE ?)";
        $params[] = "%{$q}%";
        $params[] = "%{$q}%";
        $params[] = "%{$q}%";
        $params[] = "%{$q}%";
        $params[] = "%{$q}%";
    }

    if ($deptFilter !== '' && $deptFilter !== 'all') {
        $where[] = "u.department LIKE ?";
        $params[] = "%{$deptFilter}%";
    }

    $whereSql = implode(" AND ", $where);

    // Fetch members with loan counters, overdue count, and clearance info
    $sql = "SELECT u.*, 
                   (SELECT COUNT(*) FROM loans l WHERE l.member_id = u.id AND l.status = 'borrowed') as borrowed_count,
                   (SELECT COUNT(*) FROM loans l WHERE l.member_id = u.id AND l.status = 'borrowed' AND l.due_date < CURDATE()) as overdue_count,
                   (SELECT COUNT(*) FROM loans l WHERE l.member_id = u.id AND l.status = 'pending') as pending_count,
                   (SELECT COUNT(*) FROM loans l WHERE l.member_id = u.id) as total_loan_count,
                   (SELECT COUNT(*) FROM loans l WHERE l.member_id = u.id AND l.status = 'returned') as returned_count,
                   c.id as clearance_id, c.certificate_no, c.purpose as clearance_purpose, c.created_at as clearance_date
            FROM users u
            LEFT JOIN clearances c ON c.member_id = u.id AND c.id = (SELECT MAX(c2.id) FROM clearances c2 WHERE c2.member_id = u.id)
            WHERE {$whereSql}
            ORDER BY u.name ASC LIMIT 400";

    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);
    $rawMembers = $stmt->fetchAll();

    // In-memory filter for clearance status if requested
    $membersList = [];
    foreach ($rawMembers as $m) {
        $bCount = (int)$m['borrowed_count'];
        $pCount = (int)$m['pending_count'];
        $ovCount = (int)$m['overdue_count'];
        $isClean = ($bCount === 0 && $pCount === 0);
        $hasCert = !empty($m['clearance_id']);

        if ($statusFilter === 'cleared' && !$isClean) continue;
        if ($statusFilter === 'has_loans' && $bCount === 0) continue;
        if ($statusFilter === 'overdue' && $ovCount === 0) continue;
        if ($statusFilter === 'certified' && !$hasCert) continue;

        $membersList[] = $m;
    }

    // Fetch unreturned books for members who have borrowed books (for quick preview)
    $unreturnedMap = [];
    if (!empty($membersList)) {
        $memberIds = array_column($membersList, 'id');
        $inClause = implode(',', array_map('intval', $memberIds));
        if ($inClause !== '') {
            $loansSql = "SELECT l.id as loan_id, l.member_id, l.loan_date, l.due_date, l.quantity, b.title, b.code as book_code 
                         FROM loans l 
                         JOIN books b ON b.id = l.book_id 
                         WHERE l.member_id IN ({$inClause}) AND l.status = 'borrowed'";
            $lStmt = $pdo->query($loansSql);
            while ($row = $lStmt->fetch()) {
                $unreturnedMap[$row['member_id']][] = $row;
            }
        }
    }

