if ($page === 'print_clearance' || $page === 'bebas_pustaka_pdf') {
    auth(); // Admin or Member
    $sessionUser = $_SESSION['user'];
    $isAdmin = ($sessionUser['role'] === 'admin');
    $mid = (int)($_GET['id'] ?? ($isAdmin ? 0 : $sessionUser['id']));
    $format = trim($_GET['format'] ?? 'cert');
    if ($format !== 'card') $format = 'cert';

    if (!$isAdmin && $sessionUser['id'] != $mid) {
        flash('Anda tidak memiliki akses ke dokumen anggota lain.', 'error');
        header('Location: ' . u());
        exit;
    }

    $mStmt = $pdo->prepare("SELECT * FROM users WHERE id = ? AND role = 'member' LIMIT 1");
    $mStmt->execute([$mid]);
    $member = $mStmt->fetch();

    if (!$member) {
        exit('Anggota tidak ditemukan.');
    }

    // Check loan status
    $activeLoansStmt = $pdo->prepare("SELECT l.*, b.title, b.code as book_code 
                                      FROM loans l 
                                      JOIN books b ON b.id = l.book_id 
                                      WHERE l.member_id = ? AND l.status = 'borrowed'");
    $activeLoansStmt->execute([$mid]);
    $borrowedBooks = $activeLoansStmt->fetchAll();

    $pendingLoansCount = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE member_id = {$mid} AND status = 'pending'")->fetchColumn();
    $returnedCount = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE member_id = {$mid} AND status = 'returned'")->fetchColumn();

    $isClean = (empty($borrowedBooks) && $pendingLoansCount === 0);

    // Check existing official clearance certificate
    $cStmt = $pdo->prepare("SELECT * FROM clearances WHERE member_id = ? ORDER BY id DESC LIMIT 1");
    $cStmt->execute([$mid]);
    $cert = $cStmt->fetch();

    // Can print if: already has certificate, or member is clean, or admin requests
    $canPrint = ($cert !== false && $cert !== null) || $isClean || $isAdmin;

    if (!$cert && $canPrint) {
        $nextId = ((int)$pdo->query("SELECT MAX(id) FROM clearances")->fetchColumn()) + 1;
        $certNo = generate_clearance_number($nextId);
        $purpose = 'Pengambilan Ijazah / Kelulusan';
        $ins = $pdo->prepare("INSERT INTO clearances (certificate_no, member_id, issued_by, purpose, notes) VALUES (?, ?, ?, ?, 'Terbit otomatis')");
        $ins->execute([$certNo, $mid, $isAdmin ? $sessionUser['id'] : null, $purpose]);
        $cert = [
            'id' => $nextId,
            'certificate_no' => $certNo,
            'purpose' => $purpose,
            'created_at' => date('Y-m-d H:i:s'),
            'notes' => 'Terbit otomatis'
        ];
    }

    // Config & School Details from Settings
    $headTitle = get_setting('report_head_title', 'Kepala Perpustakaan');
    $headName = get_setting('report_head_name', 'Drs. Suparman, M.Pd');
    $headNip = get_setting('report_head_nip', 'NIP. 19750815 200501 1 004');
    $staffTitle = get_setting('report_staff_title', 'Petugas Administrasi & Sirkulasi');
    $staffName = get_setting('report_staff_name', 'Petugas Perpustakaan');
    $staffNip = get_setting('report_staff_nip', 'NIP/NUPTK. 19890412 201402 2 001');
    $reportCity = get_setting('report_city', 'Banda Aceh');
    $schoolTitle = get_school_name();
    $schoolSub = get_setting('navbar_subtitle', SCHOOL_SUB);
    $schoolLogo = get_setting('navbar_logo', 'assets/img/logo.jpg');
    $schoolAddress = get_setting('info_address', 'Jl. Teuku Nyak Arief No. 123, Banda Aceh');
    $schoolPhone = get_setting('info_phone', '(0651) 123456');
    $schoolEmail = get_setting('info_email', 'perpustakaan@smkn5telkom.sch.id');

    // Barcode and QR
    $certNo = $cert['certificate_no'] ?? generate_clearance_number($mid);
    $barcodeSvg = generate_barcode_svg($certNo, 240, 44);
    $certHash = md5($certNo . $member['name']);

    $protocol = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
    $reqHost = $_SERVER['HTTP_HOST'] ?? 'localhost';
    $lanIp = @gethostbyname(gethostname());
    if (($reqHost === 'localhost' || $reqHost === '127.0.0.1') && !empty($lanIp) && $lanIp !== '127.0.0.1' && $lanIp !== 'localhost') {
        $port = $_SERVER['SERVER_PORT'] ?? '80';
        $hostWithPort = ($port !== '80' && $port !== '443') ? ($lanIp . ':' . $port) : $lanIp;
        $verifyUrl = $protocol . '://' . $hostWithPort . u('index.php?page=verify_clearance&no=' . urlencode($certNo) . '&hash=' . $certHash);
    } else {
        $verifyUrl = $protocol . '://' . $reqHost . u('index.php?page=verify_clearance&no=' . urlencode($certNo) . '&hash=' . $certHash);
    }
    $qrSvg = generate_qr_svg($verifyUrl, 84);
