        <!-- Real Standard ISO QR Code Generator Script (100% Offline) -->
        <script src="<?=u('assets/js/qrcode.min.js')?>"></script>
        <script>
        (function() {
            function renderClearanceQrs() {
                if (typeof QRCode === 'undefined') return;
                var elCert = document.getElementById('clearanceCertQr');
                if (elCert && !elCert.getAttribute('data-qr-rendered')) {
                    elCert.setAttribute('data-qr-rendered', '1');
                    var code = elCert.getAttribute('data-code');
                    elCert.innerHTML = '';
                    new QRCode(elCert, {
                        text: code,
                        width: 78,
                        height: 78,
                        colorDark: '#0b254e',
                        colorLight: '#ffffff',
                        correctLevel: QRCode.CorrectLevel.M
                    });
                }
                var elCard = document.getElementById('clearanceCardQr');
                if (elCard && !elCard.getAttribute('data-qr-rendered')) {
                    elCard.setAttribute('data-qr-rendered', '1');
                    var codeCard = elCard.getAttribute('data-code');
                    elCard.innerHTML = '';
                    new QRCode(elCard, {
                        text: codeCard,
                        width: 70,
                        height: 70,
                        colorDark: '#0b254e',
                        colorLight: '#ffffff',
                        correctLevel: QRCode.CorrectLevel.M
                    });
                }
            }
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', renderClearanceQrs);
            } else {
                renderClearanceQrs();
            }
        })();

        function switchClearanceView(mode) {
            const certView = document.getElementById('clearance_cert_view');
            const cardView = document.getElementById('clearance_card_view');
            const btnCert = document.getElementById('btn_view_cert');
            const btnCard = document.getElementById('btn_view_card');

            if (mode === 'card') {
                if (certView) certView.style.display = 'none';
                if (cardView) cardView.style.display = 'block';
                if (btnCard) { btnCard.style.background = 'var(--primary)'; btnCard.style.color = '#fff'; }
                if (btnCert) { btnCert.style.background = 'transparent'; btnCert.style.color = '#475569'; }
                document.body.className = 'clearance-mode-card';
            } else {
                if (certView) certView.style.display = 'block';
                if (cardView) cardView.style.display = 'none';
                if (btnCert) { btnCert.style.background = 'var(--primary)'; btnCert.style.color = '#fff'; }
                if (btnCard) { btnCard.style.background = 'transparent'; btnCard.style.color = '#475569'; }
                document.body.className = 'clearance-mode-cert';
            }
        }
        document.addEventListener('DOMContentLoaded', function() {
            switchClearanceView('<?=e($format)?>');
        });
        </script>
    </body>
    </html>
