// ==========================================================================
// 12C-2. PAGE: VERIFIKASI KEASLIAN SURAT BEBAS PUSTAKA (PUBLIC VALIDATION)
// ==========================================================================
if ($page === 'verify_clearance' || $page === 'validasi_bebas_pustaka') {
    $no = trim($_GET['no'] ?? '');
    $hash = trim($_GET['hash'] ?? '');
    $cid = (int)($_GET['id'] ?? 0);

    $cert = null;
    if (!empty($no)) {
        $stmt = $pdo->prepare("SELECT c.*, 
                               COALESCE(u.name, c.member_name, 'Siswa SMKN 5 Banda Aceh') AS member_name, 
                               COALESCE(u.member_code, c.member_code, '-') AS member_code, 
                               COALESCE(u.department, c.department, '-') AS department, 
                               COALESCE(u.phone, '-') AS phone, 
                               u.photo,
                               issuer.name AS issuer_name
                               FROM clearances c
                               LEFT JOIN users u ON u.id = c.member_id
                               LEFT JOIN users issuer ON issuer.id = c.issued_by
                               WHERE c.certificate_no = ? LIMIT 1");
        $stmt->execute([$no]);
        $cert = $stmt->fetch();
    } elseif (!empty($hash)) {
        $q = $pdo->query("SELECT c.*, 
                          COALESCE(u.name, c.member_name, 'Siswa SMKN 5 Banda Aceh') AS member_name, 
                          COALESCE(u.member_code, c.member_code, '-') AS member_code, 
                          COALESCE(u.department, c.department, '-') AS department, 
                          COALESCE(u.phone, '-') AS phone, 
                          u.photo,
                          issuer.name AS issuer_name
                          FROM clearances c
                          LEFT JOIN users u ON u.id = c.member_id
                          LEFT JOIN users issuer ON issuer.id = c.issued_by
                          ORDER BY c.id DESC LIMIT 200");
        while ($r = $q->fetch()) {
            $h1 = md5($r['certificate_no'] . $r['member_name']);
            $h2 = md5($r['certificate_no']);
            if (hash_equals($h1, $hash) || hash_equals($h2, $hash)) {
                $cert = $r;
                break;
            }
        }
    } elseif ($cid > 0) {
        $stmt = $pdo->prepare("SELECT c.*, 
                               COALESCE(u.name, c.member_name, 'Siswa SMKN 5 Banda Aceh') AS member_name, 
                               COALESCE(u.member_code, c.member_code, '-') AS member_code, 
                               COALESCE(u.department, c.department, '-') AS department, 
                               COALESCE(u.phone, '-') AS phone, 
                               u.photo,
                               issuer.name AS issuer_name
                               FROM clearances c
                               LEFT JOIN users u ON u.id = c.member_id
                               LEFT JOIN users issuer ON issuer.id = c.issued_by
                               WHERE c.id = ? LIMIT 1");
        $stmt->execute([$cid]);
        $cert = $stmt->fetch();
    }

    $isValid = false;
    $expectedHash = '';
    $activeLoansCount = 0;
    if ($cert) {
        $certMid = (int)($cert['member_id'] ?? 0);
        if ($certMid > 0) {
            $activeLoansCount = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE member_id = {$certMid} AND status = 'borrowed'")->fetchColumn();
        }
        $expectedHash = md5($cert['certificate_no'] . ($cert['member_name'] ?? ''));
        $altHash = md5($cert['certificate_no']);
        $isHashMatch = empty($hash) || hash_equals($expectedHash, $hash) || hash_equals($altHash, $hash);
        $isValid = ($isHashMatch && $activeLoansCount === 0);
    }

    $headTitle = get_setting('report_head_title', 'Kepala Perpustakaan');
    $headName = get_setting('report_head_name', 'Drs. Suparman, M.Pd');
    $headNip = get_setting('report_head_nip', 'NIP. 19750815 200501 1 004');
    $schoolTitle = get_school_name();
    $schoolSub = get_setting('navbar_subtitle', SCHOOL_SUB);
    $schoolLogo = get_setting('navbar_logo', 'assets/img/logo.jpg');
    $schoolAddress = get_setting('info_address', 'Jl. Teuku Nyak Arief No. 123, Banda Aceh');
    $schoolPhone = get_setting('info_phone', '(0651) 123456');
    $reportCity = get_setting('report_city', 'Banda Aceh');
