            echo "BK-002;Pemrograman Web Modern;5;Teknologi;Budi Raharjo;Informatika;2023;Dana BOS;85000;" . date('Y-m-d') . ";Panduan HTML, CSS, JavaScript dan PHP\r\n";
            echo "BK-003;Buku Sejarah Indonesia;15;Sosial;Sartono Kartodirdjo;Gramedia;2020;Hibah Pemerintah;0;" . date('Y-m-d') . ";Sejarah nasional Indonesia lengkap\r\n";
            echo "BK-004;Matematika Dasar Terapan;20;Sains;;;2022;Dana BOS;;;\r\n";
            echo "BK-005;Ensiklopedia Sains Anak;8;;;;;Dana BOS;;;\r\n";
            exit;
        }

        // Export seluruh data koleksi buku ke file Excel (.xls)
        $expWhere = ["1=1"];
        $expParams = [];
        $qExp = trim($_GET['q'] ?? '');
        $catExp = trim($_GET['category'] ?? '');
        $srcExp = trim($_GET['source'] ?? '');
        if ($qExp !== '') {
            $expWhere[] = "(title LIKE ? OR code LIKE ? OR author LIKE ? OR publisher LIKE ?)";
            $t = "%{$qExp}%";
            $expParams = [$t, $t, $t, $t];
        }
        if ($catExp !== '' && $catExp !== 'all') {
            $expWhere[] = "category = ?";
            $expParams[] = $catExp;
        }
        if ($srcExp !== '' && $srcExp !== 'all') {
            $expWhere[] = "source = ?";
            $expParams[] = $srcExp;
        }
        $stmtExp = $pdo->prepare("SELECT * FROM books WHERE " . implode(" AND ", $expWhere) . " ORDER BY id DESC");
        $stmtExp->execute($expParams);
        $expBooks = $stmtExp->fetchAll();

        header('Content-Type: application/vnd.ms-excel; charset=utf-8');
        header('Content-Disposition: attachment; filename="data_buku_perpustakaan_' . date('Ymd_His') . '.xls"');
        echo '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
<head>
<meta http-equiv="Content-Type" content="text/html; charset=utf-8">
<style>
.text { mso-number-format:"\@"; }
th { background-color: #0f172a; color: #ffffff; font-weight: bold; text-align: left; padding: 8px 12px; border: 1px solid #94a3b8; }
td { padding: 6px 12px; border: 1px solid #cbd5e1; }
.center { text-align: center; }
.right { text-align: right; }
</style>
</head>
<body>
<table>
<thead>
<tr>
  <th class="center">No</th>
  <th>Kode Buku</th>
  <th>Judul Buku</th>
  <th>Kategori</th>
  <th>Penulis</th>
  <th>Penerbit</th>
  <th class="center">Tahun Terbit</th>
  <th>Sumber Buku</th>
  <th class="right">Harga (Rp)</th>
  <th class="center">Total Stok</th>
  <th class="center">Tersedia</th>
  <th class="center">Tgl Penerimaan</th>
  <th>Deskripsi</th>
</tr>
</thead>
<tbody>';
        $noExp = 1;
        foreach ($expBooks as $eb) {
            $tglP = !empty($eb['tanggal_penerimaan']) ? date('d/m/Y', strtotime($eb['tanggal_penerimaan'])) : '-';
            echo '<tr>
  <td class="center">' . $noExp++ . '</td>
  <td class="text"><b>' . htmlspecialchars($eb['code'], ENT_QUOTES, 'UTF-8') . '</b></td>
  <td>' . htmlspecialchars($eb['title'], ENT_QUOTES, 'UTF-8') . '</td>
  <td>' . htmlspecialchars($eb['category'] ?: 'Umum', ENT_QUOTES, 'UTF-8') . '</td>
  <td>' . htmlspecialchars($eb['author'] ?: '-', ENT_QUOTES, 'UTF-8') . '</td>
  <td>' . htmlspecialchars($eb['publisher'] ?: '-', ENT_QUOTES, 'UTF-8') . '</td>
  <td class="center">' . htmlspecialchars($eb['year_published'] ?: '-', ENT_QUOTES, 'UTF-8') . '</td>
  <td>' . htmlspecialchars($eb['source'] ?: 'Dana BOS', ENT_QUOTES, 'UTF-8') . '</td>
  <td class="right">' . (!empty($eb['price']) ? number_format((int)$eb['price'], 0, ',', '.') : '-') . '</td>
  <td class="center"><b>' . (int)$eb['quantity'] . '</b></td>
  <td class="center">' . (int)$eb['available'] . '</td>
  <td class="text center">' . $tglP . '</td>
  <td>' . htmlspecialchars($eb['description'] ?: '', ENT_QUOTES, 'UTF-8') . '</td>
</tr>';
        }
        echo '</tbody></table></body></html>';
        exit;
    }

    // Handle POST Actions
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $action = $_POST['action'] ?? 'add_book';

        // 0. IMPORT MASSAL BUKU DARI EXCEL / CSV ATAU PASTE TEXT
        if ($action === 'import_books') {
            $hasFile = !empty($_FILES['file_excel']['name']) && $_FILES['file_excel']['error'] === UPLOAD_ERR_OK;
            $rawText = trim($_POST['raw_text'] ?? '');
            $defaultCategory = trim($_POST['default_category'] ?? 'Umum');
            if ($defaultCategory === '') $defaultCategory = 'Umum';
            $defaultSource = trim($_POST['default_source'] ?? 'Dana BOS');
            if ($defaultSource === '') $defaultSource = 'Dana BOS';
            $onDuplicate = trim($_POST['on_duplicate'] ?? 'update');

            if (!$hasFile && $rawText === '') {
                flash('⚠️ Anda belum memilih berkas Excel / CSV dan belum menempelkan data buku. Silakan pilih file Excel (.xlsx / .xls / .csv) atau tempelkan data baris buku ke kotak teks.', 'error');
                header('Location: ' . u('index.php?page=admin_books&open_import=1'));
                exit;
            }

            $rows = [];
            if ($hasFile) {
                $ext = strtolower(pathinfo($_FILES['file_excel']['name'], PATHINFO_EXTENSION));
                $tmpPath = $_FILES['file_excel']['tmp_name'];
                $fileHeader = @file_get_contents($tmpPath, false, null, 0, 8) ?: '';
                $isZip = (substr($fileHeader, 0, 4) === "PK\x03\x04");

                // 1. Parsing XLSX secara native via ZipArchive dan SimpleXML
                if (($ext === 'xlsx' || $isZip) && class_exists('ZipArchive')) {
                    $zip = new ZipArchive();
                    if ($zip->open($tmpPath) === true) {
                        $sharedStrings = [];
                        $sstXml = $zip->getFromName('xl/sharedStrings.xml');
                        if ($sstXml) {
                            $sstXmlClean = preg_replace('/\sxmlns[^=]*="[^"]*"/i', '', $sstXml);
                            $xmlSst = @simplexml_load_string($sstXmlClean);
                            if ($xmlSst && isset($xmlSst->si)) {
                                foreach ($xmlSst->si as $item) {
                                    if (isset($item->t)) {
                                        $sharedStrings[] = (string)$item->t;
                                    } elseif (isset($item->r)) {
                                        $tBuf = '';
                                        foreach ($item->r as $rPart) {
                                            $tBuf .= (string)($rPart->t ?? '');
                                        }
                                        $sharedStrings[] = $tBuf;
                                    } else {
                                        $sharedStrings[] = '';
                                    }
                                }
                            }
                        }

                        $sheetXml = $zip->getFromName('xl/worksheets/sheet1.xml');
                        if (!$sheetXml) {
                            for ($zi = 0; $zi < $zip->numFiles; $zi++) {
                                $zName = $zip->getNameIndex($zi);
                                if (strpos($zName, 'xl/worksheets/sheet') === 0 && substr($zName, -4) === '.xml') {
                                    $sheetXml = $zip->getFromIndex($zi);
                                    break;
                                }
                            }
                        }

                        if ($sheetXml) {
                            $sheetXmlClean = preg_replace('/\sxmlns[^=]*="[^"]*"/i', '', $sheetXml);
                            $xmlSheet = @simplexml_load_string($sheetXmlClean);
                            if ($xmlSheet && isset($xmlSheet->sheetData->row)) {
                                foreach ($xmlSheet->sheetData->row as $r) {
                                    $rowCells = [];
                                    $currCol = 0;
                                    foreach ($r->c as $c) {
                                        $cellRef = (string)($c['r'] ?? '');
                                        if ($cellRef !== '') {
                                            $colLetters = preg_replace('/[0-9]/', '', $cellRef);
                                            $targetCol = 0;
                                            for ($l = 0; $l < strlen($colLetters); $l++) {
                                                $targetCol = $targetCol * 26 + (ord(strtoupper($colLetters[$l])) - ord('A') + 1);
                                            }
                                            $targetCol--;
                                            while ($currCol < $targetCol) {
                                                $rowCells[] = '';
                                                $currCol++;
                                            }
                                        }

                                        $type = (string)($c['t'] ?? '');
                                        $val = '';
                                        if ($type === 's') {
                                            $idx = (int)(string)$c->v;
                                            $val = $sharedStrings[$idx] ?? '';
                                        } elseif ($type === 'inlineStr') {
                                            $val = (string)($c->is->t ?? '');
                                        } else {
                                            $val = (string)($c->v ?? '');
                                        }
                                        $valClean = str_replace(["\xc2\xa0", "&nbsp;"], ' ', $val);
                                        $rowCells[] = trim($valClean, " \t\n\r\0\x0B'`\"");
                                        $currCol++;
                                    }
                                    if (!empty(array_filter($rowCells, fn($v) => $v !== ''))) {
                                        $rows[] = $rowCells;
                                    }
                                }
                            }
                        }
                        $zip->close();
                    }
                }

                // 2. Parsing format HTML table (.xls)
                if (empty($rows)) {
                    $fileContent = @file_get_contents($tmpPath);
                    if ($fileContent !== false && strpos($fileContent, "\0") === false && stripos($fileContent, '<table') !== false) {
                        preg_match_all('/<tr[^>]*>(.*?)<\/tr>/is', $fileContent, $trMatches);
                        if (!empty($trMatches[1])) {
                            foreach ($trMatches[1] as $trHtml) {
                                preg_match_all('/<(?:td|th)[^>]*>(.*?)<\/(?:td|th)>/is', $trHtml, $tdMatches);
                                if (!empty($tdMatches[1])) {
                                    $rowCells = array_map(function($c) {
                                        $c = str_replace(["\xc2\xa0", "&nbsp;"], ' ', (string)$c);
                                        return trim(html_entity_decode(strip_tags($c), ENT_QUOTES, 'UTF-8'), " \t\n\r\0\x0B'`\"");
                                    }, $tdMatches[1]);
                                    if (!empty(array_filter($rowCells, fn($v) => $v !== ''))) {
                                        $rows[] = $rowCells;
                                    }
                                }
                            }
                        }
                    }

                    // 3. Parsing format teks CSV / TSV
                    if (empty($rows) && $fileContent !== false && strpos($fileContent, "\0") === false) {
                        if (substr($fileContent, 0, 3) === "\xEF\xBB\xBF") {
                            $fileContent = substr($fileContent, 3);
                        }
                        if (substr($fileContent, 0, 2) === "\xFF\xFE") {
                            $fileContent = mb_convert_encoding(substr($fileContent, 2), 'UTF-8', 'UTF-16LE');
                        }
                        $fLines = preg_split('/\r\n|\r|\n/', $fileContent);
                        foreach ($fLines as $fl) {
                            $fl = trim($fl);
                            if ($fl === '') continue;
                            $sep = ',';
                            $cntSemi = substr_count($fl, ';');
                            $cntComma = substr_count($fl, ',');
                            $cntTab = substr_count($fl, "\t");
                            if ($cntTab > $cntComma && $cntTab > $cntSemi) {
                                $sep = "\t";
                            } elseif ($cntSemi > $cntComma) {
                                $sep = ';';
                            }
                            $parsed = ($sep === "\t") ? explode("\t", $fl) : str_getcsv($fl, $sep);
                            $clean = array_map(function($v) {
                                $v = str_replace(["\xc2\xa0", "&nbsp;"], ' ', (string)$v);
                                return trim((string)$v, " \t\n\r\0\x0B'`\"");
                            }, $parsed);
                            if (!empty(array_filter($clean, fn($v) => $v !== ''))) {
                                $rows[] = $clean;
                            }
                        }
                    }
                }
            }

            // 4. Parsing Teks Hasil Copy - Paste dari Excel
            if (empty($rows) && $rawText !== '') {
                $lines = preg_split('/\r\n|\r|\n/', $rawText);
                foreach ($lines as $line) {
                    $line = trim($line);
                    if ($line === '') continue;
                    $parsed = [];
                    if (strpos($line, "\t") !== false) {
                        $parsed = explode("\t", $line);
                    } elseif (strpos($line, ';') !== false) {
                        $parsed = str_getcsv($line, ';');
                    } elseif (strpos($line, ',') !== false) {
                        $parsed = str_getcsv($line, ',');
                    } elseif (preg_match('/\s{2,}/', $line)) {
                        $parsed = preg_split('/\s{2,}/', $line);
                    } else {
                        $parsed = str_getcsv($line);
                    }
                    $clean = array_map(function($v) {
                        $v = str_replace(["\xc2\xa0", "&nbsp;"], ' ', (string)$v);
                        return trim((string)$v, " \t\n\r\0\x0B'`\"");
                    }, $parsed);
                    if (!empty(array_filter($clean, fn($v) => $v !== ''))) {
                        $rows[] = $clean;
                    }
                }
            }

            if (empty($rows)) {
                flash('⚠️ Tidak ditemukan baris data yang valid di dalam berkas atau teks yang diunggah. Pastikan data tidak kosong. Jika menggunakan Excel .xls lama (binary 97-2003), silakan simpan sebagai Excel (.xlsx) / CSV (.csv), atau blok tabel di Excel lalu Copy-Paste ke kotak teks.', 'error');
                header('Location: ' . u('index.php?page=admin_books&open_import=1'));
                exit;
            }

            // Smart Header Mapping
            $colCode = -1;
            $colTitle = -1;
            $colQty = -1;
            $colCat = -1;
            $colAuthor = -1;
            $colPublisher = -1;
            $colYear = -1;
            $colSource = -1;
            $colPrice = -1;
            $colDate = -1;
            $colDesc = -1;

            $hasHeader = false;
            $firstRow = $rows[0];
            $firstRowStr = strtolower(implode(' ', $firstRow));
            if (strpos($firstRowStr, 'kode') !== false || strpos($firstRowStr, 'judul') !== false || strpos($firstRowStr, 'title') !== false || strpos($firstRowStr, 'buku') !== false || strpos($firstRowStr, 'jumlah') !== false || strpos($firstRowStr, 'qty') !== false || strpos($firstRowStr, 'stok') !== false) {
                $hasHeader = true;
                foreach ($firstRow as $idx => $cell) {
                    $cLower = strtolower(trim($cell));
                    if (strpos($cLower, 'kode') !== false || strpos($cLower, 'code') !== false || strpos($cLower, 'isbn') !== false || strpos($cLower, 'barcode') !== false) {
                        $colCode = $idx;
                    } elseif (strpos($cLower, 'judul') !== false || strpos($cLower, 'title') !== false || strpos($cLower, 'nama buku') !== false) {
                        $colTitle = $idx;
                    } elseif (strpos($cLower, 'jumlah') !== false || strpos($cLower, 'qty') !== false || strpos($cLower, 'quantity') !== false || strpos($cLower, 'stok') !== false || strpos($cLower, 'total') !== false || strpos($cLower, 'eksemplar') !== false) {
                        $colQty = $idx;
                    } elseif (strpos($cLower, 'kategori') !== false || strpos($cLower, 'category') !== false || strpos($cLower, 'jenis') !== false) {
                        $colCat = $idx;
                    } elseif (strpos($cLower, 'penulis') !== false || strpos($cLower, 'author') !== false || strpos($cLower, 'pengarang') !== false) {
                        $colAuthor = $idx;
                    } elseif (strpos($cLower, 'penerbit') !== false || strpos($cLower, 'publisher') !== false) {
                        $colPublisher = $idx;
                    } elseif (strpos($cLower, 'tahun') !== false || strpos($cLower, 'year') !== false) {
                        $colYear = $idx;
                    } elseif (strpos($cLower, 'sumber') !== false || strpos($cLower, 'source') !== false || strpos($cLower, 'dana') !== false || strpos($cLower, 'pengadaan') !== false) {
                        $colSource = $idx;
                    } elseif (strpos($cLower, 'harga') !== false || strpos($cLower, 'price') !== false) {
                        $colPrice = $idx;
                    } elseif (strpos($cLower, 'tanggal') !== false || strpos($cLower, 'tgl') !== false || strpos($cLower, 'terima') !== false || strpos($cLower, 'date') !== false) {
                        $colDate = $idx;
                    } elseif (strpos($cLower, 'deskripsi') !== false || strpos($cLower, 'desc') !== false || strpos($cLower, 'keterangan') !== false) {
                        $colDesc = $idx;
                    }
                }
            }

            // Fallback default column indexes jika tidak terdeteksi via nama kolom
            if ($colCode === -1) $colCode = 0;
            if ($colTitle === -1) $colTitle = 1;
            if ($colQty === -1) $colQty = 2;
            if ($colCat === -1 && isset($firstRow[3])) $colCat = 3;
            if ($colAuthor === -1 && isset($firstRow[4])) $colAuthor = 4;
            if ($colPublisher === -1 && isset($firstRow[5])) $colPublisher = 5;
            if ($colYear === -1 && isset($firstRow[6])) $colYear = 6;
            if ($colSource === -1 && isset($firstRow[7])) $colSource = 7;
            if ($colPrice === -1 && isset($firstRow[8])) $colPrice = 8;
            if ($colDate === -1 && isset($firstRow[9])) $colDate = 9;
            if ($colDesc === -1 && isset($firstRow[10])) $colDesc = 10;

            $startIndex = $hasHeader ? 1 : 0;
            $insertedCount = 0;
            $updatedCount = 0;
            $skippedCount = 0;
            $failedErrors = [];

            for ($i = $startIndex; $i < count($rows); $i++) {
                $r = $rows[$i];
                $code = ($colCode >= 0 && isset($r[$colCode])) ? trim((string)$r[$colCode], " \t\n\r\0\x0B'`\"") : '';
                $title = ($colTitle >= 0 && isset($r[$colTitle])) ? trim((string)$r[$colTitle], " \t\n\r\0\x0B'`\"") : '';
                $rawQty = ($colQty >= 0 && isset($r[$colQty])) ? trim((string)$r[$colQty], " \t\n\r\0\x0B'`\"") : '';
                $cleanQty = preg_replace('/[^0-9]/', '', $rawQty);
                $qty = ($cleanQty !== '') ? (int)$cleanQty : 0;

                // Abaikan jika seluruh kolom baris kosong
                if ($code === '' && $title === '' && $rawQty === '') {
                    continue;
                }

                // Validasi kolom WAJIB: Kode Buku, Judul Buku, dan Jumlah Buku
                if ($code === '' || $title === '' || $cleanQty === '' || $qty <= 0) {
                    $missing = [];
                    if ($code === '') $missing[] = 'Kode Buku';
                    if ($title === '') $missing[] = 'Judul Buku';
                    if ($cleanQty === '' || $qty <= 0) $missing[] = 'Jumlah Buku (stok)';
                    $failedErrors[] = "Baris " . ($i + 1) . ": " . implode(', ', $missing) . " wajib diisi.";
                    continue;
                }

                // Kolom Opsional (Boleh Kosong)
                $cat = ($colCat >= 0 && isset($r[$colCat])) ? trim((string)$r[$colCat], " \t\n\r\0\x0B'`\"") : '';
                if ($cat === '') $cat = $defaultCategory;
                try {
                    $pdo->prepare("INSERT IGNORE INTO categories (name) VALUES (?)")->execute([$cat]);
                } catch (Throwable $e) {}

                $author = ($colAuthor >= 0 && isset($r[$colAuthor])) ? trim((string)$r[$colAuthor], " \t\n\r\0\x0B'`\"") : '';
                $publisher = ($colPublisher >= 0 && isset($r[$colPublisher])) ? trim((string)$r[$colPublisher], " \t\n\r\0\x0B'`\"") : '';

                $rawYear = ($colYear >= 0 && isset($r[$colYear])) ? trim((string)$r[$colYear], " \t\n\r\0\x0B'`\"") : '';
                $year = (int)preg_replace('/[^0-9]/', '', $rawYear) ?: null;

                $source = ($colSource >= 0 && isset($r[$colSource])) ? trim((string)$r[$colSource], " \t\n\r\0\x0B'`\"") : '';
                if ($source === '') $source = $defaultSource;
                try {
                    $pdo->prepare("INSERT IGNORE INTO procurement_sources (name) VALUES (?)")->execute([$source]);
                } catch (Throwable $e) {}

                $rawPrice = ($colPrice >= 0 && isset($r[$colPrice])) ? trim((string)$r[$colPrice], " \t\n\r\0\x0B'`\"") : '';
                $cleanPrice = preg_replace('/[^0-9]/', '', $rawPrice);
                $price = ($cleanPrice !== '') ? (int)$cleanPrice : null;

                $rawDate = ($colDate >= 0 && isset($r[$colDate])) ? trim((string)$r[$colDate], " \t\n\r\0\x0B'`\"") : '';
                if (preg_match('/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/', $rawDate, $dMatch)) {
                    $tanggalPenerimaan = sprintf('%04d-%02d-%02d', (int)$dMatch[3], (int)$dMatch[2], (int)$dMatch[1]);
                } elseif (preg_match('/^\d{4}-\d{2}-\d{2}$/', $rawDate)) {
                    $tanggalPenerimaan = $rawDate;
                } else {
                    $tanggalPenerimaan = date('Y-m-d');
                }
                $tahunPenerimaan = (int)date('Y', strtotime($tanggalPenerimaan));

                $desc = ($colDesc >= 0 && isset($r[$colDesc])) ? trim((string)$r[$colDesc], " \t\n\r\0\x0B'`\"") : '';

                try {
                    $chk = $pdo->prepare("SELECT id, quantity, available FROM books WHERE code = ? LIMIT 1");
                    $chk->execute([$code]);
                    $exist = $chk->fetch();

                    if ($exist) {
                        if ($onDuplicate === 'update') {
                            $bookId = (int)$exist['id'];
                            $oldQty = (int)$exist['quantity'];
                            $oldAvail = (int)$exist['available'];
                            $diff = $qty - $oldQty;
                            $newAvail = max(0, $oldAvail + $diff);

                            $upd = $pdo->prepare("UPDATE books SET title = ?, author = COALESCE(NULLIF(?, ''), author), publisher = COALESCE(NULLIF(?, ''), publisher), year_published = COALESCE(?, year_published), category = ?, source = ?, price = COALESCE(?, price), quantity = ?, available = ?, description = COALESCE(NULLIF(?, ''), description), tanggal_penerimaan = ?, tahun_penerimaan = ? WHERE id = ?");
                            $upd->execute([$title, $author, $publisher, $year, $cat, $source, $price, $qty, $newAvail, $desc, $tanggalPenerimaan, $tahunPenerimaan, $bookId]);
                            try {
                                $pdo->prepare("UPDATE books SET sumber_pengadaan = ? WHERE id = ?")->execute([$source, $bookId]);
                            } catch (Throwable $e) {}
                            $updatedCount++;
                        } else {
                            $skippedCount++;
                        }
                    } else {
                        $ins = $pdo->prepare("INSERT INTO books (code, title, author, publisher, year_published, category, source, price, quantity, copy_serials, available, description, tanggal_penerimaan, tahun_penerimaan, cover_image) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?, ?, NULL)");
                        $ins->execute([$code, $title, $author, $publisher, $year, $cat, $source, $price, $qty, $qty, $desc, $tanggalPenerimaan, $tahunPenerimaan]);
                        $newBId = $pdo->lastInsertId();
                        try {
                            $pdo->prepare("UPDATE books SET sumber_pengadaan = ? WHERE id = ?")->execute([$source, $newBId]);
                        } catch (Throwable $e) {}
                        $insertedCount++;
                    }
                } catch (Throwable $eRow) {
                    $failedErrors[] = "Kode {$code} ({$title}): " . $eRow->getMessage();
                }
            }

            $totalProcessed = $insertedCount + $updatedCount;
            if ($totalProcessed > 0) {
                $succMsg = "🎉 <b>Import Buku Berhasil!</b><br>• <b>{$insertedCount}</b> judul buku baru berhasil ditambahkan.<br>• <b>{$updatedCount}</b> data buku diperbarui.";
                if ($skippedCount > 0) $succMsg .= "<br>• <b>{$skippedCount}</b> data dilewati (karena kode buku sudah ada).";
                if (!empty($failedErrors)) $succMsg .= "<br>⚠️ Catatan baris gagal: " . htmlspecialchars(implode(', ', array_slice($failedErrors, 0, 5)));
                flash($succMsg);
            } else {
                $errDetail = !empty($failedErrors) ? ('<br>Penyebab error: ' . htmlspecialchars(implode(', ', array_slice($failedErrors, 0, 5)))) : '';
                flash("⚠️ Tidak ada data buku yang berhasil disimpan. Pastikan berkas Excel / CSV berisi kolom <b>Kode Buku</b>, <b>Judul Buku</b>, dan <b>Jumlah Buku</b> (wajib diisi)." . $errDetail, 'error');
            }

            header('Location: ' . u('index.php?page=admin_books'));
            exit;
        }

        // 1. TAMBAH KATEGORI BARU
        if ($action === 'add_category') {
            $catName = trim($_POST['category_name'] ?? '');
            $callNumber = trim($_POST['call_number'] ?? '');
            if ($catName !== '') {
                $insC = $pdo->prepare("INSERT INTO categories (call_number, name) VALUES (?, ?) ON DUPLICATE KEY UPDATE call_number = COALESCE(VALUES(call_number), call_number)");
                $insC->execute([$callNumber ?: null, $catName]);
                flash('Kategori baru "' . $catName . '"' . ($callNumber ? " (Nomor Panggil: {$callNumber})" : "") . ' berhasil ditambahkan.');
            } else {
                flash('Nama kategori tidak boleh kosong.', 'error');
            }
            header('Location: ' . u('index.php?page=admin_books'));
            exit;
        }

        // 2. HAPUS KATEGORI
        if ($action === 'delete_category') {
            $catId = (int)($_POST['category_id'] ?? 0);
            $cStmt = $pdo->prepare("SELECT name FROM categories WHERE id = ? LIMIT 1");
            $cStmt->execute([$catId]);
            $cRow = $cStmt->fetch();

            if ($cRow) {
                $catName = $cRow['name'];
                $chkStmt = $pdo->prepare("SELECT COUNT(*) FROM books WHERE category = ?");
                $chkStmt->execute([$catName]);
                $bCount = (int)$chkStmt->fetchColumn();

                if ($bCount > 0) {
                    // Pastikan kategori penampung 'Umum' tersedia
                    $pdo->exec("INSERT IGNORE INTO categories (name) VALUES ('Umum')");
                    $pdo->prepare("UPDATE books SET category = 'Umum' WHERE category = ?")->execute([$catName]);
                }
                $pdo->prepare("DELETE FROM categories WHERE id = ?")->execute([$catId]);
                flash('Kategori "' . e($catName) . '" berhasil dihapus' . ($bCount > 0 ? " ({$bCount} buku dialihkan ke kategori 'Umum')." : '.'));
            }
            header('Location: ' . u('index.php?page=admin_books'));
            exit;
        }

        // 2B. TAMBAH SUMBER PENGADAAN BUKU
        if ($action === 'add_procurement_source') {
            $srcName = trim($_POST['source_name'] ?? '');
            if ($srcName !== '') {
                $insS = $pdo->prepare("INSERT IGNORE INTO procurement_sources (name) VALUES (?)");
                $insS->execute([$srcName]);
                flash('Sumber pengadaan baru "' . $srcName . '" berhasil ditambahkan.');
            } else {
                flash('Nama sumber pengadaan tidak boleh kosong.', 'error');
            }
            header('Location: ' . u('index.php?page=admin_books'));
            exit;
        }

        // 2C. HAPUS SUMBER PENGADAAN BUKU
        if ($action === 'delete_procurement_source') {
            $srcId = (int)($_POST['source_id'] ?? 0);
            $sStmt = $pdo->prepare("SELECT name FROM procurement_sources WHERE id = ? LIMIT 1");
            $sStmt->execute([$srcId]);
            $sRow = $sStmt->fetch();

            if ($sRow) {
                $srcName = $sRow['name'];
                $chkStmt = $pdo->prepare("SELECT COUNT(*) FROM books WHERE source = ?");
                $chkStmt->execute([$srcName]);
                $bCount = (int)$chkStmt->fetchColumn();

                if ($bCount > 0) {
                    $pdo->prepare("UPDATE books SET source = 'Dana BOS' WHERE source = ?")->execute([$srcName]);
                    try {
                        $pdo->prepare("UPDATE books SET sumber_pengadaan = 'Dana BOS' WHERE sumber_pengadaan = ?")->execute([$srcName]);
                    } catch (Throwable $e) {}
                }
                $pdo->prepare("DELETE FROM procurement_sources WHERE id = ?")->execute([$srcId]);
                $pdo->exec("INSERT IGNORE INTO procurement_sources (name) VALUES ('Dana BOS')");
                flash('Sumber pengadaan "' . e($srcName) . '" berhasil dihapus' . ($bCount > 0 ? " ({$bCount} buku disesuaikan ke 'Dana BOS')." : '.'));
            }
            header('Location: ' . u('index.php?page=admin_books'));
            exit;
        }

        // 3. HAPUS BUKU
        // 3. HAPUS BUKU (DIPINDAHKAN KE ARSIP SELAMA 2 X 24 JAM / 48 JAM)
        if ($action === 'delete_book') {
            $bookId = (int)($_POST['book_id'] ?? 0);
            $bStmt = $pdo->prepare("SELECT * FROM books WHERE id = ? LIMIT 1");
            $bStmt->execute([$bookId]);
            $bookRow = $bStmt->fetch();

            if (!$bookRow) {
                flash('Buku tidak ditemukan.', 'error');
            } else {
                // Check active loans
                $chkLoan = $pdo->prepare("SELECT COUNT(*) FROM loans WHERE book_id = ? AND status IN ('borrowed', 'approved', 'pending')");
                $chkLoan->execute([$bookId]);
                $activeLoanCount = (int)$chkLoan->fetchColumn();

                if ($activeLoanCount > 0) {
                    flash('Buku "' . $bookRow['title'] . '" tidak dapat dihapus karena masih sedang dipinjam oleh anggota.', 'error');
                } else {
                    // Backup historical loans
                    $bLoans = [];
                    try {
                        $sL = $pdo->prepare("SELECT * FROM loans WHERE book_id = ?");
                        $sL->execute([$bookId]);
                        $bLoans = $sL->fetchAll();
                    } catch (Throwable $e) {}

                    $backupJson = json_encode([
                        'loans' => $bLoans,
                    ]);

                    // Pindahkan ke tabel arsip dengan masa aktif 2 x 24 jam (48 jam)
                    try {
                        $archStmt = $pdo->prepare("INSERT INTO archived_books 
                            (original_id, code, title, author, publisher, year_published, category, source, price, tanggal_penerimaan, tahun_penerimaan, quantity, available, copy_serials, description, cover_image, original_created_at, deleted_at, expires_at, backup_data)
                            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), DATE_ADD(NOW(), INTERVAL 48 HOUR), ?)");
                        $archStmt->execute([
                            $bookRow['id'],
                            $bookRow['code'],
                            $bookRow['title'],
                            $bookRow['author'],
                            $bookRow['publisher'],
                            $bookRow['year_published'],
                            $bookRow['category'],
                            $bookRow['source'],
                            $bookRow['price'],
                            $bookRow['tanggal_penerimaan'],
                            $bookRow['tahun_penerimaan'],
                            $bookRow['quantity'],
                            $bookRow['available'],
                            $bookRow['copy_serials'],
                            $bookRow['description'],
                            $bookRow['cover_image'],
                            $bookRow['created_at'],
                            $backupJson
                        ]);
                    } catch (Throwable $e) {}

                    // Pindahkan buku dari tabel aktif ke arsip (riwayat transaksi pinjaman lama tetap dipertahankan utuh demi integritas data & laporan)
                    $pdo->prepare("DELETE FROM books WHERE id = ?")->execute([$bookId]);

                    flash('Buku "' . $bookRow['title'] . '" berhasil dipindahkan ke Arsip (tersimpan selama 2 x 24 jam). Anda dapat memulihkannya kapan saja.');
                }
            }
            header('Location: ' . u('index.php?page=admin_books'));
            exit;
        }

        // HAPUS BANYAK BUKU SEKALIGUS / HAPUS DATA SEMUA KE ARSIP
        if ($action === 'bulk_delete_books') {
            $selectedIdsRaw = trim($_POST['selected_ids'] ?? '');
            $deleteScope = trim($_POST['delete_all_scope'] ?? 'selected');
            $targetIds = [];

            if ($deleteScope === 'all') {
                $allStmt = $pdo->query("SELECT id FROM books");
                $targetIds = $allStmt->fetchAll(PDO::FETCH_COLUMN);
            } elseif ($selectedIdsRaw !== '') {
                $parts = explode(',', $selectedIdsRaw);
                foreach ($parts as $p) {
                    $pid = (int)trim($p);
                    if ($pid > 0) $targetIds[] = $pid;
                }
            } elseif (!empty($_POST['selected_book_ids']) && is_array($_POST['selected_book_ids'])) {
                foreach ($_POST['selected_book_ids'] as $p) {
                    $pid = (int)$p;
                    if ($pid > 0) $targetIds[] = $pid;
                }
            }

            if (empty($targetIds)) {
                flash('Tidak ada buku yang dipilih untuk dihapus.', 'error');
            } else {
                $successCount = 0;
                $skippedLoanTitles = [];

                foreach ($targetIds as $bid) {
                    $bStmt = $pdo->prepare("SELECT * FROM books WHERE id = ? LIMIT 1");
                    $bStmt->execute([$bid]);
                    $book = $bStmt->fetch();
                    if (!$book) continue;

                    // Periksa pinjaman aktif
                    $chkLoan = $pdo->prepare("SELECT COUNT(*) FROM loans WHERE book_id = ? AND status IN ('borrowed', 'approved', 'pending')");
                    $chkLoan->execute([$bid]);
                    if ((int)$chkLoan->fetchColumn() > 0) {
                        $skippedLoanTitles[] = $book['title'];
                        continue;
                    }

                    // Backup riwayat peminjaman
                    $bLoans = [];
                    try {
                        $sL = $pdo->prepare("SELECT * FROM loans WHERE book_id = ?");
                        $sL->execute([$bid]);
                        $bLoans = $sL->fetchAll();
                    } catch (Throwable $e) {}

                    $backupJson = json_encode([
                        'loans' => $bLoans,
                    ]);

                    // Pindahkan ke arsip
                    try {
                        $archStmt = $pdo->prepare("INSERT INTO archived_books 
                            (original_id, code, title, author, publisher, year_published, category, source, price, tanggal_penerimaan, tahun_penerimaan, quantity, available, copy_serials, description, cover_image, original_created_at, deleted_at, expires_at, backup_data)
                            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), DATE_ADD(NOW(), INTERVAL 48 HOUR), ?)");
                        $archStmt->execute([
                            $book['id'],
                            $book['code'],
                            $book['title'],
                            $book['author'],
                            $book['publisher'],
                            $book['year_published'],
                            $book['category'],
                            $book['source'],
                            $book['price'],
                            $book['tanggal_penerimaan'],
                            $book['tahun_penerimaan'],
                            $book['quantity'],
                            $book['available'],
                            $book['copy_serials'],
                            $book['description'],
                            $book['cover_image'],
                            $book['created_at'],
                            $backupJson
                        ]);
                    } catch (Throwable $e) {}

                    // Pindahkan buku dari tabel aktif ke arsip (riwayat transaksi pinjaman lama tetap dipertahankan utuh demi integritas data & laporan)
                    $pdo->prepare("DELETE FROM books WHERE id = ?")->execute([$bid]);

                    $successCount++;
                }

                $msg = "Sebanyak {$successCount} judul buku berhasil dipindahkan ke Arsip (tersimpan selama 2 x 24 jam).";
                if (!empty($skippedLoanTitles)) {
                    $cntSkip = count($skippedLoanTitles);
                    $titlesPreview = implode(', ', array_slice($skippedLoanTitles, 0, 3));
                    if ($cntSkip > 3) $titlesPreview .= " dan " . ($cntSkip - 3) . " lainnya";
                    $msg .= " (Catatan: {$cntSkip} buku dilewati karena sedang dipinjam oleh siswa: {$titlesPreview}).";
                }
                flash($msg, $successCount > 0 ? 'success' : 'warning');
            }
            header('Location: ' . u('index.php?page=admin_books'));
            exit;
        }

        // PULIHKAN / BALIKKAN DATA BUKU DARI ARSIP
        if ($action === 'restore_book') {
            $aid = (int)($_POST['archive_id'] ?? 0);
            $archStmt = $pdo->prepare("SELECT * FROM archived_books WHERE id = ? LIMIT 1");
            $archStmt->execute([$aid]);
            $arch = $archStmt->fetch();

            if (!$arch) {
                flash('Data arsip buku tidak ditemukan atau sudah kadaluarsa (melewati batas 2 x 24 jam).', 'error');
            } else {
                $targetCode = $arch['code'];
                $chkC = $pdo->prepare("SELECT id FROM books WHERE code = ? LIMIT 1");
                $chkC->execute([$targetCode]);
                if ($chkC->fetch()) {
                    $targetCode = $arch['code'] . '-KEMBALI-' . rand(10, 99);
                }

                $chkId = $pdo->prepare("SELECT id FROM books WHERE id = ? LIMIT 1");
                $chkId->execute([$arch['original_id']]);
                $origFree = !$chkId->fetch();

                if ($origFree) {
                    $ins = $pdo->prepare("INSERT INTO books (id, code, title, author, publisher, year_published, category, source, price, tanggal_penerimaan, tahun_penerimaan, quantity, available, copy_serials, description, cover_image, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
                    $ins->execute([
                        $arch['original_id'],
                        $targetCode,
                        $arch['title'],
                        $arch['author'],
                        $arch['publisher'],
                        $arch['year_published'],
                        $arch['category'],
                        $arch['source'],
                        $arch['price'],
                        $arch['tanggal_penerimaan'],
                        $arch['tahun_penerimaan'],
                        $arch['quantity'],
                        $arch['available'],
                        $arch['copy_serials'],
                        $arch['description'],
                        $arch['cover_image'],
                        $arch['original_created_at'] ?: date('Y-m-d H:i:s')
                    ]);
                    $restoredBid = $arch['original_id'];
                } else {
                    $ins = $pdo->prepare("INSERT INTO books (code, title, author, publisher, year_published, category, source, price, tanggal_penerimaan, tahun_penerimaan, quantity, available, copy_serials, description, cover_image, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
                    $ins->execute([
                        $targetCode,
                        $arch['title'],
                        $arch['author'],
                        $arch['publisher'],
                        $arch['year_published'],
                        $arch['category'],
                        $arch['source'],
                        $arch['price'],
                        $arch['tanggal_penerimaan'],
                        $arch['tahun_penerimaan'],
                        $arch['quantity'],
                        $arch['available'],
                        $arch['copy_serials'],
                        $arch['description'],
                        $arch['cover_image'],
                        $arch['original_created_at'] ?: date('Y-m-d H:i:s')
                    ]);
                    $restoredBid = (int)$pdo->lastInsertId();
                }

                // Kembalikan riwayat loans jika ada
                if (!empty($arch['backup_data'])) {
                    $bData = json_decode($arch['backup_data'], true);
                    if (is_array($bData) && !empty($bData['loans'])) {
                        foreach ($bData['loans'] as $l) {
                            try {
                                $pdo->prepare("INSERT INTO loans (book_id, member_id, quantity, copy_serial, request_date, loan_date, due_date, return_date, status, notes) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
                                    ->execute([$restoredBid, $l['member_id'], $l['quantity'] ?? 1, $l['copy_serial'] ?? null, $l['request_date'], $l['loan_date'], $l['due_date'], $l['return_date'], $l['status'], $l['notes'] ?? '']);
                            } catch (Throwable $e) {}
                        }
                    }
                }

                $pdo->prepare("DELETE FROM archived_books WHERE id = ?")->execute([$aid]);
                flash('Buku "' . $arch['title'] . '" berhasil dibalikkan (dipulihkan) ke Daftar Koleksi Buku.');
            }
            header('Location: ' . u('index.php?page=admin_books&open_archive=1'));
            exit;
        }

        // PULIHKAN / BALIKKAN SEMUA DATA BUKU DARI ARSIP
        if ($action === 'restore_all_books') {
            $allArch = $pdo->query("SELECT * FROM archived_books ORDER BY id ASC")->fetchAll();
            $restoredCount = 0;

            foreach ($allArch as $arch) {
                $targetCode = $arch['code'];
                $chkC = $pdo->prepare("SELECT id FROM books WHERE code = ? LIMIT 1");
                $chkC->execute([$targetCode]);
                if ($chkC->fetch()) {
                    $targetCode = $arch['code'] . '-KEMBALI-' . rand(10, 99);
                }

                $chkId = $pdo->prepare("SELECT id FROM books WHERE id = ? LIMIT 1");
                $chkId->execute([$arch['original_id']]);
                $origFree = !$chkId->fetch();

                if ($origFree) {
                    $ins = $pdo->prepare("INSERT INTO books (id, code, title, author, publisher, year_published, category, source, price, tanggal_penerimaan, tahun_penerimaan, quantity, available, copy_serials, description, cover_image, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
                    $ins->execute([
                        $arch['original_id'],
                        $targetCode,
                        $arch['title'],
                        $arch['author'],
                        $arch['publisher'],
                        $arch['year_published'],
                        $arch['category'],
                        $arch['source'],
                        $arch['price'],
                        $arch['tanggal_penerimaan'],
                        $arch['tahun_penerimaan'],
                        $arch['quantity'],
                        $arch['available'],
                        $arch['copy_serials'],
                        $arch['description'],
                        $arch['cover_image'],
                        $arch['original_created_at'] ?: date('Y-m-d H:i:s')
                    ]);
                    $restoredBid = $arch['original_id'];
                } else {
                    $ins = $pdo->prepare("INSERT INTO books (code, title, author, publisher, year_published, category, source, price, tanggal_penerimaan, tahun_penerimaan, quantity, available, copy_serials, description, cover_image, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
                    $ins->execute([
                        $targetCode,
                        $arch['title'],
                        $arch['author'],
                        $arch['publisher'],
                        $arch['year_published'],
                        $arch['category'],
                        $arch['source'],
                        $arch['price'],
                        $arch['tanggal_penerimaan'],
                        $arch['tahun_penerimaan'],
                        $arch['quantity'],
                        $arch['available'],
                        $arch['copy_serials'],
                        $arch['description'],
                        $arch['cover_image'],
                        $arch['original_created_at'] ?: date('Y-m-d H:i:s')
                    ]);
                    $restoredBid = (int)$pdo->lastInsertId();
                }

                if (!empty($arch['backup_data'])) {
                    $bData = json_decode($arch['backup_data'], true);
                    if (is_array($bData) && !empty($bData['loans'])) {
                        foreach ($bData['loans'] as $l) {
                            try {
                                $pdo->prepare("INSERT INTO loans (book_id, member_id, quantity, copy_serial, request_date, loan_date, due_date, return_date, status, notes) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
                                    ->execute([$restoredBid, $l['member_id'], $l['quantity'] ?? 1, $l['copy_serial'] ?? null, $l['request_date'], $l['loan_date'], $l['due_date'], $l['return_date'], $l['status'], $l['notes'] ?? '']);
                            } catch (Throwable $e) {}
                        }
                    }
                }

                $pdo->prepare("DELETE FROM archived_books WHERE id = ?")->execute([$arch['id']]);
                $restoredCount++;
