        // HAPUS PERMANEN DARI ARSIP BUKU
        if ($action === 'permanent_delete_book') {
            $aid = (int)($_POST['archive_id'] ?? 0);
            $s = $pdo->prepare("SELECT cover_image FROM archived_books WHERE id = ? LIMIT 1");
            $s->execute([$aid]);
            $cov = $s->fetchColumn();
            if ($cov && strpos($cov, 'book_') === 0 && file_exists(__DIR__ . '/uploads/' . $cov)) {
                @unlink(__DIR__ . '/uploads/' . $cov);
            }
            $pdo->prepare("DELETE FROM archived_books WHERE id = ?")->execute([$aid]);
            flash('Buku berhasil dihapus permanen dari arsip.');
            header('Location: ' . u('index.php?page=admin_books&open_archive=1'));
            exit;
        }

        // KOSONGKAN ARSIP BUKU
        if ($action === 'empty_book_archive') {
            $all = $pdo->query("SELECT cover_image FROM archived_books")->fetchAll(PDO::FETCH_COLUMN);
            foreach ($all as $cov) {
                if ($cov && strpos($cov, 'book_') === 0 && file_exists(__DIR__ . '/uploads/' . $cov)) {
                    @unlink(__DIR__ . '/uploads/' . $cov);
                }
            }
            $pdo->exec("DELETE FROM archived_books");
            flash('Seluruh arsip koleksi buku berhasil dikosongkan secara permanen.');
            header('Location: ' . u('index.php?page=admin_books'));
            exit;
        }

        // 4. UPDATE BUKU
        if ($action === 'update_book') {
            $bookId = (int)($_POST['book_id'] ?? 0);
            $bStmt = $pdo->prepare("SELECT * FROM books WHERE id = ? LIMIT 1");
            $bStmt->execute([$bookId]);
            $currBook = $bStmt->fetch();

            if (!$currBook) {
                flash('Buku tidak ditemukan.', 'error');
            } else {
                $code = trim($_POST['code'] ?? '');
                $title = trim($_POST['title'] ?? '');
                $author = trim($_POST['author'] ?? '');
                $publisher = trim($_POST['publisher'] ?? '');
                $year = (int)($_POST['year'] ?? 0) ?: null;
                $category = trim($_POST['category'] ?? '');
                $callNumber = trim($_POST['call_number'] ?? '');
                $newCategory = trim($_POST['new_category'] ?? '');
                $newCatCallNumber = trim($_POST['new_cat_call_number'] ?? '');

                if ($category === '__NEW__' || $category === '') {
                    $category = $newCategory !== '' ? $newCategory : 'Umum';
                    if ($newCatCallNumber !== '') {
                        $callNumber = $newCatCallNumber;
                    }
                }
                if ($category !== '') {
                    $pdo->prepare("INSERT INTO categories (call_number, name) VALUES (?, ?) ON DUPLICATE KEY UPDATE call_number = COALESCE(VALUES(call_number), call_number)")->execute([$callNumber ?: null, $category]);
                }

                // Sumber Buku & Harga
                $sourceType = trim($_POST['source_type'] ?? 'Dana BOS');
                $customSource = trim($_POST['custom_source'] ?? '');
                $source = ($sourceType === '__CUSTOM__' || $sourceType === '') ? ($customSource !== '' ? $customSource : 'Dana BOS') : $sourceType;
                if ($source !== '') {
                    $pdo->prepare("INSERT IGNORE INTO procurement_sources (name) VALUES (?)")->execute([$source]);
                }

                $rawPrice = trim($_POST['price'] ?? '');
                $cleanPrice = preg_replace('/[^0-9]/', '', $rawPrice);
                $price = ($cleanPrice !== '') ? (int)$cleanPrice : null;

                $qty = max(1, (int)($_POST['quantity'] ?? 1));
                $desc = trim($_POST['description'] ?? '');

                if ($code === '' || $title === '') {
                    flash('Kode dan Judul Buku wajib diisi.', 'error');
                } else {
                    // Check duplicate code on other books
                    $dupStmt = $pdo->prepare("SELECT id FROM books WHERE code = ? AND id != ? LIMIT 1");
                    $dupStmt->execute([$code, $bookId]);
                    if ($dupStmt->fetch()) {
                        flash('Kode buku "' . e($code) . '" sudah digunakan oleh buku lain.', 'error');
                    } else {
                        // Cek peminjaman aktif untuk buku ini di loans
                        $chkLoans = $pdo->prepare("SELECT copy_serial, quantity FROM loans WHERE book_id = ? AND status = 'borrowed'");
                        $chkLoans->execute([$bookId]);
                        $activeLoans = $chkLoans->fetchAll();

                        $activeBorrowedQty = 0;
                        $borrowedSerials = [];
                        foreach ($activeLoans as $al) {
                            $activeBorrowedQty += max(1, (int)$al['quantity']);
                            if (!empty($al['copy_serial'])) {
                                foreach (explode(',', (string)$al['copy_serial']) as $sc) {
                                    $sc = trim($sc);
                                    if ($sc !== '' && !in_array($sc, $borrowedSerials, true)) {
                                        $borrowedSerials[] = $sc;
                                    }
                                }
                            }
                        }

                        // Cek juga dari book_copies jika ada status borrowed
                        $chkCopiesStmt = $pdo->prepare("SELECT copy_code, status FROM book_copies WHERE book_id = ?");
                        $chkCopiesStmt->execute([$bookId]);
                        $existingCopies = $chkCopiesStmt->fetchAll();

                        $existingCopyStatus = [];
                        foreach ($existingCopies as $ec) {
                            $existingCopyStatus[$ec['copy_code']] = $ec['status'];
                            if ($ec['status'] === 'borrowed' && !in_array($ec['copy_code'], $borrowedSerials, true)) {
                                $borrowedSerials[] = $ec['copy_code'];
                            }
                        }

                        // Validasi stok minimum: tidak boleh lebih kecil dari eksemplar yang sedang dipinjam
                        if ($qty < $activeBorrowedQty) {
                            flash('Jumlah stok total buku (' . $qty . ' eksemplar) tidak boleh lebih kecil dari jumlah buku yang sedang dipinjam (' . $activeBorrowedQty . ' eksemplar).', 'error');
                            header('Location: ' . u('index.php?page=admin_books'));
                            exit;
                        }

                        $tanggalPenerimaan = trim($_POST['tanggal_penerimaan'] ?? '');
                        if ($tanggalPenerimaan === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $tanggalPenerimaan)) {
                            $tanggalPenerimaan = !empty($currBook['tanggal_penerimaan']) ? $currBook['tanggal_penerimaan'] : date('Y-m-d', strtotime($currBook['created_at']));
                        }
                        $tahunPenerimaan = (int)date('Y', strtotime($tanggalPenerimaan));

                        // Cover photo upload & removal handling
                        $coverImage = $currBook['cover_image'] ?? null;
                        if (!empty($_POST['remove_cover'])) {
                            if (!empty($currBook['cover_image']) && strpos($currBook['cover_image'], 'book_') === 0 && file_exists(__DIR__ . '/uploads/' . $currBook['cover_image'])) {
                                @unlink(__DIR__ . '/uploads/' . $currBook['cover_image']);
                            }
                            $coverImage = null;
                        } elseif (!empty($_FILES['cover_image']['name']) && $_FILES['cover_image']['error'] === UPLOAD_ERR_OK) {
                            $uploadedCover = handle_book_cover_upload('cover_image', $currBook['cover_image']);
                            if ($uploadedCover) {
                                $coverImage = $uploadedCover;
                            }
                        }

                        // Serial numbers of copies (optional)
                        $rawSerials = trim($_POST['copy_serials'] ?? '');
                        $serialsList = [];
                        if ($rawSerials !== '') {
                            $decoded = json_decode($rawSerials, true);
                            if (is_array($decoded)) {
                                foreach ($decoded as $s) {
                                    $s = trim((string)$s);
                                    if ($s !== '') $serialsList[] = $s;
                                }
                            }
                        }
                        // Otomatis buat nomor seri sesuai kode & quantity jika belum ada nomor seri terdata
                        if (empty($serialsList) && !empty($code) && $qty > 0) {
                            for ($i = 1; $i <= $qty; $i++) {
                                $serialsList[] = $code . '-' . str_pad($i, 2, '0', STR_PAD_LEFT);
                            }
                        }
                        $cleanSerials = array_values(array_unique($serialsList));
                        $serialsJson = !empty($cleanSerials) ? json_encode($cleanSerials, JSON_UNESCAPED_UNICODE) : null;

                        // Validasi nomor seri: eksemplar yang sedang dipinjam TIDAK BOLEH dihilangkan atau diubah
                        if (!empty($borrowedSerials)) {
                            $missingBorrowed = array_diff($borrowedSerials, $cleanSerials);
                            if (!empty($missingBorrowed)) {
                                flash('Perubahan nomor seri ditolak: Eksemplar berikut sedang berstatus dipinjam (' . implode(', ', $missingBorrowed) . '). Selesaikan peminjaman terlebih dahulu sebelum menghapus nomor seri tersebut.', 'error');
                                header('Location: ' . u('index.php?page=admin_books'));
                                exit;
                            }
                        }

                        // Hitung stok available yang sinkron dan konsisten: total qty dikurangi yang sedang dipinjam
                        $newAvail = max(0, $qty - $activeBorrowedQty);

                        // Gunakan transaksi untuk menjamin konsistensi books dan book_copies
                        try {
                            if (!$pdo->inTransaction()) {
                                $pdo->beginTransaction();
                            }

                            $upd = $pdo->prepare("UPDATE books SET code=?, title=?, author=?, publisher=?, year_published=?, category=?, call_number=?, source=?, price=?, quantity=?, copy_serials=?, available=?, description=?, tanggal_penerimaan=?, tahun_penerimaan=?, cover_image=? WHERE id=?");
                            $upd->execute([$code, $title, $author, $publisher, $year, $category, $callNumber ?: null, $source, $price, $qty, $serialsJson, $newAvail, $desc, $tanggalPenerimaan, $tahunPenerimaan, $coverImage, $bookId]);

                            $pdo->prepare("UPDATE books SET sumber_pengadaan=? WHERE id=?")->execute([$source, $bookId]);

                            if (!empty($cleanSerials)) {
                                // 1. Hapus eksemplar yang tidak lagi ada di daftar serial baru HANYA jika TIDAK sedang dipinjam
                                $placeholders = implode(',', array_fill(0, count($cleanSerials), '?'));
                                $delStmt = $pdo->prepare("DELETE FROM book_copies WHERE book_id = ? AND copy_code NOT IN ($placeholders) AND status != 'borrowed'");
                                $delParams = array_merge([$bookId], $cleanSerials);
                                $delStmt->execute($delParams);

                                // 2. Insert atau pertahankan status eksemplar yang sudah ada
                                $insCopy = $pdo->prepare("INSERT INTO book_copies (book_id, copy_code, status) VALUES (?, ?, 'available')");
                                foreach ($cleanSerials as $cCode) {
                                    if (!isset($existingCopyStatus[$cCode])) {
                                        // Eksemplar baru
                                        $insCopy->execute([$bookId, $cCode]);
                                    }
                                    // Eksemplar yang sudah ada TETAP mempertahankan statusnya (borrowed, lost, damaged, atau available)
                                }
                            } else {
                                // Jika daftar serial dikosongkan, hanya hapus eksemplar yang TIDAK sedang dipinjam
                                $pdo->prepare("DELETE FROM book_copies WHERE book_id = ? AND status != 'borrowed'")->execute([$bookId]);
                            }

                            $pdo->commit();
                            flash('Data buku "' . $title . '" berhasil diperbarui.');
                        } catch (Throwable $e) {
                            if ($pdo->inTransaction()) {
                                $pdo->rollBack();
                            }
                            flash('Gagal memperbarui buku: ' . $e->getMessage(), 'error');
                        }
                    }
                }
            }
            header('Location: ' . u('index.php?page=admin_books'));
            exit;
        }

        // 5. TAMBAH BUKU BARU
        $code = trim($_POST['code'] ?? '');
        $title = trim($_POST['title'] ?? '');
        $author = trim($_POST['author'] ?? '');
        $publisher = trim($_POST['publisher'] ?? '');
        $year = (int)($_POST['year'] ?? 0) ?: null;
        $category = trim($_POST['category'] ?? '');
        $callNumber = trim($_POST['call_number'] ?? '');
        $newCategory = trim($_POST['new_category'] ?? '');
        $newCatCallNumber = trim($_POST['new_cat_call_number'] ?? '');

        // If admin typed new category in book form
        if ($category === '__NEW__' || $category === '') {
            $category = $newCategory !== '' ? $newCategory : 'Umum';
            if ($newCatCallNumber !== '') {
                $callNumber = $newCatCallNumber;
            }
        }

        // Save new category to categories table
        if ($category !== '') {
            $pdo->prepare("INSERT INTO categories (call_number, name) VALUES (?, ?) ON DUPLICATE KEY UPDATE call_number = COALESCE(VALUES(call_number), call_number)")->execute([$callNumber ?: null, $category]);
        }

        // Sumber Buku & Harga
        $sourceType = trim($_POST['source_type'] ?? 'Dana BOS');
        $customSource = trim($_POST['custom_source'] ?? '');
        $source = ($sourceType === '__CUSTOM__' || $sourceType === '') ? ($customSource !== '' ? $customSource : 'Dana BOS') : $sourceType;
        if ($source !== '') {
            $pdo->prepare("INSERT IGNORE INTO procurement_sources (name) VALUES (?)")->execute([$source]);
        }

        $rawPrice = trim($_POST['price'] ?? '');
        $cleanPrice = preg_replace('/[^0-9]/', '', $rawPrice);
        $price = ($cleanPrice !== '') ? (int)$cleanPrice : null;

        $qty = max(1, (int)($_POST['quantity'] ?? 1));
        $desc = trim($_POST['description'] ?? '');

        $tanggalPenerimaan = trim($_POST['tanggal_penerimaan'] ?? '');
        if ($tanggalPenerimaan === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $tanggalPenerimaan)) {
            $tanggalPenerimaan = date('Y-m-d');
        }
        $tahunPenerimaan = (int)date('Y', strtotime($tanggalPenerimaan));

        if ($code === '' || $title === '') {
            flash('Kode dan Judul Buku wajib diisi.', 'error');
        } else {
            $coverImage = null;
            if (!empty($_FILES['cover_image']['name']) && $_FILES['cover_image']['error'] === UPLOAD_ERR_OK) {
                $uploadedCover = handle_book_cover_upload('cover_image');
                if ($uploadedCover) {
                    $coverImage = $uploadedCover;
                }
            }

            // Serial numbers of copies (optional)
            $rawSerials = trim($_POST['copy_serials'] ?? '');
            $serialsList = [];
            if ($rawSerials !== '') {
                $decoded = json_decode($rawSerials, true);
                if (is_array($decoded)) {
                    foreach ($decoded as $s) {
                        $s = trim((string)$s);
                        if ($s !== '') $serialsList[] = $s;
                    }
                }
            }
            // Otomatis buat nomor seri sesuai kode & quantity jika belum ada nomor seri terdata
            if (empty($serialsList) && !empty($code) && $qty > 0) {
                for ($i = 1; $i <= $qty; $i++) {
                    $serialsList[] = $code . '-' . str_pad($i, 2, '0', STR_PAD_LEFT);
                }
            }
            $serialsJson = !empty($serialsList) ? json_encode(array_values(array_unique($serialsList)), JSON_UNESCAPED_UNICODE) : null;

            $ins = $pdo->prepare("INSERT INTO books (code, title, author, publisher, year_published, category, call_number, source, price, quantity, copy_serials, available, description, tanggal_penerimaan, tahun_penerimaan, cover_image) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
            $ins->execute([$code, $title, $author, $publisher, $year, $category, $callNumber ?: null, $source, $price, $qty, $serialsJson, $qty, $desc, $tanggalPenerimaan, $tahunPenerimaan, $coverImage]);
            $newBId = $pdo->lastInsertId();
            try {
                $pdo->prepare("UPDATE books SET sumber_pengadaan=? WHERE id=?")->execute([$source, $newBId]);
                if (!empty($serialsList) && $newBId) {
                    $insCopy = $pdo->prepare("INSERT INTO book_copies (book_id, copy_code, status) VALUES (?, ?, 'available')");
                    foreach (array_unique($serialsList) as $cCode) {
                        $insCopy->execute([$newBId, $cCode]);
                    }
                }
            } catch (Throwable $e) {}

            flash('Buku baru "' . $title . '" berhasil ditambahkan.');
        }
        header('Location: ' . u('index.php?page=admin_books'));
        exit;
    }

    // Check if in edit mode
    $editBook = null;
    if (isset($_GET['edit'])) {
        $editId = (int)$_GET['edit'];
        $eStmt = $pdo->prepare("SELECT * FROM books WHERE id = ? LIMIT 1");
        $eStmt->execute([$editId]);
        $editBook = $eStmt->fetch();
    }

    // Search & Filter Parameters for Admin Books
    $q = trim($_GET['q'] ?? '');
    $catFilter = trim($_GET['category'] ?? '');
    $sourceFilter = trim($_GET['source'] ?? '');

    $where = ["1=1"];
    $params = [];

    if ($q !== '') {
        $where[] = "(title LIKE ? OR code LIKE ? OR author LIKE ? OR publisher LIKE ? OR copy_serials LIKE ?)";
        $term = "%{$q}%";
        $params[] = $term;
        $params[] = $term;
        $params[] = $term;
        $params[] = $term;
        $params[] = $term;
    }

    if ($catFilter !== '' && $catFilter !== 'all') {
        $where[] = "category = ?";
        $params[] = $catFilter;
    }

    if ($sourceFilter !== '' && $sourceFilter !== 'all') {
        $where[] = "source = ?";
        $params[] = $sourceFilter;
    }

    // Fetch Categories & Sources with Book Count
    $categories = $pdo->query("SELECT c.*, (SELECT COUNT(*) FROM books b WHERE b.category = c.name) as book_count FROM categories c ORDER BY c.call_number ASC, c.name ASC")->fetchAll();
    $procurementSources = $pdo->query("SELECT s.*, (SELECT COUNT(*) FROM books b WHERE b.source = s.name) as book_count FROM procurement_sources s ORDER BY s.name ASC")->fetchAll();
    $distinctSources = array_column($procurementSources, 'name');
    // Live Statistics for Books Page (Otomatis ter-update saat buku ditambah/diedit/dipinjam)
    $statTotalTitles = (int)$pdo->query("SELECT COUNT(*) FROM books")->fetchColumn();
    $statTotalBooks  = (int)$pdo->query("SELECT COALESCE(SUM(quantity), 0) FROM books")->fetchColumn();
    $statBorrowed    = (int)$pdo->query("SELECT COALESCE(SUM(quantity), 0) FROM loans WHERE status = 'borrowed'")->fetchColumn();
    $statOverdue     = (int)$pdo->query("SELECT COUNT(*) FROM loans WHERE status = 'borrowed' AND due_date < CURDATE()")->fetchColumn();

    // Pagination for Admin Books (10 baris per halaman)
    $perPage = 10;
    $countSql = "SELECT COUNT(*) FROM books WHERE " . implode(" AND ", $where);
    $stmtCount = $pdo->prepare($countSql);
    $stmtCount->execute($params);
    $totalBooksCount = (int)$stmtCount->fetchColumn();
    $totalPages = max(1, (int)ceil($totalBooksCount / $perPage));

    $pageNumber = max(1, (int)($_GET['p'] ?? 1));
    if ($pageNumber > $totalPages) $pageNumber = $totalPages;
    $offset = ($pageNumber - 1) * $perPage;

    // Sinkronisasi otomatis stok tersedia dengan status peminjaman riil di tabel loans
    try {
        $pdo->exec("UPDATE books SET available = GREATEST(0, quantity - (
            SELECT COALESCE(SUM(quantity), 0) FROM loans WHERE book_id = books.id AND status IN ('borrowed', 'approved', 'pending')
        ))");
    } catch (Throwable $eSyncBooks) {}

    $sqlBooks = "SELECT b.*, (SELECT COALESCE(SUM(l.quantity), 0) FROM loans l WHERE l.book_id = b.id AND l.status IN ('borrowed', 'approved', 'pending')) as active_loans_count FROM books b WHERE " . implode(" AND ", $where) . " ORDER BY b.id DESC LIMIT {$perPage} OFFSET {$offset}";
    $stmtBooks = $pdo->prepare($sqlBooks);
    $stmtBooks->execute($params);
    $books = $stmtBooks->fetchAll();
    $archivedBooksCount = (int)$pdo->query("SELECT COUNT(*) FROM archived_books")->fetchColumn();
    $archivedBooks = [];
    if (isset($_GET['open_archive']) || isset($_GET['view_archive']) || $archivedBooksCount > 0) {
        $archivedBooks = $pdo->query("SELECT * FROM archived_books ORDER BY deleted_at DESC LIMIT 50")->fetchAll();
    }

    render_app_layout('admin', 'books', 'Data Buku', function() use ($books, $categories, $procurementSources, $distinctSources, $editBook, $q, $catFilter, $sourceFilter, $statTotalTitles, $statTotalBooks, $statBorrowed, $statOverdue, $pageNumber, $totalPages, $totalBooksCount, $perPage, $offset, $archivedBooks, $archivedBooksCount) {
