        </div>

        <!-- Load HTML5 QR Code & Barcode Scanner Library -->
        <script src="<?=u('assets/js/html5-qrcode.min.js')?>"></script>
        <script>
        // Stock Scanner & Serial Numbers Controller
        let stockScannerInstance = null;
        let isStockScannerActive = false;
        let availableStockCameras = [];
        let selectedStockCameraId = null;
        let currentScannedSerials = [];
        let lastScannedText = '';
        let lastScannedTime = 0;

        function playStockScanBeep(isSuccess = true) {
            try {
                const AudioCtx = window.AudioContext || window.webkitAudioContext;
                if (!AudioCtx) return;
                const ctx = new AudioCtx();
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                const now = ctx.currentTime;
                if (isSuccess) {
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(1046.5, now);
                    osc.frequency.setValueAtTime(1567.98, now + 0.08);
                    gain.gain.setValueAtTime(0.35, now);
                    gain.gain.exponentialRampToValueAtTime(0.01, now + 0.22);
                    osc.start(now);
                    osc.stop(now + 0.22);
                } else {
                    osc.type = 'sawtooth';
                    osc.frequency.setValueAtTime(300, now);
                    gain.gain.setValueAtTime(0.3, now);
                    gain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);
                    osc.start(now);
                    osc.stop(now + 0.2);
                }
            } catch(e) {}
        }

        function openStockScannerModal() {
            const titleVal = document.getElementById('book_title_input') ? document.getElementById('book_title_input').value.trim() : '';
            const codeVal = document.getElementById('book_code_input') ? document.getElementById('book_code_input').value.trim() : '';
            
            document.getElementById('scanner_modal_book_title').textContent = titleVal || '(Judul belum diisi)';
            document.getElementById('scanner_modal_book_code').textContent = codeVal || '(Belum ada kode)';

            const hiddenInput = document.getElementById('hidden_copy_serials');
            try {
                currentScannedSerials = hiddenInput && hiddenInput.value ? JSON.parse(hiddenInput.value) : [];
                if (!Array.isArray(currentScannedSerials)) currentScannedSerials = [];
            } catch(e) {
                currentScannedSerials = [];
            }

            renderScannedSerialsList();
            document.getElementById('modal_stock_scanner').style.display = 'flex';

            setTimeout(() => {
                const manInp = document.getElementById('manual_serial_input');
                if (manInp) manInp.focus();
            }, 200);

            initStockCameraScanner();
        }

        function closeStockScannerModal() {
            stopStockCameraScanner();
            document.getElementById('modal_stock_scanner').style.display = 'none';
        }

        function renderScannedSerialsList() {
            const container = document.getElementById('scanned_serials_list_container');
            const badge = document.getElementById('modal_total_copies_badge');
            
            badge.textContent = currentScannedSerials.length + ' Eksemplar';

            if (currentScannedSerials.length === 0) {
                container.innerHTML = `
                    <div style="padding:30px 16px;text-align:center;color:#94a3b8;font-size:12px;border:1.5px dashed #cbd5e1;border-radius:8px;background:#ffffff;">
                        <div style="font-size:24px;margin-bottom:6px;">🏷️</div>
                        <b>Belum ada nomor seri eksemplar terdata.</b><br>
                        Arahkan kode batang atau QR buku ke kamera, atau gunakan barcode scanner USB.
                    </div>
                `;
                return;
            }

            let html = '';
            currentScannedSerials.forEach((sn, idx) => {
                html += `
                    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;background:#ffffff;padding:7px 10px;border-radius:8px;border:1px solid #cbd5e1;font-size:12px;box-shadow:0 1px 2px rgba(0,0,0,0.02);">
                        <div style="display:flex;align-items:center;gap:8px;min-width:0;overflow:hidden;">
                            <span style="background:#e0f2fe;color:#0369a1;font-size:10px;font-weight:800;padding:2px 6px;border-radius:4px;flex-shrink:0;">
                                #${idx + 1}
                            </span>
                            <span style="font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;font-weight:700;color:var(--navy);word-break:break-all;">
                                ${escapeHtml(sn)}
                            </span>
                        </div>
                        <button type="button" onclick="removeScannedSerial(${idx})" style="background:#fee2e2;border:1px solid #fecaca;color:#ef4444;border-radius:4px;width:24px;height:24px;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;font-size:13px;line-height:1;" title="Hapus nomor seri ini">
                            &times;
                        </button>
                    </div>
                `;
            });
            container.innerHTML = html;
        }

        function addScannedSerial(code) {
            if (!code) return;
            const cleanCode = code.trim();
            if (!cleanCode) return;

            if (currentScannedSerials.includes(cleanCode)) {
                playStockScanBeep(false);
                showStockScanFeedback('⚠️ Nomor seri "' + cleanCode + '" sudah terdaftar sebelumnya!', 'warning');
                return;
            }

            currentScannedSerials.push(cleanCode);
            playStockScanBeep(true);
            showStockScanFeedback('✅ Berhasil di-scan: ' + cleanCode + ' (Total: ' + currentScannedSerials.length + ')', 'success');
            renderScannedSerialsList();

            const container = document.getElementById('scanned_serials_list_container');
            if (container) container.scrollTop = container.scrollHeight;
        }

        function removeScannedSerial(index) {
            if (index >= 0 && index < currentScannedSerials.length) {
                const removed = currentScannedSerials.splice(index, 1);
                showStockScanFeedback('🗑️ Dihapus: ' + removed[0], 'info');
                renderScannedSerialsList();
            }
        }

        function clearAllScannedSerials() {
            if (currentScannedSerials.length === 0) return;
            if (confirm('Kosongkan semua (' + currentScannedSerials.length + ') nomor seri eksemplar ter-scan?')) {
                currentScannedSerials = [];
                renderScannedSerialsList();
                showStockScanFeedback('Daftar nomor seri telah dikosongkan.', 'info');
            }
        }

        function generateAutoSerialSequence() {
            const codeVal = document.getElementById('book_code_input') ? document.getElementById('book_code_input').value.trim() : '';
            const qtyInput = document.getElementById('book_quantity_input');
            const targetQty = Math.max(1, parseInt(qtyInput ? qtyInput.value : 5) || 5);
            const prefix = codeVal ? codeVal : 'BK';

            if (currentScannedSerials.length > 0 && !confirm('Sudah ada ' + currentScannedSerials.length + ' nomor seri. Tambahkan nomor seri urut otomatis hingga ' + targetQty + ' eksemplar?')) {
                return;
            }

            let addedCount = 0;
            for (let i = 1; i <= targetQty; i++) {
                const sn = prefix + '-' + String(i).padStart(2, '0');
                if (!currentScannedSerials.includes(sn)) {
                    currentScannedSerials.push(sn);
                    addedCount++;
                }
            }
            renderScannedSerialsList();
            playStockScanBeep(true);
            showStockScanFeedback('✅ Berhasil membuat ' + addedCount + ' nomor seri urut (' + prefix + '-01 s.d. ' + prefix + '-' + String(targetQty).padStart(2, '0') + ')', 'success');
        }

        function applyStockScannerToForm() {
            const hiddenInput = document.getElementById('hidden_copy_serials');
            if (hiddenInput) {
                hiddenInput.value = JSON.stringify(currentScannedSerials);
            }

            const autoSync = document.getElementById('chk_auto_sync_stock');
            const qtyInput = document.getElementById('book_quantity_input');
            if (autoSync && autoSync.checked && currentScannedSerials.length > 0 && qtyInput) {
                qtyInput.value = currentScannedSerials.length;
            }

            const badgeWrap = document.getElementById('stock_scanned_badge_wrap');
            const badgeCount = document.getElementById('scanned_serials_badge_count');
            if (badgeWrap && badgeCount) {
                if (currentScannedSerials.length > 0) {
                    badgeWrap.style.display = 'block';
                    badgeCount.textContent = currentScannedSerials.length;
                } else {
                    badgeWrap.style.display = 'none';
                }
            }

            closeStockScannerModal();
        }

        function handleManualSerialKeyDown(e) {
            if (e.key === 'Enter') {
                e.preventDefault();
                addManualSerialFromInput();
            }
        }

        function addManualSerialFromInput() {
            const input = document.getElementById('manual_serial_input');
            if (!input) return;
            const val = input.value.trim();
            if (val) {
                addScannedSerial(val);
                input.value = '';
                input.focus();
            }
        }

        function handleManualQuantityInput(val) {
            // Optional: User can freely type manual quantity without breaking serials
        }

        function showStockScanFeedback(msg, type) {
            const el = document.getElementById('stock_scan_feedback');
            if (!el) return;
            el.style.display = 'block';
            if (type === 'success') {
                el.style.background = '#dcfce7';
                el.style.color = '#15803d';
                el.style.border = '1px solid #86efac';
            } else if (type === 'warning') {
                el.style.background = '#fef3c7';
                el.style.color = '#b45309';
                el.style.border = '1px solid #fcd34d';
            } else {
                el.style.background = '#f1f5f9';
                el.style.color = '#334155';
                el.style.border = '1px solid #cbd5e1';
            }
            el.textContent = msg;
            setTimeout(() => {
                if (el.textContent === msg) el.style.display = 'none';
            }, 3500);
        }

        async function initStockCameraScanner() {
            if (typeof Html5Qrcode === 'undefined') return;
            try {
                if (availableStockCameras.length === 0) {
                    const devices = await Html5Qrcode.getCameras();
                    if (devices && devices.length > 0) {
                        availableStockCameras = devices;
                        const sel = document.getElementById('stockScannerCamSelect');
                        sel.innerHTML = '';
                        devices.forEach((cam, idx) => {
                            const opt = document.createElement('option');
                            opt.value = cam.id;
                            opt.text = cam.label || ('Kamera ' + (idx + 1));
                            sel.appendChild(opt);
                        });
                        selectedStockCameraId = devices[0].id;
                    }
                }
                startStockCameraScanner();
            } catch(err) {
                console.warn('Could not enumerate cameras:', err);
            }
        }

        async function startStockCameraScanner() {
            if (isStockScannerActive || typeof Html5Qrcode === 'undefined') return;
            const placeholder = document.getElementById('stockScannerPlaceholder');
            const reticle = document.getElementById('stockScannerReticle');
            const statusBadge = document.getElementById('stockScannerStatusBadge');
            const btnToggle = document.getElementById('btnToggleStockCam');

            try {
                if (!stockScannerInstance) {
                    stockScannerInstance = new Html5Qrcode("stockScannerLiveView");
                }
                statusBadge.textContent = 'Menghubungkan...';
                statusBadge.style.background = '#fef08a';
                statusBadge.style.color = '#854d0e';

                const camConfig = selectedStockCameraId ? { deviceId: { exact: selectedStockCameraId } } : { facingMode: "environment" };

                await stockScannerInstance.start(
                    camConfig,
                    {
                        fps: 20,
                        qrbox: function(w, h) {
                            return { width: Math.min(w - 20, 260), height: Math.min(h - 20, 180) };
                        },
                        aspectRatio: 1.333333,
                        videoConstraints: {
                            facingMode: "environment",
                            width: { min: 640, ideal: 1280 },
                            height: { min: 480, ideal: 720 }
                        },
                        experimentalFeatures: {
                            useBarCodeDetectorIfSupported: true
                        }
                    },
                    onStockQrSuccess,
                    onStockQrError
                );

                isStockScannerActive = true;
                if (placeholder) placeholder.style.display = 'none';
                if (reticle) reticle.style.display = 'block';
                statusBadge.textContent = 'Kamera Aktif (Siap Scan)';
                statusBadge.style.background = '#dcfce7';
                statusBadge.style.color = '#15803d';
                btnToggle.textContent = '⏹ Matikan Kamera';
                btnToggle.className = 'btn btn-outline-danger btn-sm';
            } catch(err) {
                console.error('Camera start error:', err);
                if (placeholder) placeholder.style.display = 'flex';
                if (reticle) reticle.style.display = 'none';
                statusBadge.textContent = 'Kamera Gagal';
                statusBadge.style.background = '#fee2e2';
                statusBadge.style.color = '#b91c1c';
            }
        }

        async function stopStockCameraScanner() {
            if (!isStockScannerActive || !stockScannerInstance) return;
            try {
                await stockScannerInstance.stop();
            } catch(e) {}
            isStockScannerActive = false;
            const placeholder = document.getElementById('stockScannerPlaceholder');
            const reticle = document.getElementById('stockScannerReticle');
            const statusBadge = document.getElementById('stockScannerStatusBadge');
            const btnToggle = document.getElementById('btnToggleStockCam');

            if (placeholder) placeholder.style.display = 'flex';
            if (reticle) reticle.style.display = 'none';
            if (statusBadge) {
                statusBadge.textContent = 'Kamera Mati';
                statusBadge.style.background = '#e2e8f0';
                statusBadge.style.color = '#475569';
            }
            if (btnToggle) {
                btnToggle.textContent = '📷 Buka Kamera';
                btnToggle.className = 'btn btn-outline-success btn-sm';
            }
        }

        function toggleStockCameraScanner() {
            if (isStockScannerActive) {
                stopStockCameraScanner();
            } else {
                startStockCameraScanner();
            }
        }

        function onStockScannerCamChange(newId) {
            selectedStockCameraId = newId;
            if (isStockScannerActive) {
                stopStockCameraScanner().then(() => {
                    startStockCameraScanner();
                });
            }
        }

        function onStockQrSuccess(decodedText) {
            const now = Date.now();
            if (decodedText === lastScannedText && (now - lastScannedTime) < 2000) {
                return;
            }
            lastScannedText = decodedText;
            lastScannedTime = now;
            addScannedSerial(decodedText);
        }

        function onStockQrError(err) {
            // Ignore per-frame decode errors
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }
        </script>


        <script>
        let prevCatVal = '';
        let prevSrcVal = '';

        const ddcMappingList = [
            { range: '000-099', min: 0,   max: 99,  names: ['Karya Umum', 'Umum'] },
            { range: '100-199', min: 100, max: 199, names: ['Filsafat dan Psikologi', 'Filsafat'] },
            { range: '200-299', min: 200, max: 299, names: ['Agama', 'Agama Islam', 'Islam'] },
            { range: '300-399', min: 300, max: 399, names: ['Ilmu-Ilmu Sosial', 'Sosial'] },
            { range: '400-499', min: 400, max: 499, names: ['Bahasa', 'Bahasa Indonesia', 'Bahasa Inggris'] },
            { range: '500-599', min: 500, max: 599, names: ['Ilmu-Ilmu Alam dan Matematika', 'Sains', 'Matematika'] },
            { range: '600-699', min: 600, max: 699, names: ['Teknologi dan Ilmu Terapan', 'Teknologi', 'Teknologi & IT', 'Komputer', 'robotika'] },
            { range: '700-799', min: 700, max: 799, names: ['Kesenian, Hiburan, dan Olahraga', 'Kesenian', 'Keterampilan', 'Olahraga'] },
            { range: '800-899', min: 800, max: 899, names: ['Kesusastraan', 'Sastra & Novel', 'Novel', 'fiksi', 'Sastra'] },
            { range: '900-999', min: 900, max: 999, names: ['Geografi dan Sejarah', 'Sejarah', 'Geografi'] }
        ];

        function handleCallNumberInput(val) {
            val = (val || '').trim();
            if (!val) return;

            const catSelect = document.getElementById('book_category_select');
            if (!catSelect) return;

            // 1. Cek langsung data-call-number pada option yang ada
            for (let i = 0; i < catSelect.options.length; i++) {
                const opt = catSelect.options[i];
                const optCn = (opt.getAttribute('data-call-number') || '').trim();
                if (optCn && (optCn === val || val.startsWith(optCn.substring(0, 3)))) {
                    catSelect.selectedIndex = i;
                    prevCatVal = opt.value;
                    return;
                }
            }

            // 2. Ekstrak digit angka (contoh '200', '297.1', '200-299')
            const m = val.match(/^(\d{1,3})/);
            if (m) {
                const num = parseInt(m[1], 10);
                const matchedDdc = ddcMappingList.find(d => num >= d.min && num <= d.max);
                if (matchedDdc) {
                    for (let i = 0; i < catSelect.options.length; i++) {
                        const opt = catSelect.options[i];
                        if (matchedDdc.names.includes(opt.value)) {
                            catSelect.selectedIndex = i;
                            prevCatVal = opt.value;
                            return;
                        }
                    }
                }
            }
        }

        function handleCatChange(val) {
            if (val === '__MANAGE_CAT__') {
                openCatModal();
                if (prevCatVal && prevCatVal !== '__MANAGE_CAT__') {
                    document.getElementById('book_category_select').value = prevCatVal;
                } else {
                    document.getElementById('book_category_select').selectedIndex = 0;
                }
                return;
            }
            prevCatVal = val;
            toggleNewCatInput(val);

            // Sinkronisasi otomatis Nomor Panggil ketika Kategori dipilih
            const catSelect = document.getElementById('book_category_select');
            const callInp = document.getElementById('book_call_number_input');
            if (catSelect && callInp && val && val !== '__NEW__') {
                const opt = catSelect.options[catSelect.selectedIndex];
                const cn = opt ? opt.getAttribute('data-call-number') : '';
                if (cn && (!callInp.value || /^\d{3}(-\d{3})?$/.test(callInp.value))) {
                    callInp.value = cn;
                }
            }
        }

        function openCatModal() {
            const sel = document.getElementById('book_category_select');
            const currentVal = sel ? sel.value : '';
            document.querySelectorAll('#modal_manage_categories .cat-item-row').forEach(function(row) {
                if (currentVal && row.getAttribute('data-name') === currentVal) {
                    row.style.background = '#fef2f2';
                    row.style.borderColor = '#f87171';
                } else {
                    row.style.background = '#f8fafc';
                    row.style.borderColor = '#cbd5e1';
                }
            });
            document.getElementById('modal_manage_categories').style.display = 'flex';
        }

        function closeCatModal() {
            document.getElementById('modal_manage_categories').style.display = 'none';
        }

        function handleSourceChange(val) {
            if (val === '__MANAGE_SRC__') {
                openSourceModal();
                if (prevSrcVal && prevSrcVal !== '__MANAGE_SRC__') {
                    document.getElementById('book_source_select').value = prevSrcVal;
                } else {
                    document.getElementById('book_source_select').selectedIndex = 0;
                }
                return;
            }
            prevSrcVal = val;
            toggleCustomSource(val);
        }

        function openSourceModal() {
            const sel = document.getElementById('book_source_select');
            const currentVal = sel ? sel.value : '';
            document.querySelectorAll('#modal_manage_sources .source-item-row').forEach(function(row) {
                if (currentVal && row.getAttribute('data-name') === currentVal) {
                    row.style.background = '#fef2f2';
                    row.style.borderColor = '#f87171';
                } else {
                    row.style.background = '#f8fafc';
                    row.style.borderColor = '#e2e8f0';
                }
            });
            document.getElementById('modal_manage_sources').style.display = 'flex';
        }

        function closeSourceModal() {
            document.getElementById('modal_manage_sources').style.display = 'none';
        }

        function toggleNewCatInput(val) {
            const container = document.getElementById('new_cat_container');
            const input = document.getElementById('new_category_input');
            const newCatCall = document.getElementById('new_cat_call_number_input');
            if (val === '__NEW__') {
                container.style.display = 'block';
                input.focus();
                input.required = true;
                const parentCall = document.getElementById('book_call_number_input');
                if (parentCall && parentCall.value && newCatCall && !newCatCall.value) {
                    newCatCall.value = parentCall.value;
                }
            } else {
                container.style.display = 'none';
                input.required = false;
            }
        }
        function cancelNewCat() {
            const select = document.getElementById('book_category_select');
            select.selectedIndex = 0;
            toggleNewCatInput(select.value);
        }

        function toggleCustomSource(val) {
            const container = document.getElementById('custom_source_container');
            const input = document.getElementById('custom_source_input');
            if (val === '__CUSTOM__') {
                container.style.display = 'block';
                input.focus();
                input.required = true;
            } else {
                container.style.display = 'none';
                input.required = false;
            }
        }
        function cancelCustomSource() {
            const select = document.getElementById('book_source_select');
            select.selectedIndex = 0;
            toggleCustomSource(select.value);
        }

        function previewBookCover(input) {
            const previewImg = document.getElementById('book_cover_img_preview');
            const placeholder = document.getElementById('book_cover_placeholder');
            if (input.files && input.files[0]) {
                const file = input.files[0];
                const reader = new FileReader();
                reader.onload = function(e) {
                    if (previewImg) {
                        previewImg.src = e.target.result;
                        previewImg.style.display = 'block';
                    }
                    if (placeholder) {
                        placeholder.style.display = 'none';
                    }
                };
                reader.readAsDataURL(file);
            }
        }
        function toggleRemoveCover(isChecked) {
            const previewImg = document.getElementById('book_cover_img_preview');
            const placeholder = document.getElementById('book_cover_placeholder');
            const input = document.getElementById('book_cover_input');
            if (isChecked) {
                if (input) input.value = '';
                if (previewImg) previewImg.style.display = 'none';
                if (placeholder) placeholder.style.display = 'flex';
            } else {
                const origSrc = "<?=!empty($editCoverUrl) ? $editCoverUrl : ''?>";
                if (origSrc && previewImg) {
                    previewImg.src = origSrc;
                    previewImg.style.display = 'block';
                    if (placeholder) placeholder.style.display = 'none';
                }
            }
        function loadSampleBookImportData() {
            const ta = document.getElementById('import_book_raw_text');
            if (ta) {
                ta.value = "Kode Buku\tJudul Buku\tJumlah Buku\tKategori\tPenulis\tPenerbit\tTahun Terbit\tSumber Buku\tHarga Satuan\nBK-001\tLaskar Pelangi\t10\tNovel\tAndrea Hirata\tBentang Pustaka\t2005\tDana BOS\t65000\nBK-002\tPemrograman Web Modern\t5\tTeknologi\tBudi Raharjo\tInformatika\t2023\tDana BOS\t85000\nBK-003\tBuku Sejarah Indonesia\t15\tSosial\tSartono Kartodirdjo\tGramedia\t2020\tHibah Pemerintah\t0\nBK-004\tMatematika Terapan\t20\tSains\t\t\t2022\tDana BOS\t";
                ta.focus();
            }
        }
        function validateBookImportForm(form) {
            const fileInput = form.file_excel;
            const hasFile = fileInput && fileInput.files && fileInput.files.length > 0;
            const rawText = form.raw_text ? form.raw_text.value.trim() : '';
            if (!hasFile && rawText === '') {
                alert('Silakan pilih berkas Excel / CSV terlebih dahulu, atau tempelkan baris data buku ke dalam kotak teks.');
                if (form.file_excel) form.file_excel.focus();
                return false;
            }
            return true;
        }
        </script>

