        <script>
        function getCheckedBookCheckboxes() {
            return Array.from(document.querySelectorAll('.book-checkbox:checked'));
        }

        function updateBulkBooksBar() {
            const checked = getCheckedBookCheckboxes();
            const bar = document.getElementById('bulk_book_selection_bar');
            const countBadge = document.getElementById('bulk_book_selected_count_badge');
            const masterCheck = document.getElementById('check_all_books');
            const allBoxes = document.querySelectorAll('.book-checkbox');

            if (countBadge) countBadge.textContent = checked.length + ' Buku Dipilih';

            if (bar) {
                bar.style.display = checked.length > 0 ? 'flex' : 'none';
            }

            if (masterCheck && allBoxes.length > 0) {
                masterCheck.checked = (checked.length === allBoxes.length);
                masterCheck.indeterminate = (checked.length > 0 && checked.length < allBoxes.length);
            }

            allBoxes.forEach(cb => {
                const tr = cb.closest('tr');
                if (tr) {
                    if (cb.checked) {
                        tr.style.backgroundColor = '#fef2f2';
                    } else {
                        tr.style.backgroundColor = '';
                    }
                }
            });
        }

        document.addEventListener('DOMContentLoaded', function() {
            const masterCheck = document.getElementById('check_all_books');
            if (masterCheck) {
                masterCheck.addEventListener('change', function() {
                    const allBoxes = document.querySelectorAll('.book-checkbox');
                    allBoxes.forEach(cb => {
                        cb.checked = masterCheck.checked;
                    });
                    updateBulkBooksBar();
                });
            }

            document.querySelectorAll('.book-checkbox').forEach(cb => {
                cb.addEventListener('change', updateBulkBooksBar);
            });
        });

        function uncheckAllBooks() {
            const masterCheck = document.getElementById('check_all_books');
            if (masterCheck) masterCheck.checked = false;
            document.querySelectorAll('.book-checkbox').forEach(cb => cb.checked = false);
            updateBulkBooksBar();
        }

        function toggleBookArchiveBox() {
            const b = document.getElementById('box_archive_books');
            if (b) {
                b.style.display = (b.style.display === 'none' || b.style.display === '') ? 'block' : 'none';
                if (b.style.display === 'block') {
                    b.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            }
        }

        function handleDeleteAllBooksClick() {
            const checked = getCheckedBookCheckboxes();
            const allBoxes = document.querySelectorAll('.book-checkbox');

            if (checked.length > 0) {
                submitBulkDeleteBooksForm();
            } else {
                if (allBoxes.length === 0) {
                    alert('Tidak ada data buku untuk dihapus.');
                    return;
                }
                if (confirm('⚠️ KONFIRMASI HAPUS SEMUA DATA BUKU KE ARSIP (2 X 24 JAM)\n\nApakah Anda yakin ingin memindahkan SELURUH data koleksi buku ke dalam ARSIP?\n\n✓ Seluruh data buku akan dipindahkan ke Arsip selama 2 x 24 jam (48 jam).\n✓ Anda dapat memulihkan (membalikkan) data buku kapan saja dari menu Arsip.\n✓ Buku yang sedang dipinjam siswa otomatis dilewati demi keamanan.')) {
                    document.getElementById('bulk_delete_book_ids_input').value = '';
                    document.getElementById('bulk_delete_book_scope_input').value = 'all';
                    document.getElementById('form_bulk_delete_books').submit();
                }
            }
        }

        function submitBulkDeleteBooksForm() {
            const checked = getCheckedBookCheckboxes();
            if (checked.length === 0) {
                alert('Silakan pilih / centang setidaknya satu buku terlebih dahulu.');
                return;
            }

            let borrowedCount = 0;
            const ids = [];
            checked.forEach(cb => {
                ids.push(cb.value);
                const bCount = parseInt(cb.getAttribute('data-borrowed') || '0', 10);
                if (bCount > 0) borrowedCount++;
            });

            let confirmMsg = '⚠️ KONFIRMASI PEMINDAHAN KE ARSIP (2 X 24 JAM)\n\n' +
                             'Apakah Anda yakin ingin memindahkan ' + ids.length + ' buku terpilih ke dalam ARSIP?\n\n' +
                             '✓ Seluruh data buku akan disimpan di Arsip selama 2 x 24 jam (48 jam).\n' +
                             '✓ Anda dapat memulihkan (membalikkan) data buku kapan saja dari menu Arsip.\n' +
                             '✓ Setelah 48 jam, data di arsip akan dihapus permanen secara otomatis.';

            if (borrowedCount > 0) {
                confirmMsg += '\n\n⚠️ Catatan: ' + borrowedCount + ' buku yang sedang dipinjam siswa otomatis DILEWATI dan tidak akan dihapus.';
            }

            if (confirm(confirmMsg)) {
                document.getElementById('bulk_delete_book_ids_input').value = ids.join(',');
                document.getElementById('bulk_delete_book_scope_input').value = 'selected';
                document.getElementById('form_bulk_delete_books').submit();
            }
        }
        </script>
        <?php
    });
    exit;
}

