            <script>
            function loadSampleImportData() {
                const ta = document.getElementById('import_raw_text');
                if (ta) {
                    ta.value = "NISN/NIP/NIK\tNAMA\tNOMOR Hape\tPasword\tKategori / Jurusan\n0109628124\tAdhean Chilli\t081666166161\tsiswa123\tTeknik Informatika (PPLG)\n198501152010011002\tBudi Santoso, S.Pd\t082198765432\tguru123\tGuru / Tenaga Pendidik";
                    ta.focus();
                }
            }
            function validateImportForm(form) {
                const fileInput = form.file_excel;
                const hasFile = fileInput && fileInput.files && fileInput.files.length > 0;
                const textVal = document.getElementById('import_raw_text') ? document.getElementById('import_raw_text').value.trim() : '';
                if (!hasFile && textVal === '') {
                    alert('⚠️ Perhatian: Anda belum memilih berkas Excel dan belum menempelkan data anggota ke kotak teks.\n\nSilakan pilih file Excel (Choose File) ATAU klik tombol "Tempel Contoh Data" / salin data dari Excel ke kotak teks sebelum menekan tombol Proses.');
                    if (document.getElementById('import_raw_text')) document.getElementById('import_raw_text').focus();
                    return false;
                }
                return true;
            }
            </script>

