            <?php render_table_pagination($pageNumber, $totalPages, $totalMembersCount, $perPage, array_filter(['page' => 'admin_members', 'q' => $q, 'category' => $catFilter, 'status' => $statusFilter, 'year' => $yearFilter])); ?>
        </div>

        <script>
        function getCheckedMemberCheckboxes() {
            return Array.from(document.querySelectorAll('.member-checkbox:checked'));
        }

        function updateBulkBar() {
            const checked = getCheckedMemberCheckboxes();
            const bar = document.getElementById('bulk_selection_bar');
            const countBadge = document.getElementById('bulk_selected_count_badge');
            const printBadge = document.getElementById('bulk_card_print_badge');
            const modalCount = document.getElementById('modal_checked_count');
            const masterCheck = document.getElementById('check_all_members');
            const allBoxes = document.querySelectorAll('.member-checkbox');

            if (countBadge) countBadge.textContent = checked.length + ' Anggota Dipilih';
            if (printBadge) printBadge.textContent = checked.length;
            if (modalCount) modalCount.textContent = checked.length;

            if (bar) {
                bar.style.display = checked.length > 0 ? 'flex' : 'none';
            }

            if (masterCheck && allBoxes.length > 0) {
                masterCheck.checked = (checked.length === allBoxes.length);
                masterCheck.indeterminate = (checked.length > 0 && checked.length < allBoxes.length);
            }

            allBoxes.forEach(cb => {
                const tr = cb.closest('tr');
                if (tr) {
                    if (cb.checked) {
                        tr.style.backgroundColor = '#f0fdf4';
                    } else {
                        tr.style.backgroundColor = '';
                    }
                }
            });
        }

        function submitBulkPrintCards() {
            const checked = getCheckedMemberCheckboxes();
            if (checked.length === 0) {
                alert('⚠️ Perhatian: Anda belum mencentang siswa pada tabel.\n\nSilakan centang satu atau beberapa siswa pada tabel (atau centang kotak "Aksi" untuk memilih semua), lalu klik tombol "Cetak Kartu Terpilih".');
                return;
            }
            const ids = checked.map(cb => cb.value).join(',');
            window.open('<?=u('index.php?page=card&ids=')?>' + ids, '_blank');
        }

        document.addEventListener('DOMContentLoaded', function() {
            const masterCheck = document.getElementById('check_all_members');
            if (masterCheck) {
                masterCheck.addEventListener('change', function() {
                    const allBoxes = document.querySelectorAll('.member-checkbox');
                    allBoxes.forEach(cb => {
                        cb.checked = masterCheck.checked;
                    });
                    updateBulkBar();
                });
            }

            document.querySelectorAll('.member-checkbox').forEach(cb => {
                cb.addEventListener('change', updateBulkBar);
            });
        });

        function uncheckAllMembers() {
            const masterCheck = document.getElementById('check_all_members');
            if (masterCheck) masterCheck.checked = false;
            document.querySelectorAll('.member-checkbox').forEach(cb => cb.checked = false);
            updateBulkBar();
        }

        function toggleArchiveBox() {
            const b = document.getElementById('box_archive_members');
            if (b) {
                b.style.display = (b.style.display === 'none' || b.style.display === '') ? 'block' : 'none';
                if (b.style.display === 'block') {
                    b.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            }
        }

        function toggleYearDeleteBox() {
            const b = document.getElementById('box_delete_by_year');
            const arc = document.getElementById('box_archive_members');
            const imp = document.getElementById('form_import_member_box');
            const f = document.getElementById('form_add_member_box');
            if (arc) arc.style.display = 'none';
            if (imp) imp.style.display = 'none';
            if (f) f.style.display = 'none';

            if (b) {
                b.style.display = (b.style.display === 'none' || b.style.display === '') ? 'block' : 'none';
                if (b.style.display === 'block') {
                    b.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            }
        }

        function handleYearSelectChange(sel) {
            const customWrap = document.getElementById('custom_year_input_wrap');
            const customInput = document.getElementById('custom_year_input');
            if (sel.value === 'custom') {
                if (customWrap) customWrap.style.display = 'block';
                if (customInput) customInput.focus();
            } else {
                if (customWrap) customWrap.style.display = 'none';
            }
        }

        function confirmDeleteByYear(form) {
            const sel = document.getElementById('delete_target_year_select');
            let targetYear = sel ? sel.value : '';
            if (targetYear === 'custom') {
                const customInput = document.getElementById('custom_year_input');
                targetYear = customInput ? customInput.value.trim() : '';
            }

            if (!targetYear) {
                alert('Silakan pilih atau masukkan tahun masuk anggota yang ingin dihapus.');
                return false;
            }

            const selectedOption = sel ? sel.options[sel.selectedIndex] : null;
            const countInfo = selectedOption && selectedOption.getAttribute('data-count') ? ' (' + selectedOption.getAttribute('data-count') + ' anggota terdaftar)' : '';
            const onlyStudents = form.elements['only_students'] ? form.elements['only_students'].checked : true;
            const scopeText = onlyStudents ? 'KATEGORI SISWA' : 'SELURUH ANGGOTA';

            const confirmMsg = '⚠️ KONFIRMASI PENGHAPUSAN MASSAL ANGKATAN / TAHUN MASUK\n\n' +
                               'Apakah Anda yakin ingin memindahkan seluruh anggota (' + scopeText + ') tahun masuk ' + targetYear + countInfo + ' ke dalam ARSIP?\n\n' +
                               '✓ Data akan disimpan di Arsip selama 2 x 24 jam (48 jam).\n' +
                               '✓ Data dapat dibalikkan / dipulihkan kapan saja dari menu Arsip jika diperlukan.\n' +
                               '✓ Anggota yang masih memiliki buku pinjaman aktif otomatis dilewati demi keamanan perpustakaan.\n' +
                               '✓ Setelah 48 jam di arsip, data akan hilang permanen secara otomatis.';

            return confirm(confirmMsg);
        }

        function handleDeleteAllClick() {
            const checked = getCheckedMemberCheckboxes();
            const allBoxes = document.querySelectorAll('.member-checkbox');

            if (checked.length > 0) {
                submitBulkDeleteForm();
            } else {
                if (allBoxes.length === 0) {
                    alert('Tidak ada data anggota pada tabel ini untuk dihapus.');
                    return;
                }
                if (confirm('Anda belum mencentang anggota.\n\nApakah Anda ingin MENCENTANG SEMUA anggota di halaman ini (' + allBoxes.length + ' anggota) dan memindahkannya ke Arsip?\n\n✓ Data tersimpan aman di Arsip selama 2 x 24 jam (48 jam).\n✓ Data dapat dipulihkan kapan saja sebelum 48 jam.')) {
                    allBoxes.forEach(cb => cb.checked = true);
                    updateBulkBar();
                    submitBulkDeleteForm();
                }
            }
        }

        function submitBulkDeleteForm() {
            const checked = getCheckedMemberCheckboxes();
            if (checked.length === 0) {
                alert('Silakan pilih / centang setidaknya satu anggota terlebih dahulu.');
                return;
            }

            const ids = checked.map(cb => cb.value);
            const names = checked.slice(0, 3).map(cb => cb.getAttribute('data-name') || '').filter(Boolean);
            let preview = names.join(', ');
            if (checked.length > 3) preview += ' dan ' + (checked.length - 3) + ' anggota lainnya';

            const confirmMsg = 'Apakah Anda yakin ingin memindahkan ' + checked.length + ' anggota (' + preview + ') ke dalam ARSIP?\n\n' +
                               '✓ Data tersimpan di Arsip selama 2 x 24 jam (48 jam).\n' +
                               '✓ Data dapat dipulihkan / dibalikkan kapan saja dari menu Arsip.\n' +
                               '✓ Data akan hilang otomatis jika melewati 2 x 24 jam.';

            if (confirm(confirmMsg)) {
                document.getElementById('bulk_delete_ids_input').value = ids.join(',');
                document.getElementById('bulk_delete_scope_input').value = 'selected';
                document.getElementById('form_bulk_delete_members').submit();
            }
        }

        function handleMemberStatusChange(sel, memberName, activeLoans) {
            const newStatus = sel.value;
            const oldStatus = sel.getAttribute('data-original');
            if (newStatus === oldStatus) return;

            let confirmMsg = '';
            if (newStatus === 'inactive') {
                confirmMsg = 'Apakah Anda yakin ingin mengubah status akun "' + memberName + '" menjadi TIDAK AKTIF?';
                if (activeLoans > 0) {
                    confirmMsg += '\n\n⚠️ PERINGATAN: Anggota ini masih memiliki ' + activeLoans + ' peminjaman buku yang aktif!';
                }
                confirmMsg += '\n\nAnggota yang tidak aktif tidak dapat login maupun meminjam buku perpustakaan.';
            } else if (newStatus === 'active') {
                confirmMsg = 'Aktifkan akun anggota "' + memberName + '"?';
            } else {
                confirmMsg = 'Ubah status akun anggota "' + memberName + '"?';
            }

            if (confirm(confirmMsg)) {
                sel.className = 'member-status-select status-val-' + newStatus;
                sel.form.submit();
            } else {
                sel.value = oldStatus;
            }
        }
        </script>
        <?php
    });
    exit;
}

if ($page === 'admin_visits') {
    auth('admin');

    // Handle POST Actions
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $action = $_POST['action'] ?? 'add_visit';

        if ($action === 'scan_member') {
            $code = trim($_POST['member_code'] ?? '');
            $purpose = trim($_POST['purpose'] ?? 'Membaca Koleksi Buku');
            if ($purpose === '') $purpose = 'Membaca Koleksi Buku';

            if ($code !== '') {
                $cleanCode = $code;
                if (preg_match('/id=([0-9]+)/i', $code, $mId)) {
                    $cleanCode = $mId[1];
                } elseif (preg_match('/([A-Za-z0-9\-_]{3,})/i', $code, $mCode)) {
                    $cleanCode = $mCode[1];
                }

                $stmt = $pdo->prepare("SELECT id, name, department, member_code, username, status FROM users WHERE (member_code = ? OR username = ? OR id = ? OR member_code = ?) AND role = 'member' LIMIT 1");
                $stmt->execute([$cleanCode, $cleanCode, (int)$cleanCode, $code]);
                $mem = $stmt->fetch();

                if ($mem) {
                    if ($mem['status'] === 'inactive') {
                        flash('Akun anggota ' . $mem['name'] . ' sedang nonaktif. Kunjungan tidak dapat dicatat.', 'error');
                    } else {
                        $chkVisit = $pdo->prepare("SELECT id FROM visits WHERE member_id = ? AND visit_date = CURDATE() AND (time_out IS NULL OR time_out = '00:00:00') ORDER BY id DESC LIMIT 1");
                        $chkVisit->execute([$mem['id']]);
                        $actVisit = $chkVisit->fetch();

                        if ($actVisit) {
                            $upd = $pdo->prepare("UPDATE visits SET time_out = CURTIME() WHERE id = ?");
                            $upd->execute([$actVisit['id']]);
                            flash('Check-out berhasil! Terima kasih atas kunjungannya, ' . $mem['name'] . '.');
                        } else {
                            $ins = $pdo->prepare("INSERT INTO visits (member_id, visitor_name, department, purpose, visit_date, time_in) VALUES (?, ?, ?, ?, CURDATE(), CURTIME())");
                            $ins->execute([$mem['id'], $mem['name'], $mem['department'] ?: 'Anggota', $purpose]);
                            flash('Presensi kedatangan berhasil! Selamat datang ' . $mem['name'] . ' (' . ($mem['member_code'] ?: $mem['username']) . ').');
                        }
                    }
                } else {
                    flash('Kartu Anggota tidak terdaftar dalam sistem (Kode: ' . $code . ').', 'error');
                }
            } else {
                flash('Silakan scan atau ketik kode kartu anggota.', 'error');
            }
            header('Location: ' . u('index.php?page=admin_visits'));
            exit;
        }

        if ($action === 'quick_member') {
            $mid = (int)($_POST['member_id'] ?? 0);
            $purpose = trim($_POST['purpose'] ?? 'Membaca & Meminjam Buku');
            if ($purpose === '') $purpose = 'Membaca & Meminjam Buku';

            if ($mid > 0) {
                $mStmt = $pdo->prepare("SELECT name, department, member_code FROM users WHERE id = ? AND role = 'member' LIMIT 1");
                $mStmt->execute([$mid]);
                $mem = $mStmt->fetch();
                if ($mem) {
                    $ins = $pdo->prepare("INSERT INTO visits (member_id, visitor_name, department, purpose, visit_date, time_in) VALUES (?, ?, ?, ?, CURDATE(), CURTIME())");
                    $ins->execute([$mid, $mem['name'], $mem['department'] ?: '-', $purpose]);
                    flash('Presensi kunjungan anggota ' . $mem['name'] . ' (' . $mem['member_code'] . ') berhasil dicatat.');
                } else {
                    flash('Anggota tidak ditemukan.', 'error');
                }
            } else {
                flash('Silakan pilih anggota terlebih dahulu.', 'error');
            }
            header('Location: ' . u('index.php?page=admin_visits'));
            exit;
        }

        if ($action === 'checkout') {
            $vid = (int)($_POST['visit_id'] ?? 0);
            if ($vid > 0) {
                $pdo->prepare("UPDATE visits SET time_out = CURTIME() WHERE id = ? AND visit_date = CURDATE()")->execute([$vid]);
                flash('Jam keluar pengunjung berhasil dicatat.');
            }
            header('Location: ' . u('index.php?page=admin_visits'));
            exit;
        }

        // Guest / Manual Visit
        $mid = (int)($_POST['member_id'] ?? 0);
        $vName = trim($_POST['visitor_name'] ?? '');
        $dept = trim($_POST['department'] ?? '');
        $purpose = trim($_POST['purpose'] ?? 'Membaca Buku');

        if ($vName !== '') {
            $ins = $pdo->prepare("INSERT INTO visits (member_id, visitor_name, department, purpose, visit_date, time_in) VALUES (?, ?, ?, ?, CURDATE(), CURTIME())");
            $ins->execute([$mid ?: null, $vName, $dept, $purpose]);
            flash('Presensi kunjungan tamu berhasil dicatat.');
        } else {
            flash('Nama pengunjung wajib diisi.', 'error');
        }
        header('Location: ' . u('index.php?page=admin_visits'));
        exit;
    }

    $activeMembers = $pdo->query("SELECT id, name, member_code, department FROM users WHERE role='member' AND status='active' ORDER BY name ASC")->fetchAll();
    $todayVisits = $pdo->query("SELECT v.*, u.name as member_name, u.member_code as u_code FROM visits v LEFT JOIN users u ON u.id = v.member_id WHERE v.visit_date = CURDATE() ORDER BY v.id DESC")->fetchAll();

    $totalToday = count($todayVisits);
    $activeNow = 0;
    foreach ($todayVisits as $tv) {
        if (empty($tv['time_out'])) $activeNow++;
    }

    render_app_layout('admin', 'visits', 'Buku Kunjungan Harian', function() use ($activeMembers, $todayVisits, $totalToday, $activeNow) {
