        </div>

        <!-- Load HTML5 QR Code & Barcode Scanner Library -->
        <script src="<?=u('assets/js/html5-qrcode.min.js')?>"></script>
        <script>
        (function() {
            let html5QrScanner = null;
            let isScannerActive = false;
            let isProcessingScan = false;
            let lastCodeScanned = '';
            let lastScanTimestamp = 0;
            let availableCameras = [];
            let selectedCameraId = null;

            // Audio Chime Synthesis (Web Audio API - 100% Offline)
            function playBeepSound(isSuccess) {
                try {
                    const AudioCtx = window.AudioContext || window.webkitAudioContext;
                    if (!AudioCtx) return;
                    const ctx = new AudioCtx();
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    const now = ctx.currentTime;

                    if (type === 'checkout') {
                        // Melodi harmoni kepulangan (E5 -> A5 -> C6)
                        osc.type = 'sine';
                        osc.frequency.setValueAtTime(659.25, now);
                        osc.frequency.setValueAtTime(880, now + 0.1);
                        osc.frequency.setValueAtTime(1046.5, now + 0.2);
                        gain.gain.setValueAtTime(0.35, now);
                        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.45);
                        osc.start(now);
                        osc.stop(now + 0.45);
                    } else if (type === 'checkin' || type === true) {
                        // Melodi cerah kedatangan (A5 -> E6)
                        osc.type = 'sine';
                        osc.frequency.setValueAtTime(880, now);
                        osc.frequency.setValueAtTime(1318.5, now + 0.08);
                        gain.gain.setValueAtTime(0.35, now);
                        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.35);
                        osc.start(now);
                        osc.stop(now + 0.35);
                    } else {
                        // Suara kesalahan
                        osc.type = 'sawtooth';
                        osc.frequency.setValueAtTime(260, now);
                        gain.gain.setValueAtTime(0.3, now);
                        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.25);
                        osc.start(now);
                        osc.stop(now + 0.25);
                    }
                } catch(e) {}
            }

            // Voice Speech Synthesis: Kedatangan & Kepulangan (100% Offline & Alami)
            function speakThankYou(memberName, actionType) {
                try {
                    if ('speechSynthesis' in window) {
                        window.speechSynthesis.cancel();
                        const firstName = memberName ? memberName.trim().split(' ')[0] : '';
                        let msg = '';
                        if (actionType === 'checkout') {
                            msg = firstName ? 
                                ('Terima kasih kunjungannya, ' + firstName + '! Sampai jumpa lagi.') : 
                                'Terima kasih atas kunjungannya, sampai jumpa lagi!';
                        } else {
                            msg = firstName ? 
                                ('Selamat datang, ' + firstName + '! Presensi kedatangan berhasil dicatat.') : 
                                'Selamat datang! Presensi kedatangan berhasil dicatat.';
                        }
                        
                        const utter = new SpeechSynthesisUtterance(msg);
                        utter.lang = 'id-ID';
                        utter.rate = 1.0;
                        utter.pitch = actionType === 'checkout' ? 1.02 : 1.05;
                        utter.volume = 1.0;

                        const voices = window.speechSynthesis.getVoices();
                        if (voices && voices.length > 0) {
                            const idVoice = voices.find(v => v.lang && (v.lang.toLowerCase().includes('id') || v.lang.toLowerCase().includes('ind')));
                            if (idVoice) utter.voice = idVoice;
                        }

                        window.speechSynthesis.speak(utter);
                    }
                } catch(e) {
                    console.warn('Speech synthesis audio warning:', e);
                }
            }

            window.testThankYouVoice = function() {
                playBeepSound('checkout');
                setTimeout(() => {
                    speakThankYou('Siswa', 'checkout');
                }, 220);
            };

            // Mode Switcher: 'scan' or 'button'
            window.switchPresenceMode = function(mode) {
                const btnScan = document.getElementById('tabBtnScan');
                const btnBtn = document.getElementById('tabBtnButton');
                const panelScan = document.getElementById('panelScanMode');
                const panelBtn = document.getElementById('panelButtonMode');

                if (mode === 'scan') {
                    btnScan.classList.add('active', 'tab-scan');
                    btnBtn.classList.remove('active');
                    panelScan.style.display = 'block';
                    panelBtn.style.display = 'none';
                    localStorage.setItem('perpustakaan_presence_mode', 'scan');
                    startCameraScanner();
                } else {
                    btnBtn.classList.add('active');
                    btnScan.classList.remove('active', 'tab-scan');
                    panelScan.style.display = 'none';
                    panelBtn.style.display = 'block';
                    localStorage.setItem('perpustakaan_presence_mode', 'button');
                    stopCameraScanner();
                }
            };

            // Camera Scanner Controller
            window.startCameraScanner = async function() {
                if (isScannerActive) return;

                const liveView = document.getElementById('scannerLiveView');
                const placeholder = document.getElementById('scannerPlaceholder');
                const reticle = document.getElementById('scannerReticle');
                const statusDot = document.getElementById('scannerStatusDot');
                const statusText = document.getElementById('scannerStatusText');
                const btnToggle = document.getElementById('btnToggleCam');

                placeholder.style.display = 'none';
                reticle.style.display = 'block';
                statusDot.className = 'scanner-status-dot pulse';
                statusText.textContent = 'Menghubungkan Kamera...';

                try {
                    if (!html5QrScanner) {
                        html5QrScanner = new Html5Qrcode("scannerLiveView");
                    }

                    // Enumerate cameras if not loaded
                    if (availableCameras.length === 0) {
                        try {
                            const devices = await Html5Qrcode.getCameras();
                            if (devices && devices.length > 0) {
                                availableCameras = devices;
                                const sel = document.getElementById('cameraDeviceSelect');
                                sel.innerHTML = '';
                                devices.forEach((cam, idx) => {
                                    const opt = document.createElement('option');
                                    opt.value = cam.id;
                                    opt.text = cam.label || ('Kamera ' + (idx + 1));
                                    sel.appendChild(opt);
                                });
                                selectedCameraId = devices[0].id;
                            }
                        } catch(camErr) {
                            console.warn('Could not enumerate camera devices:', camErr);
                        }
                    }

                    const camConfig = selectedCameraId ? {
                        deviceId: { exact: selectedCameraId }
                    } : {
                        facingMode: "environment"
                    };

                    await html5QrScanner.start(
                        camConfig,
                        {
                            fps: 20, // Pemindaian lebih responsif (20 fps)
                            qrbox: function(viewfinderWidth, viewfinderHeight) {
                                // Area deteksi luas agar QR kartu cepat tertangkap
                                return {
                                    width: Math.min(viewfinderWidth - 20, 320),
                                    height: Math.min(viewfinderHeight - 20, 230)
                                };
                            },
                            aspectRatio: 1.333333,
                            videoConstraints: {
                                facingMode: "environment",
                                width: { min: 640, ideal: 1280, max: 1920 },
                                height: { min: 480, ideal: 720, max: 1080 }
                            },
                            experimentalFeatures: {
                                useBarCodeDetectorIfSupported: true // Akses akselerasi hardware native browser
                            }
                        },
                        onQrCodeSuccess,
                        onQrCodeError
                    );

                    isScannerActive = true;
                    statusDot.style.background = '#22c55e';
                    statusText.textContent = 'Kamera Aktif (Siap Scan)';
                    btnToggle.innerHTML = '⏹ Matikan Kamera';
                    btnToggle.className = 'btn btn-sm btn-outline-danger';
                } catch(err) {
                    console.error('Camera start error:', err);
                    placeholder.style.display = 'block';
                    reticle.style.display = 'none';
                    statusDot.style.background = '#ef4444';
                    statusText.textContent = 'Gagal Akses Kamera';
                    showScanErrorAlert('Gagal mengakses kamera laptop/PC: ' + (err.message || err) + '. Pastikan izin kamera telah diizinkan pada browser.');
                }
            };

            window.stopCameraScanner = async function() {
                if (!isScannerActive || !html5QrScanner) return;
                try {
                    await html5QrScanner.stop();
                } catch(e) {}
                isScannerActive = false;

                const placeholder = document.getElementById('scannerPlaceholder');
                const reticle = document.getElementById('scannerReticle');
                const statusDot = document.getElementById('scannerStatusDot');
                const statusText = document.getElementById('scannerStatusText');
                const btnToggle = document.getElementById('btnToggleCam');

                placeholder.style.display = 'block';
                reticle.style.display = 'none';
                statusDot.style.background = '#94a3b8';
                statusDot.classList.remove('pulse');
                statusText.textContent = 'Kamera Mati';
                btnToggle.innerHTML = '📷 Buka Kamera';
                btnToggle.className = 'btn btn-sm btn-outline-success';
            };

            window.toggleCameraScanner = function() {
                if (isScannerActive) {
                    stopCameraScanner();
                } else {
                    startCameraScanner();
                }
            };

            window.onCameraDeviceChange = function(newCamId) {
                selectedCameraId = newCamId;
                if (isScannerActive) {
                    stopCameraScanner().then(() => {
                        startCameraScanner();
                    });
                }
            };

            function onQrCodeSuccess(decodedText) {
                if (isProcessingScan) return;
                const now = Date.now();
                if (decodedText === lastCodeScanned && (now - lastScanTimestamp) < 3000) {
                    return; // Cooldown 3 detik untuk kartu yang sama
                }
                lastCodeScanned = decodedText;
                lastScanTimestamp = now;

                processScannedCard(decodedText);
            }

            function onQrCodeError(error) {
                // Ignore per-frame decode errors
            }

            // Process Scanned Code via AJAX
            window.processScannedCard = function(code) {
                if (!code || isProcessingScan) return;
                isProcessingScan = true;

                const purpose = document.getElementById('scanVisitPurpose').value;
                const feedbackBox = document.getElementById('scanFeedbackContainer');

                feedbackBox.style.display = 'block';
                feedbackBox.innerHTML = `
                    <div class="scan-feedback-box" style="background:#f8fafc;border:1px solid #cbd5e1;color:#334155;">
                        <span style="font-size:20px;animation:spin 1s linear infinite;">⏳</span>
                        <div>
                            <b>Memverifikasi data kartu "${escapeHtml(code)}"...</b>
                            <div style="font-size:11px;color:#64748b;">Mencocokkan ke database anggota perpustakaan</div>
                        </div>
                    </div>
                `;

                const formData = new FormData();
                formData.append('code', code);
                formData.append('purpose', purpose);

                fetch('<?=u("index.php?page=api_scan_visit")?>', {
                    method: 'POST',
                    body: formData
                })
                .then(r => r.json())
                .then(res => {
                    isProcessingScan = false;
                    if (res.success) {
                        const actType = res.action_type || 'checkin';
                        playBeepSound(actType);
                        speakThankYou(res.member ? res.member.name : '', actType);
                        showScanSuccessAlert(res.member, actType);
                        if (actType === 'checkout') {
                            updateVisitRowCheckout(res.member);
                        } else {
                            appendNewVisitRow(res.member);
                        }
                        if (res.stats) {
                            updateStatsDisplay(res.stats);
                        }
                    } else {
                        playBeepSound('error');
                        showScanErrorAlert(res.message);
                    }
                })
                .catch(err => {
                    isProcessingScan = false;
                    playBeepSound('error');
                    showScanErrorAlert('Terjadi gangguan saat memproses presensi. Silakan coba kembali.');
                });
            };

            window.submitManualCode = function() {
                const inp = document.getElementById('manualBarcodeInput');
                const val = inp.value.trim();
                if (val) {
                    processScannedCard(val);
                    inp.value = '';
                }
            };

            function showScanSuccessAlert(m, actionType) {
                const box = document.getElementById('scanFeedbackContainer');
                box.style.display = 'block';

                const isCheckout = (actionType === 'checkout');
                const badgeColor = isCheckout ? '#0369a1' : '#15803d';
                const badgeBg = isCheckout ? '#e0f2fe' : '#dcfce7';
                const borderCol = isCheckout ? '#7dd3fc' : '#86efac';
                const statusLabel = isCheckout ? '👋 CHECK-OUT KEPULANGAN BERHASIL' : '✓ CHECK-IN KEDATANGAN BERHASIL';
                
                const timeInfo = isCheckout ? 
                    `Jam Masuk: <b>${(m.time_in || '').substring(0,5)} WIB</b> · Jam Pulang: <b><span style="color:#0284c7;">${(m.time_out || '').substring(0,5)} WIB</span></b>` :
                    `Keperluan: <b>${escapeHtml(m.purpose)}</b> · Jam Masuk: <b>${(m.time_in || '').substring(0,5)} WIB</b>`;

                const subMsg = isCheckout ?
                    `<div style="font-size:12px;color:#0369a1;margin-top:3px;font-weight:700;">Terima kasih atas kunjungannya, hati-hati di jalan!</div>` :
                    `<div style="font-size:12px;color:#15803d;margin-top:3px;font-weight:700;">Selamat datang di perpustakaan! Silakan membaca dan memilih buku.</div>`;

                box.innerHTML = `
                    <div class="scan-feedback-box success" style="border:1.5px solid ${borderCol};background:linear-gradient(135deg, ${isCheckout ? '#f0f9ff' : '#f0fdf4'} 0%, #ffffff 100%);">
                        <img src="${m.photo}" alt="Foto" style="width:48px;height:56px;border-radius:6px;object-fit:cover;border:2px solid ${borderCol};background:#0f172a;flex-shrink:0;">
                        <div style="flex:1;min-width:0;">
                            <div style="font-size:10.5px;font-weight:800;color:${badgeColor};letter-spacing:0.5px;display:inline-block;padding:2px 8px;background:${badgeBg};border-radius:12px;margin-bottom:4px;">
                                ${statusLabel}
                            </div>
                            <div style="font-size:16px;font-weight:800;color:#0f172a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
                                ${escapeHtml(m.name)}
                            </div>
                            <div style="font-size:12px;color:#334155;">
                                NISN/ID: <b>${escapeHtml(m.member_code)}</b> · ${escapeHtml(m.department)}
                            </div>
                            <div style="font-size:11.5px;color:#475569;margin-top:2px;">
                                ${timeInfo}
                            </div>
                            ${subMsg}
                        </div>
                    </div>
                `;
            }

            function showScanErrorAlert(msg) {
                const box = document.getElementById('scanFeedbackContainer');
                box.style.display = 'block';
                box.innerHTML = `
                    <div class="scan-feedback-box error">
                        <span style="font-size:24px;flex-shrink:0;">⚠️</span>
                        <div style="flex:1;">
                            <div style="font-size:13.5px;font-weight:800;color:#b91c1c;">Gagal Memproses Presensi</div>
                            <div style="font-size:12px;color:#7f1d1d;line-height:1.4;">${escapeHtml(msg)}</div>
                        </div>
                    </div>
                `;
            }

            function appendNewVisitRow(m) {
                const tbody = document.getElementById('todayVisitsTableBody');
                const emptyRow = document.getElementById('emptyVisitRow');
                if (emptyRow) emptyRow.remove();

                const tr = document.createElement('tr');
                tr.id = 'visit-row-' + m.visit_id;
                tr.setAttribute('data-member-id', m.id);
                tr.style.background = '#ecfdf5';
                tr.innerHTML = `
                    <td>1</td>
                    <td>
                        <div style="font-weight:700;color:var(--navy);">${escapeHtml(m.name)}</div>
                    </td>
                    <td><span class="badge badge-blue">${escapeHtml(m.member_code)}</span></td>
                    <td>${escapeHtml(m.department)}</td>
                    <td>${escapeHtml(m.purpose)}</td>
                    <td><span class="badge badge-green" style="font-size:12px;">${m.time_in.substring(0,5)} WIB</span></td>
                    <td class="col-time-out"><span class="badge-status-visiting" style="font-size:12px;color:#10b981;font-weight:700;">Masih Berkunjung</span></td>
                    <td class="col-action" style="text-align:center;">
                        <form method="post" style="display:inline;" onsubmit="return confirm('Catat kepulangan/check-out pengunjung ini?');">
                            <input type="hidden" name="csrf" value="<?=csrf()?>">
                            <input type="hidden" name="action" value="checkout">
                            <input type="hidden" name="visit_id" value="${m.visit_id}">
                            <button type="submit" class="btn btn-sm btn-outline-warning" style="font-size:11.5px;padding:4px 10px;">
                                <?=icon('clock', '', 12)?> Check-out
                            </button>
                        </form>
                    </td>
                `;

                if (tbody.firstChild) {
                    tbody.insertBefore(tr, tbody.firstChild);
                } else {
                    tbody.appendChild(tr);
                }

                // Renumber rows & update total badge
                const rows = tbody.querySelectorAll('tr');
                let count = 0;
                rows.forEach((r) => {
                    if (r.id !== 'emptyVisitRow') {
                        count++;
                        const firstTd = r.querySelector('td');
                        if (firstTd) firstTd.textContent = count;
                    }
                });
                const countBadge = document.getElementById('visitTableCount');
                if (countBadge) countBadge.textContent = count;

                setTimeout(() => {
                    tr.style.transition = 'background 2s ease';
                    tr.style.background = 'transparent';
                }, 1500);
            }

            function updateVisitRowCheckout(m) {
                let row = document.getElementById('visit-row-' + m.visit_id);
                if (!row) {
                    // Fallback cari berdasarkan data-member-id yang masih berkunjung
                    const candidateRows = document.querySelectorAll(`tr[data-member-id="${m.id}"]`);
                    for (let r of candidateRows) {
                        const visitingBadge = r.querySelector('.badge-status-visiting');
                        if (visitingBadge) {
                            row = r;
                            break;
                        }
                    }
                }

                if (row) {
                    const timeOutFormatted = (m.time_out || '').substring(0, 5) + ' WIB';
                    const colTimeOut = row.querySelector('.col-time-out') || row.children[6];
                    const colAction = row.querySelector('.col-action') || row.children[7];

                    if (colTimeOut) {
                        colTimeOut.innerHTML = `<span class="badge badge-gray" style="font-size:12px;">${timeOutFormatted}</span>`;
                    }
                    if (colAction) {
                        colAction.innerHTML = `<span style="font-size:11.5px;color:var(--text-muted);"><svg class="icon" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg> Selesai</span>`;
                    }

                    row.style.background = '#e0f2fe';
                    setTimeout(() => {
                        row.style.transition = 'background 2s ease';
                        row.style.background = 'transparent';
                    }, 1500);
                }
            }

            function updateStatsDisplay(s) {
                const totalEl = document.getElementById('statTotalToday');
                const activeEl = document.getElementById('statActiveNow');
                const outEl = document.getElementById('statCheckedOut');
                if (totalEl) totalEl.textContent = s.total_today;
                if (activeEl) activeEl.textContent = s.active_now;
                if (outEl) outEl.textContent = s.checked_out;
            }

            function escapeHtml(str) {
                if (!str) return '';
                return String(str).replace(/[&<>"']/g, function(m) {
                    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m];
                });
            }

            // Restore saved mode or default to 'scan'
            const savedMode = localStorage.getItem('perpustakaan_presence_mode') || 'scan';
            if (savedMode === 'button') {
                switchPresenceMode('button');
            } else {
                // Focus on barcode input for quick gun scanning
                const barcodeInp = document.getElementById('manualBarcodeInput');
                if (barcodeInp) barcodeInp.focus();
            }
        })();
        </script>
        <?php
    });
    exit;
}

