if ($page === 'admin_news') {
    auth('admin');

    // Handle Delete
    if (isset($_GET['delete'])) {
        $nid = (int)$_GET['delete'];
        $del = $pdo->prepare("DELETE FROM news WHERE id = ?");
        $del->execute([$nid]);
        flash('Berita / pengumuman berhasil dihapus.');
        header('Location: ' . u('index.php?page=admin_news'));
        exit;
    }

    // Handle Create & Update
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        checkcsrf();
        $id = (int)($_POST['id'] ?? 0);
        $title = trim($_POST['title'] ?? '');
        $category = trim($_POST['category'] ?? 'Pengumuman');
        $content = trim($_POST['content'] ?? '');
        $author = trim($_POST['author'] ?? 'Admin Perpustakaan');
        $status = in_array($_POST['status'] ?? '', ['published', 'draft']) ? $_POST['status'] : 'published';

        if ($title === '' || $content === '') {
            flash('Judul dan isi berita wajib diisi.', 'error');
        } else {
            if ($id > 0) {
                $stmt = $pdo->prepare("UPDATE news SET title = ?, category = ?, content = ?, author = ?, status = ? WHERE id = ?");
                $stmt->execute([$title, $category, $content, $author, $status, $id]);
                flash('Berita berhasil diperbarui.');
            } else {
                $stmt = $pdo->prepare("INSERT INTO news (title, category, content, author, status) VALUES (?, ?, ?, ?, ?)");
                $stmt->execute([$title, $category, $content, $author, $status]);
                flash('Berita baru berhasil diterbitkan dan langsung tampil di beranda publik!');
            }
            header('Location: ' . u('index.php?page=admin_news'));
            exit;
        }
    }

    // Fetch Edit Data if Requested
    $editItem = null;
