            $currentPass = (string)($_POST['current_password'] ?? '');
            $newPass = (string)($_POST['new_password'] ?? '');
            $confirmPass = (string)($_POST['confirm_password'] ?? '');
            $adminId = (int)($currentUser['id'] ?? 0);

            $adminStmt = $pdo->prepare("SELECT * FROM users WHERE id = ? AND role = 'admin' LIMIT 1");
            $adminStmt->execute([$adminId]);
            $adminUser = $adminStmt->fetch();

            if (!$adminUser || !password_verify($currentPass, $adminUser['password_hash'])) {
                flash('Password saat ini salah. Silakan periksa kembali password akun admin Anda.', 'error');
            } elseif (strlen($newPass) < 6) {
                flash('Password baru minimal harus 6 karakter untuk menjaga keamanan sistem.', 'error');
            } elseif ($newPass !== $confirmPass) {
                flash('Konfirmasi password baru tidak cocok. Pastikan pengetikan sama persis.', 'error');
            } else {
                $newHash = password_hash($newPass, PASSWORD_DEFAULT);
                $pdo->prepare("UPDATE users SET password_hash = ? WHERE id = ? AND role = 'admin'")->execute([$newHash, $adminId]);
                if (isset($_SESSION['user'])) {
                    $_SESSION['user']['password_hash'] = $newHash;
                }
                flash('Password admin berhasil diubah! Gunakan password baru ini untuk login berikutnya.');
            }
            header('Location: ' . u('index.php?page=settings&tab=password'));
            exit;
        }

        if ($tab === 'member_categories') {
            $action = $_POST['action'] ?? 'add';

            if ($action === 'add') {
                $name = trim($_POST['name'] ?? '');
                $group = trim($_POST['group_type'] ?? 'Civitas Sekolah');
                if ($name === '') {
                    flash('Nama kategori / jurusan tidak boleh kosong.', 'error');
                } else {
                    $chk = $pdo->prepare("SELECT id FROM member_categories WHERE LOWER(name) = LOWER(?) LIMIT 1");
                    $chk->execute([$name]);
                    if ($chk->fetch()) {
                        flash('Kategori "' . e($name) . '" sudah ada dalam daftar.', 'error');
                    } else {
                        $orderStmt = $pdo->query("SELECT COALESCE(MAX(sort_order), 0) + 1 FROM member_categories");
                        $nextOrder = (int)$orderStmt->fetchColumn();
                        $ins = $pdo->prepare("INSERT INTO member_categories (name, group_type, sort_order) VALUES (?, ?, ?)");
                        $ins->execute([$name, $group, $nextOrder]);
                        flash('Kategori "' . e($name) . '" berhasil ditambahkan ke daftar pendaftaran anggota.');
                    }
                }
            } elseif ($action === 'edit') {
                $catId = (int)($_POST['id'] ?? 0);
                $name = trim($_POST['name'] ?? '');
                $group = trim($_POST['group_type'] ?? 'Civitas Sekolah');
                $sync = isset($_POST['sync_members']) && $_POST['sync_members'] === '1';

                if ($catId <= 0 || $name === '') {
                    flash('Data kategori tidak lengkap.', 'error');
                } else {
                    $chk = $pdo->prepare("SELECT id FROM member_categories WHERE LOWER(name) = LOWER(?) AND id != ? LIMIT 1");
                    $chk->execute([$name, $catId]);
                    if ($chk->fetch()) {
                        flash('Kategori dengan nama "' . e($name) . '" sudah ada.', 'error');
                    } else {
                        $oldStmt = $pdo->prepare("SELECT name FROM member_categories WHERE id = ?");
                        $oldStmt->execute([$catId]);
                        $oldName = $oldStmt->fetchColumn();

                        $upd = $pdo->prepare("UPDATE member_categories SET name = ?, group_type = ? WHERE id = ?");
                        $upd->execute([$name, $group, $catId]);

                        if ($sync && $oldName && $oldName !== $name) {
                            $updUsers = $pdo->prepare("UPDATE users SET department = ? WHERE department = ?");
                            $updUsers->execute([$name, $oldName]);
                            $updVisits = $pdo->prepare("UPDATE visits SET department = ? WHERE department = ?");
                            $updVisits->execute([$name, $oldName]);
                        }
                        flash('Kategori "' . e($name) . '" berhasil diperbarui.');
                    }
                }
            } elseif ($action === 'delete') {
                $catId = (int)($_POST['id'] ?? 0);
                $cStmt = $pdo->prepare("SELECT name FROM member_categories WHERE id = ? LIMIT 1");
                $cStmt->execute([$catId]);
                $cName = $cStmt->fetchColumn();

                if ($cName) {
                    $chkUsers = $pdo->prepare("SELECT COUNT(*) FROM users WHERE department = ?");
                    $chkUsers->execute([$cName]);
                    $memCount = (int)$chkUsers->fetchColumn();

                    $pdo->prepare("DELETE FROM member_categories WHERE id = ?")->execute([$catId]);

                    if ($memCount > 0) {
                        flash('Kategori "' . e($cName) . '" berhasil dihapus dari opsi pendaftaran. Sebanyak ' . $memCount . ' data anggota yang sudah terdaftar tetap tersimpan sebagai arsip.', 'warning');
                    } else {
                        flash('Kategori "' . e($cName) . '" berhasil dihapus.');
                    }
                }
            } elseif ($action === 'apply_preset') {
                $preset = $_POST['preset'] ?? '';
