            <script>
            document.getElementById('navLogoInput')?.addEventListener('change', function(e) {
                const file = e.target.files[0];
                if (file) {
                    const reader = new FileReader();
                    reader.onload = function(evt) {
                        const preview = document.getElementById('navLogoPreview');
                        if (preview) preview.src = evt.target.result;
                    };
                    reader.readAsDataURL(file);
                }
            });

            function syncColorPicker(pickerId, textId) {
                const picker = document.getElementById(pickerId);
                const text = document.getElementById(textId);
                if (picker && text) {
                    text.value = picker.value;
                    updateLivePreview();
                }
            }

            function syncColorInput(textId, pickerId) {
                const text = document.getElementById(textId);
                const picker = document.getElementById(pickerId);
                if (text && picker) {
                    if (/^#[0-9a-fA-F]{6}$/.test(text.value)) {
                        picker.value = text.value;
                    }
                    updateLivePreview();
                }
            }

            function applyThemePreset(primary, navBg, navText, sidebarBg) {
                const setVal = (id, val) => {
                    const el = document.getElementById(id);
                    if (el) el.value = val;
                };
                setVal('themePrimaryPicker', primary);
                setVal('themePrimaryText', primary);
                setVal('themeNavbarBgPicker', navBg);
                setVal('themeNavbarBgText', navBg);
                setVal('themeNavbarTextPicker', navText);
                setVal('themeNavbarText', navText);
                setVal('themeSidebarBgPicker', sidebarBg);
                setVal('themeSidebarBgText', sidebarBg);

                updateLivePreview();
            }

            function updateLivePreview() {
                const primary = document.getElementById('themePrimaryText')?.value || '#1474dc';
                const navBg = document.getElementById('themeNavbarBgText')?.value || '#ffffff';
                const navText = document.getElementById('themeNavbarText')?.value || '#17324d';
                const sidebarBg = document.getElementById('themeSidebarBgText')?.value || '#0c2340';

                const pNav = document.getElementById('previewNavbarContainer');
                if (pNav) {
                    pNav.style.backgroundColor = navBg;
                }
                const pTitle = document.getElementById('previewNavTitle');
                if (pTitle) pTitle.style.color = navText;

                const link1 = document.getElementById('previewNavLink');
                if (link1) link1.style.color = navText;
                const link2 = document.getElementById('previewNavLink2');
                if (link2) link2.style.color = navText;

                const pBtn = document.getElementById('previewNavBtn');
                if (pBtn) pBtn.style.backgroundColor = primary;

                const pSide = document.getElementById('previewSidebarContainer');
                if (pSide) pSide.style.backgroundColor = sidebarBg;

                const pSideActive = document.getElementById('previewSidebarActive');
                if (pSideActive) pSideActive.style.backgroundColor = primary;
            }
            </script>
