                </div>
            </div>

            <script>
            function updateFooterLivePreview() {
                var leftVal = document.getElementById('footerLeftInput')?.value || '';
                var rightVal = document.getElementById('footerRightInput')?.value || '';
                
                var currentYear = '<?=date('Y')?>';
                var schoolName = '<?=e(SCHOOL)?>';
                
                var formattedLeft = leftVal
                    .replace(/\{YEAR\}/g, currentYear)
                    .replace(/\{TAHUN\}/g, currentYear)
                    .replace(/\{SEKOLAH\}/g, schoolName)
                    .replace(/\{SCHOOL\}/g, schoolName);

                var formattedRight = rightVal
                    .replace(/\{YEAR\}/g, currentYear)
                    .replace(/\{TAHUN\}/g, currentYear)
                    .replace(/\{SEKOLAH\}/g, schoolName)
                    .replace(/\{SCHOOL\}/g, schoolName);

                var pLeft = document.getElementById('footerPreviewLeft');
                var pRight = document.getElementById('footerPreviewRight');
                if (pLeft) pLeft.innerHTML = formattedLeft;
                if (pRight) pRight.textContent = formattedRight;
            }

            function resetFooterDefault() {
                var defaultLeft = '© <?=date('Y')?> <b><?=e(SCHOOL)?></b> · Perpustakaan Digital Berbasis Intranet Cepat';
                var defaultRight = 'Akses Lokal Host & Wi-Fi Sekolah · Respons Cepat 0ms CDN';
                
                var leftInput = document.getElementById('footerLeftInput');
                var rightInput = document.getElementById('footerRightInput');
                if (leftInput) leftInput.value = defaultLeft;
                if (rightInput) rightInput.value = defaultRight;
                updateFooterLivePreview();
            }
            </script>
        <?php endif; ?>

