            <script>
            function openEditMemberCatModal(cat) {
                document.getElementById('edit_cat_id').value = cat.id;
                document.getElementById('edit_cat_name').value = cat.name;
                const grpSelect = document.getElementById('edit_cat_group');
                let found = false;
                for (let i = 0; i < grpSelect.options.length; i++) {
                    if (grpSelect.options[i].value === cat.group_type) {
                        grpSelect.selectedIndex = i;
                        found = true;
                        break;
                    }
                }
                if (!found && cat.group_type) {
                    const opt = document.createElement('option');
                    opt.value = cat.group_type;
                    opt.textContent = cat.group_type;
                    opt.selected = true;
                    grpSelect.appendChild(opt);
                }
                const modal = document.getElementById('editMemberCatModal');
                modal.style.display = 'flex';
            }
            function closeEditMemberCatModal() {
                document.getElementById('editMemberCatModal').style.display = 'none';
            }
            </script>
