            <!-- Real-Time Interactive Preview Script -->
            <script>
            function toggleKopMode(mode) {
                const boxLogo = document.getElementById('box_logo_settings');
                const boxText = document.getElementById('box_text_settings');
                const boxImage = document.getElementById('box_image_settings');
                const pvCustom = document.getElementById('preview_custom_container');
                const pvBanner = document.getElementById('preview_banner_container');
                const lblCustom = document.getElementById('label_mode_custom');
                const lblImage = document.getElementById('label_mode_image');

                if (mode === 'image') {
                    if (boxLogo) boxLogo.style.display = 'none';
                    if (boxText) boxText.style.display = 'none';
                    if (boxImage) boxImage.style.display = 'block';
                    if (pvCustom) pvCustom.style.display = 'none';
                    if (pvBanner) pvBanner.style.display = 'block';
                    if (lblCustom) { lblCustom.style.borderColor = '#e2e8f0'; lblCustom.style.background = '#fff'; }
                    if (lblImage) { lblImage.style.borderColor = 'var(--primary)'; lblImage.style.background = '#eff6ff'; }
                } else {
                    if (boxLogo) boxLogo.style.display = 'block';
                    if (boxText) boxText.style.display = 'block';
                    if (boxImage) boxImage.style.display = 'none';
                    if (pvCustom) pvCustom.style.display = 'block';
                    if (pvBanner) pvBanner.style.display = 'none';
                    if (lblCustom) { lblCustom.style.borderColor = 'var(--primary)'; lblCustom.style.background = '#eff6ff'; }
                    if (lblImage) { lblImage.style.borderColor = '#e2e8f0'; lblImage.style.background = '#fff'; }
                }
            }

            function updatePreviewLogo() {
                const showLeft = document.getElementById('chk_show_logo_left')?.checked;
                const showRight = document.getElementById('chk_show_logo_right')?.checked;

                const leftWrap = document.getElementById('preview_logo_left_wrapper');
                const rightWrap = document.getElementById('preview_logo_right_wrapper');
                const spacerLeft = document.getElementById('preview_spacer_left');
                const spacerRight = document.getElementById('preview_spacer_right');

                if (leftWrap) leftWrap.style.display = showLeft ? 'flex' : 'none';
                if (rightWrap) rightWrap.style.display = showRight ? 'flex' : 'none';

                if (spacerLeft) spacerLeft.style.display = (!showLeft && showRight) ? 'block' : 'none';
                if (spacerRight) spacerRight.style.display = (!showRight && showLeft) ? 'block' : 'none';
            }

            function updateLivePreviewText() {
                const l1 = document.getElementById('input_kop_line1')?.value || '';
                const l2 = document.getElementById('input_kop_line2')?.value || '';
                const l3 = document.getElementById('input_kop_line3')?.value || '';
                const l4 = document.getElementById('input_kop_line4')?.value || '';
                const l5 = document.getElementById('input_kop_line5')?.value || '';

                const docTitle = document.getElementById('input_clearance_title')?.value || 'SURAT KETERANGAN BEBAS PUSTAKA';
                const noFormat = document.getElementById('input_clearance_format')?.value || '421.5/PERPUS-SMK5/BP/{ROMAN}/{YEAR}/{NO}';
                let introTxt = document.getElementById('input_clearance_intro')?.value || 'Kepala Perpustakaan {SEKOLAH} dengan ini menerangkan nama dibawah berikut :';

                const schoolName = l3 || <?=json_encode($schoolTitle)?>;
                introTxt = introTxt.replace('{SEKOLAH}', schoolName);

                const elL1 = document.getElementById('pv_line1');
                const elL2 = document.getElementById('pv_line2');
                const elL3 = document.getElementById('pv_line3');
                const elL4 = document.getElementById('pv_line4');
                const elL5 = document.getElementById('pv_line5');

                if (elL1) { elL1.textContent = l1; elL1.style.display = l1 ? 'block' : 'none'; }
                if (elL2) { elL2.textContent = l2; elL2.style.display = l2 ? 'block' : 'none'; }
                if (elL3) { elL3.textContent = l3; elL3.style.display = l3 ? 'block' : 'none'; }
                if (elL4) { elL4.textContent = l4; elL4.style.display = l4 ? 'block' : 'none'; }
                if (elL5) { elL5.textContent = l5; elL5.style.display = l5 ? 'block' : 'none'; }

                const elDocTitle = document.getElementById('pv_doc_title');
                if (elDocTitle) elDocTitle.textContent = docTitle;

                const elDocNo = document.getElementById('pv_doc_no');
                if (elDocNo) {
                    const romans = ['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'];
                    const now = new Date();
                    const curRoman = romans[now.getMonth()];
                    const curYear = now.getFullYear();
                    let sampleNo = noFormat;
                    if (sampleNo.indexOf('{') !== -1) {
                        sampleNo = sampleNo.replace('{ROMAN}', curRoman).replace('{YEAR}', curYear).replace('{NO}', '0018').replace('{ID}', '18');
                    } else {
                        sampleNo = sampleNo.replace(/\/+$/, '') + '/' + curRoman + '/' + curYear + '/0018';
                    }
                    elDocNo.textContent = sampleNo;
                }

                const elIntro = document.getElementById('pv_intro_text');
                if (elIntro) elIntro.textContent = introTxt;
            }

            function previewUploadImage(input, targetImgId, liveImgId) {
                if (input.files && input.files[0]) {
                    const reader = new FileReader();
                    reader.onload = function(e) {
                        const target = document.getElementById(targetImgId);
                        const live = document.getElementById(liveImgId);
                        if (target) target.src = e.target.result;
                        if (live) live.src = e.target.result;
                    };
                    reader.readAsDataURL(input.files[0]);
                }
            }
            </script>
        <?php endif; ?>

