            <script>
            function togglePassVisibility(inputId, btn) {
                const inp = document.getElementById(inputId);
                if (inp.type === 'password') {
                    inp.type = 'text';
                    btn.textContent = 'Sembunyikan';
                } else {
                    inp.type = 'password';
                    btn.textContent = 'Lihat Password';
                }
            }

            function checkPassStrength(val) {
                const bar = document.getElementById('pass_strength_bar');
                const txt = document.getElementById('pass_strength_text');
                if (!val) {
                    bar.style.width = '0%';
                    bar.style.background = '#e2e8f0';
                    txt.textContent = 'Kekuatan password: Minimal 6 karakter.';
                    txt.style.color = 'var(--text-muted)';
                    return;
                }
                let score = 0;
                if (val.length >= 6) score += 25;
                if (val.length >= 8) score += 25;
                if (/[A-Z]/.test(val) && /[a-z]/.test(val)) score += 25;
                if (/[0-9]/.test(val) || /[^A-Za-z0-9]/.test(val)) score += 25;

                bar.style.width = score + '%';
                if (score <= 25) {
                    bar.style.background = '#ef4444';
                    txt.textContent = 'Kekuatan: Lemah (tambahkan variasi karakter)';
                    txt.style.color = '#ef4444';
                } else if (score <= 50) {
                    bar.style.background = '#f59e0b';
                    txt.textContent = 'Kekuatan: Sedang (tambahkan huruf besar/angka)';
                    txt.style.color = '#f59e0b';
                } else if (score <= 75) {
                    bar.style.background = '#3b82f6';
                    txt.textContent = 'Kekuatan: Baik';
                    txt.style.color = '#3b82f6';
                } else {
                    bar.style.background = '#10b981';
                    txt.textContent = 'Kekuatan: Sangat Kuat & Aman';
                    txt.style.color = '#10b981';
                }
                checkPassMatch();
            }

            function checkPassMatch() {
                const n = document.getElementById('new_pass_input').value;
                const c = document.getElementById('conf_pass_input').value;
                const msg = document.getElementById('pass_match_msg');
                if (!c) {
                    msg.textContent = '';
                    return;
                }
                if (n === c) {
                    msg.textContent = '✓ Konfirmasi password cocok.';
                    msg.style.color = '#16a34a';
                } else {
                    msg.textContent = '✕ Konfirmasi password belum sama.';
                    msg.style.color = '#dc2626';
                }
            }

            function validateAdminPassForm() {
                const n = document.getElementById('new_pass_input').value;
                const c = document.getElementById('conf_pass_input').value;
                if (n.length < 6) {
                    alert('Password baru minimal harus 6 karakter.');
                    return false;
                }
                if (n !== c) {
                    alert('Konfirmasi password tidak cocok dengan password baru.');
                    return false;
                }
                return true;
            }
            </script>
        <?php endif; ?>

