// ==========================================================================
// 16B. PAGE: CADANGAN & BACKUP DATABASE MULTI-FOLDER (ADMIN)
// ==========================================================================
if ($page === 'backup' || $page === 'admin_backup' || $page === 'backup_database') {
    auth('admin');

    // Handler Unduh File Backup .sql
    if (isset($_GET['download'])) {
        $df = basename($_GET['download']);
        if (preg_match('/^perpustakaan_backup_.*\.sql$/', $df)) {
            $dirs = get_perpus_backup_dirs();
            $filepath = null;
            foreach ($dirs as $d) {
                if (file_exists($d . DIRECTORY_SEPARATOR . $df)) {
                    $filepath = $d . DIRECTORY_SEPARATOR . $df;
                    break;
                }
            }
            if ($filepath && file_exists($filepath)) {
                if (ob_get_level()) ob_end_clean();
                header('Content-Description: File Transfer');
                header('Content-Type: application/sql');
                header('Content-Disposition: attachment; filename="' . $df . '"');
                header('Expires: 0');
                header('Cache-Control: must-revalidate');
                header('Pragma: public');
                header('Content-Length: ' . filesize($filepath));
                readfile($filepath);
                exit;
            }
        }
        flash('File backup tidak ditemukan atau nama file tidak valid.', 'error');
        header('Location: ' . u('index.php?page=backup'));
        exit;
    }

    // Handler POST: Buat Backup Baru Sekarang
    if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['buat_backup_sekarang'])) {
        checkcsrf();
        $res = buat_backup_perpustakaan('manual_admin_dashboard');
        if (!empty($res['success'])) {
            flash("Cadangan database perpustakaan ({$res['filename']}) berhasil dibuat dan disimpan di " . count($res['locations']) . " lokasi aman!", 'success');
        } else {
            flash($res['pesan'] ?? 'Gagal membuat cadangan database.', 'error');
        }
        header('Location: ' . u('index.php?page=backup'));
        exit;
    }

    // Handler POST: Pulihkan (Restore) Database
    if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['restore_backup_sekarang'])) {
        checkcsrf();
        $filepath_restore = '';
        $source_label = '';

        // Pilihan 1: Upload file .sql mandiri
        if (isset($_FILES['file_sql_upload']) && $_FILES['file_sql_upload']['error'] === UPLOAD_ERR_OK) {
            $ext = strtolower(pathinfo($_FILES['file_sql_upload']['name'], PATHINFO_EXTENSION));
            if ($ext === 'sql') {
                $filepath_restore = $_FILES['file_sql_upload']['tmp_name'];
                $source_label = 'file upload ' . htmlspecialchars($_FILES['file_sql_upload']['name']);
            } else {
                flash('File yang diunggah harus berekstensi .sql!', 'error');
                header('Location: ' . u('index.php?page=backup'));
                exit;
            }
        } elseif (!empty($_POST['file_backup_pilihan'])) {
            // Pilihan 2: Pilih dari daftar file cadangan tersimpan
            $chosen = basename($_POST['file_backup_pilihan']);
            if (preg_match('/^perpustakaan_backup_.*\.sql$/', $chosen)) {
                $dirs = get_perpus_backup_dirs();
                foreach ($dirs as $d) {
                    if (file_exists($d . DIRECTORY_SEPARATOR . $chosen)) {
                        $filepath_restore = $d . DIRECTORY_SEPARATOR . $chosen;
                        $source_label = 'file tersimpan ' . $chosen;
                        break;
                    }
                }
            }
        }

        $targetDb = trim($_POST['target_database'] ?? '');
        $confirmProd = trim($_POST['konfirmasi_restore_produksi'] ?? '');

        if (!empty($filepath_restore)) {
            $res_restore = pulihkan_database_perpustakaan($filepath_restore, $targetDb, $confirmProd);
            if (!empty($res_restore['success'])) {
                flash("Database `{$targetDb}` BERHASIL dipulihkan utuh 100% dari {$source_label}!", 'success');
            } else {
                flash("Gagal memulihkan database: " . ($res_restore['pesan'] ?? 'Kesalahan tidak diketahui'), 'error');
            }
        } else {
            flash('Silakan pilih salah satu file cadangan yang tersedia atau unggah file .sql.', 'warning');
        }
        header('Location: ' . u('index.php?page=backup'));
        exit;
    }

    // Handler POST: Hapus File Backup
    if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['hapus_backup_file'])) {
        checkcsrf();
        $fn_hapus = basename($_POST['filename_hapus'] ?? '');
        if (hapus_file_backup_perpustakaan($fn_hapus)) {
            flash("File cadangan {$fn_hapus} berhasil dihapus dari seluruh folder penyimpanan.", 'success');
        } else {
            flash("Gagal menghapus file cadangan {$fn_hapus}.", 'error');
        }
        header('Location: ' . u('index.php?page=backup'));
        exit;
    }

    // Data cadangan untuk tampilan
    $backup_dirs_info = get_perpus_backup_dirs();
    $semua_file_backup = daftar_file_backup_perpustakaan();

    render_app_layout('admin', 'backup', 'Backup Database', function() use ($backup_dirs_info, $semua_file_backup) {
        ?>
        <!-- HEADER OVERVIEW & STATUS 3 LOKASI AMAN -->
        <div class="card-box" style="margin-bottom:20px; background:linear-gradient(135deg, #f0fdf4 0%, #e6fcf5 100%); border:1px solid #b2f2bb; padding:20px 24px;">
            <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:14px;">
                <div style="display:flex; align-items:center; gap:14px;">
                    <div style="width:48px; height:48px; border-radius:12px; background:#087f5b; color:#fff; display:flex; align-items:center; justify-content:center; flex-shrink:0;">
                        <?=icon('database', '', 26)?>
                    </div>
                    <div>
                        <h3 style="margin:0; color:#087f5b; font-size:18px; font-weight:800; display:flex; align-items:center; gap:8px;">
                            Sistem Cadangan &amp; Pemulihan Database Perpustakaan Multi-Folder
                        </h3>
                        <p style="margin:4px 0 0; color:#2b8a3e; font-size:13px; line-height:1.5;">
                            Data perpustakaan Anda <b>100% aman</b> dari risiko error, crash, atau uninstalasi XAMPP. Setiap pencadangan otomatis diduplikasi ke folder di luar instalasi XAMPP.
